WordHunterWoW_QuestEN[93009] = { title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nSeek the smallest house.\nWhere pawsteps mark the sand.\nNow dig where dogs lie.\n\nGood luck!", objectives = "Solve the riddle and find the treasure.", completion = "Well done!" }
WordHunterWoW_QuestEN[93010] = { title = "The Serpent Shrine", description = "Here! De note says Ula'tek was sealed away by de Amani. To break de seal, one needs a \"key.\"\n\n<Zul'jan flips through the notes.>\n\nDe key was hidden within a shrine and protected with ancient magic. But which shrine... \n\n<Zul'jan looks up.>\n\nDidn't de tablets at Numazon mention a shrine bein' \"dedicated to de serpent's victory?\" We know from de visions in Harandar dat Ula'tek was a serpent. \n\nDat must be it! De key is hidden at de serpent shrine in Atal'Aman!", objectives = "" }
WordHunterWoW_QuestEN[93011] = { title = "Legacy of the Amani", description = "If Malacrass was right, de key to Ula'tek should be right here.\n\n<Zul'jan's heavy hammer thumps onto the shrine for emphasis.>\n\nIt may take me some time to break through de stone to find it.\n\nI don't know what kind of protection de ancestors have in place, but you will have to deal with dem while I work.\n\nI admit, I did not believe de visions in Harandar. I don't fully trust Malacrass's notes either.\n\nBut if de key is here, dat would be undeniable proof dat what we are chasing is real.", objectives = "" }
WordHunterWoW_QuestEN[93012] = { title = "Dead End", description = "After the meeting in Harandar, I came here to speak with Zul'jarra about the vision you witnessed. Zul'jan had seemed upset when you left and it was not my intent to make him so.\n\nBut all of that can wait. Now that you're awake, you should go speak to Zul'jarra. She wants to know what happened at Atal'Aman.", objectives = "" }
WordHunterWoW_QuestEN[93018] = { title = "Them That Were Lost", description = "My brother is here. And so are de captives.\n\nDey are bein' held in de small shrines ahead. For what, I don't know.\n\nBut somehow my brother is involved.\n\nGettin' my people free of dis place is of de highest priority. Do whatever is necessary to free dem.\n\nZul'jan can wait until de prisoners are safe.", objectives = "" }
WordHunterWoW_QuestEN[93019] = { title = "Situation Normal, All Snaked Up", description = "<Zul'jarra's hand tightens on her axe.>\n\nWe knew de island was cursed, but is dis de curse? Or has what Zul'jan and Malacrass done brought dem here?\n\nDe answer doesn't matter. We must find and save de ones dey kidnapped--and find my brother.\n\n<Zul'jarra surveys the island stretching out around her. Her eyes narrow.>\n\nI see somethin' ahead. A structure. I'm gonna see if my people are there.\n\nYou protect de people here. Crush de serpents. Grind dem into de ground.\n\nMeet me when you are done.", objectives = "" }
WordHunterWoW_QuestEN[93022] = { title = "Fire, the Only Way to Be Sure", description = "De prisoners need to be rescued, yes, but dis place is an abomination.\n\nWe must cleanse it with de spirit-born fire of Jan'alai.\n\nTake dis totem. It will allow you to wield de breath of our loa.\n\nPurge their nests. And kill de spiteful broodsisters that laid dem!", objectives = "" }
WordHunterWoW_QuestEN[93023] = { title = "Death of Furies", description = "Now only these creatures block our way to...\n\n<Zul'jarra growls softly.>\n\n...to Zul'jan.\n\nDey are protectin' him like he's one of dem. One of their army.\n\nWhether he is or not, we gotta take dem down if we're gonna find out.", objectives = "" }
WordHunterWoW_QuestEN[93024] = { title = "Come With Me", description = "Stay here, hash'ura. I'm goin' in to talk to him.\n\nMaybe I can talk him into leavin' on his own--and tellin' us what Malacrass has planned.\n\nI hope to de loa that he will come to his senses.", objectives = "" }
WordHunterWoW_QuestEN[93025] = { title = "Words 9", description = "", objectives = "" }
WordHunterWoW_QuestEN[93043] = { title = "When Predator Becomes Prey", description = "Such a strong will to survive, even when trapped in a cage. \n\nDo not underestimate your prey, {name}. They can strike at any time.\n\nOur friend here will be more than willing to demonstrate, I am sure...", objectives = "Survive an ambush by your prey.", progress = "Speak with Astalor Bloodsworn to continue.", completion = "I can assure you that it will seldom be this easy." }
WordHunterWoW_QuestEN[93047] = { title = "Butchery Basics", description = "We can't keep up with how much these soldiers eat. Lend us just a bit of your time to feed dis army, hm?\n\nWe need boar. Not just a steak or two, we need de entire boar. Nothin' goes to waste, yah?", objectives = "Collect 10 Boar Carcasses.", progress = "De art of Amani huntin' is about discipline. You practice until de skills come as naturally as breathin'.\n\nBut right now, discipline means doin' what I tell you.", completion = "You are an impressive hunter, dat is for sure. Thank you for helpin' us out here." }
WordHunterWoW_QuestEN[93048] = { title = "Got No Rhythm", description = "Dat boy Kovu stormed out of here without even tryin' a single step. He thinks he's got two left feet, but he isn't even willin' to try.\n\nYou look like an impressive fighter. He'll respect you for dat.\n\nMaybe he just needs de right dance partner to show him de steps. Help him out, hm?", objectives = "Teach Kovu how to dance.", progress = "Makin' progress, yah?", completion = "Dat boy still needs a lot of practice, but you helped him get out of his head and just feel de rhythm." }
WordHunterWoW_QuestEN[93049] = { title = "Homework Support", description = "<The little girl keeps her voice low, making sure her father doesn't overhear.>\n\nMy friends are goin' out to play down where de shade lilies grow, but I'm supposed to do a buncha borin' apothecary stuff.\n\nPapa wants me to collect some plants to make salves and balms we use for healin'. I asked if it could wait and he said no.\n\nWhat if... you helped me out? Just dis once, pleeease?", objectives = "Collect 15 Pristine Shade Lilies and 8 Dragonhawk Fern Fronds.", progress = "Did you get all of dem?", completion = "All in perfect condition!\n\nMaybe you should be de apprentice instead." }
WordHunterWoW_QuestEN[93050] = { title = "Altar History", description = "De altars need to be infused with de power of de loas every so often.\n\nI'm not as spry as I used to be and de altars are all spread out.\n\nHelp an old shaman out, eh? I'll give you my totem to channel de loas' power into de altars.\n\nAnd maybe you can learn a thing or two from de other acolytes and myself in de process.", objectives = "Empower the 4 Loa Altars.", progress = "I just need to take a little breather here.\n\nDon't go worryin' about me, now. Keep focused on the task at hand, eh?", completion = "My days of combat are behind me, but I'm glad to be helpin' out around de village." }
WordHunterWoW_QuestEN[93051] = { title = "The Final Exam", description = "My trainin' is almost complete!\n\nMy commander says I need to prove myself against a strong fighter before she can recommend me for combat.\n\nBut I've been strugglin' to find someone willin' to spar with me after... uh, after what happened de last time...\n\nYou look capable. And intimidatin'. Mind helpin' me out here?\n\nAnd no goin' easy on me, yes? I can take it.", objectives = "Spar Dar'rak for his final exam.", progress = "Do not pull even a single punch. De boy must succeed or fail on his own.\n\nIf he's not ready, you will be doin' him no favors sendin' him into the fray unprepared.", completion = "You fought well.\n\nYour own strength proved Dar'rak can hold his own against warriors far stronger than himself.\n\nI never expected him to beat you, <name>. But de fact that he still breathes is an impressive enough feat, hm?" }
WordHunterWoW_QuestEN[93055] = { title = "Extracurriculars", description = "{name}, how fares your journey through this timeline?\n\nShould you wish to explore history further, Khadgar and Eternus may be able to show you more quests that the champions of Azeroth previously experienced.", objectives = "Speak with Khadgar in Dalaran and Eternus at the Infinite Bazaar.", progress = "Back so soon? Perhaps I miscalculated how long you would spend procrastinating.", completion = "Hopefully this diversion has been enlightening." }
WordHunterWoW_QuestEN[93056] = { title = "A Lesson in Alacrity", description = "You are exceeding expectations, {name}.\n\nEven still, let us not tarry. I will teach you what I know so that we may expedite your journey.\n\nHowever, all good things come with time. You are not yet ready for my strongest blessings.", objectives = "Reach level 70.", completion = "Yes, now you are prepared." }
WordHunterWoW_QuestEN[93057] = { title = "A House For You", description = "<A glowing parchment appears in front of you with the symbol of a home in front of it.>\n\nGreetings, {name}!\n\nHave you ever wanted to own a home? Have a place to call your own? Now you can!\n\nJoin us in Founder's Point, the new Housing Neighborhood. Get your very own slice of Azeroth!", objectives = "Travel to your capital city's portal room to find a portal to a neighborhood.\n\nYou can also travel to a housing neighborhood from the housing Dashboard." }
WordHunterWoW_QuestEN[93063] = { title = "Broken Spears", description = "De spirits, their weapons--I recognize dem! Dey are Amani: heroes and warriors from our murals and stories! Dis was de site of a great battle--one dat earned us de right to call dis land Zul'Aman. \n\nWe should bring evidence of our history back to the others watchin' Zul'jarra, to remind 'em we got our ancestors watchin' over us.\n\nTakin' de raised spirits' weapons may \"raise some spirits\" back at camp, no?", objectives = "" }
WordHunterWoW_QuestEN[93064] = { title = "Awe of She", description = "It's the priestess again--the one whose remains we found in the crypt.\n\nThese memories--no. Not memories. They are like nightmares. Something horrible befell the goddess. We must see it directly. Hear her song through all the noise.\n\nI fear this vision will be too much for me alone. Join me, both of you, and let us witness the goddess' past terror.", objectives = "" }
WordHunterWoW_QuestEN[93071] = { title = "Rotten to the Core", description = "", objectives = "" }
