WordHunterWoW_QuestEN[93091] = { title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nDeep in the forest.\nWhere the hookah haze rises.\nTreasure waits below.\n\nGood luck!", objectives = "Solve the riddle and find the treasure.", completion = "Well done!" }
WordHunterWoW_QuestEN[93093] = { title = "Gnarldin Trophies", description = "I was sent here to prove dat I am ready to be an Amani warrior. All dat want de honor must prove demselves.\n\nI chose de gnarldin since dey are close now, and I heard Zul'jarra softened dem up a little.\n\nLooks like I wasn't de only one who thought dat and was wrong.\n\nBut I still need to collect as many trophies from de gnarldin as possible.\n\nIf I have de bigshot hash'ura helpin' me, there's no way I can lose, no?\n\nYou get de trophies. I will stay behind to watch our backs.", objectives = "Recover 35 trophies from gnarldin and their allies.", progress = "Did you get de trophies? De gnarldin have plenty of dem from all their fightin'.", completion = "Dat... dat is a lot of trophies there, hash'ura." }
WordHunterWoW_QuestEN[93094] = { title = "Scavenged Victory", description = "Many warriors have chosen to face de gnarldin since dey came to Zul'Aman, but many have failed.\n\nDey thought now dat de gnarldin are in our territory and weakened, dey would be easier...\n\nDe gnarldin hunters have collected tablets from de Amani hunters dat fell here.\n\nBut with you at my side, we can get \"vengeance\" for those dat lost their lives here--no killin' or life riskin' required.\n\nWe don't have to kill de gnarldin. We just have to get close enough to gather de tablets. What do you say?", objectives = "Recover 6 Hunter's Tablets from fallen Amani.", progress = "With those tablets, no one can question our strength!", completion = "Dis is plenty!\n\nAll of dem were actually dead... right?" }
WordHunterWoW_QuestEN[93095] = { title = "Bitter Fury", description = "De leader of de gnarldin here is known as Tusk Taker. Take a wild guess why she's named dat.\n\nThere is a trophy dis one has in a cave. Take it, and she will run out rarin' for a fight.\n\nDefeat her for me, and no one can challenge my right to be an Amani warrior.", objectives = "Steal Tusk Taker's Taken Tusk Trophy to lure her out, then defeat her.", progress = "Did you kill Tusk Taker yet?", completion = "Hah! Tusk Taker is dead!\n\nDe others will see me as a true Amani warrior now--when I tell them I took all de trophies that killed Tusk Taker." }
WordHunterWoW_QuestEN[93096] = { title = "Amani Honor", description = "Dat is all de trophies we need.\n\nI'll take dem to de meetin' point nearby. All we gotta do is wait there for Huntmaster Jinki to show up.\n\nCome!", objectives = "Meet Kel'vujo at the meeting point to receive your reward from Huntmaster Jinki.", completion = "Dis is a shameful fate for Kel'vujo, but one dat he chose.\n\nYou, hash'ura, have proven once again to be strong. \n\nTake dis as thanks for helpin' to weed out de weak and unfit from our warriors." }
