WordHunterWoW_QuestEN[93120] = { title = "Infinite Research: Special Assignment, A World to Explore", description = "This is my final special assignment for you, {name}.\n\nThere is an entire world--an entire timeline--left for you to explore.\n\nOur work carries on. We must leave no corner of the world unexamined.", objectives = "Complete 10 World Quests.", progress = "With great power comes, in this timeline, even more power.", completion = "Excellent progress. Here are the spoils of your victory." }
