WordHunterWoW_QuestEN[93171] = { title = "Calling All Combatants!", description = "<You read a nearby advertisement...>\n\nRun, don't walk!\n\nThe Artisan's Consortium has teamed up with local Silvermoon artisans in Falconwing Square to offer a new selection of heraldries and crafted equipment. These are certified for use in arenas and battlegrounds, guaranteed!\n\nHead on down and look for Mirvedon to receive your free sample today.\n\nAct now while supplies last! Terms and conditions apply.\n\n-Aisha", objectives = "" }
WordHunterWoW_QuestEN[93178] = { title = "A Quiet Walk Interrupted", description = "It is de hash'ura! De favored of our wily loa! Maybe you can help...\n\nMy father, Oban, is ill and I have been givin' him all my attention.\n\nWhen I turned my back an hour ago, my daughter, Kanza, had run off!\n\nI searched de village, but I can't go further and leave my father behind.\n\nPlease, find where she went? She can be on her own, but she's a sensitive girl, and I don't want her goin' far.\n\nDat fool boy Haz'kel wouldn't come down, but he may have seen her leave. Ask him first.", objectives = "Help Nerunda find Kanza's whereabouts in Zul'Aman.", progress = "I'm so worried about Kanza!\n\nShe shouldn't be on her own.", completion = "What was she doin' out past de log bridge? I told her not to go there.\n\nAnd with my basket and our best tea kettle?\n\nOh... oh, no. She wouldn't! And alone?" }
WordHunterWoW_QuestEN[93179] = { title = "Childlike Devotion", description = "She's goin' to Filo's shrine. She's too old for dat. She's almost thirteen--an adult.\n\nFilo is de Loa of Childhood and protects children. Parents pray to Filo for healthy children.\n\nIt is even said if a child dies, Filo waits with a child in de afterlife until their parents claim dem.\n\nDat is superstition, but dat's why she's goin'.\n\nWe lost her twin, Janaka. She must think she's with Filo.\n\nThe way to Filo's shrine is dangerous, and dat loa won't speak to her. Do what you can to bring her home!", objectives = "Find Kanza at the Shrine of Filo.", progress = "<Kanza eyes you uncertainly.>", completion = "<You do not want to take the child back by force, but perhaps you can persuade her by to listen to you by helping her with what she is trying to accomplish here.\n\nJudging by the items arrayed before Filo's shrine, she is preparing some sort of ritual.\n\nPerhaps if you help her with the ritual, she may go with you--or go home on her own.>" }
WordHunterWoW_QuestEN[93180] = { title = "Shrine Preparations", description = "<Kanza makes no sound but briefly meets your gaze. She points off toward the hot spring pools.\n\nMaybe she wants you to do something there?>", objectives = "Follow Kanza and help her by killing 4 Stinger Matriarchs, 6 Stinger Hatchlings, and by collecting 20 Thorncaps.", progress = "<Kanza shifts her weight from foot to foot, swaying impatiently.>", completion = "<Kanza claps and jumps up and down excitedly.\n\nBut she pulls at your sleeve and makes an arcing motion with her hand, pointing into the far distance.\n\nThere is something else she wants you to do.>" }
WordHunterWoW_QuestEN[93181] = { title = "Temple and a Teapot", description = "<Kanza is dancing with excitement.\n\nShe holds her small hand with one finger up.\n\nOne last thing to do.\n\nYou must almost be ready for the ritual to summon Filo--if that is indeed what she is asking for your help to do.\n\nShe fishes in her tunic for something and presents an object to you: the broken handle of a teapot, presumably from the one she dropped on the way here.\n\nPerhaps she needs a substitute?>", objectives = "Buy a teapot from a vendor in nearby Camp Stonewash and help Kanza start the ritual.", progress = "<Kanza looks nervous and expectant.>", completion = "I had to see her.\n\nJust one more time." }
WordHunterWoW_QuestEN[93182] = { title = "Healing Homeward", description = "I will go home.", objectives = "Return to Nerunda in Witherbark Bluffs and check if Kanza returned home.", completion = "I don't know what you did or what de loa did, but I got my Kanza back and more.\n\nShe is talkin' again like she used to. More even. She never talked a lot.\n\nAnd I'm goin' to make her a place where she feels safe to keep talkin' to me." }
WordHunterWoW_QuestEN[93199] = { title = "Slithering in the Mire", description = "De Children of Ula'tek overwhelmed de swamp and its inhabitants. Dey kill anything in their path, just to increase their numbers and expand their holdings.\n\nDo what you can to reduce their numbers. Keep dem distracted and occupied. I'll sneak ahead and look for Wa'kani and de other scouts.", objectives = "" }
WordHunterWoW_QuestEN[93200] = { title = "A Handful of Voidlight Marl", description = "", objectives = "We're grateful for your help. Take these supplies as a gesture of thanks." }
WordHunterWoW_QuestEN[93229] = { title = "Fried Eggs", description = "De snakes are focused on two things: killin' and reproducin'. Dey took over dis part of de swamp, leaving nothing livin' in their path and layin' eggs all over de place!\n\nBurn any of de eggs you come across. Careful, though. You get too close, dey can burst open, and you don't wanna be anywhere near dem when dat happens.", objectives = "" }
WordHunterWoW_QuestEN[93233] = { title = "Savagery Among the Ruins", description = "De murlocs entrenched demselves in these old ruins. Dey are usually a tough, but cowardly sort. Dis batch is different. Probably gone mad--don't know why, don't care.\n\nClear de ruins while you search. Don't slay their young, though. Dey don't seem to be affected by whatever got de others.", objectives = "" }
WordHunterWoW_QuestEN[93239] = { title = "Scouts in the Swamp", description = "I looked around some more while you were rescuin' Wa'kani. I think de other scouts were taken by de murlocs.\n\nWe'll have to search further into de ruins. I'll circle 'round and see if I can find anything. You're better than me in a fight, so you can search where I can't. Locate de scouts and meet me near de docks.", objectives = "" }
WordHunterWoW_QuestEN[93257] = { title = "Revantusk at Risk", description = "Fishers of de forest tribes constantly talk to each other about our hauls, and none are more legendary than de river-walking Revantusk and their crabs! But...\n\nI've heard they've fallen on hard times. First, de Twilight's Blade ransacked their city. Now, their cages aren't bringing in enough meat for de refugees.\n\nDe Revantusk have a new head river-walker, Kahanea, who could use an extra set of hands in taking care of dis crab problem.\n\nYou up to de task, outsider?", objectives = "Find Kahanea in Nalorakk's Prowl.", completion = "So word of our famine has spread?\n\n<Kahanea grimaces.>\n\nThere is no denying it." }
WordHunterWoW_QuestEN[93258] = { title = "Crab Clues", description = "De rumors are true. No matter what we try, we aren't netting as many crabs as before. And de ones we do catch taste wrong, even making some of my people sick!\n\nI succeeded my mother's position as head river-walker after losing her to de Twilight's Blade. Dealing with dis famine, my new duties, and my grief... It's so much for me to bear.\n\nDis is de area where we first noticed an issue with our crabs. Can you investigate for me while I make more traps?", objectives = "Investigate the lakeshore for causes of the food shortage.", progress = "I must make dis right--for my people. For my mother. I wish she could give us guidance.", completion = "Void-tainted bodies and baskets? And some crazed crabs ambushed you? Dis is getting worse!\n\nNak'tek found de Void polluting baskets upriver, just like what you found down here along de lakeshore. De Void ties all of our clues together! Let's follow that lead." }
WordHunterWoW_QuestEN[93259] = { title = "Clobbering Crawlers", description = "While I continue to scout de area for causes of dis famine, please harvest crab meat for our refugees. Their hunger only gets worse as our investigation goes on.\n\nSince de traps aren't working, you have to hunt those crabs yourself and get food straight from de source!\n\nMake sure you're getting healthy meat, though. I'm worried about some of those crabs being infected with de Void.", objectives = "Harvest 10 pieces of Mouthwatering Crab Meat from the crabs upriver.", progress = "My people have been through so much. Everyone deserves a warm home to return to, and a hearty meal to restore their strength and spirit.", completion = "Dis is more meat than we've seen in a week! My people will be grateful for an actual meal. You have my gratitude." }
WordHunterWoW_QuestEN[93260] = { title = "Caging Crawlers", description = "Our traps being mucked up with de Void would explain why we've been catching fewer crabs! And why some of de crabs have made our people sick.\n\nPlease clean our traps upriver! Based on Nak'tek's report, de infected crabs sound dangerous... so be careful approaching those traps.\n\nYou can find de baskets nestled among de sticks or by bases of waterfalls--dey provide a natural disguise! Crabs are easily tricked dat way.", objectives = "Clean 6 Crab Traps upriver.", progress = "Were you able to clean any of de traps? Or find a source of de filth gumming them up?", completion = "Those shards you found must've caused de Void pollution clogging our traps. I'm glad you removed them! De river looks much cleaner, and our trap count is back to normal... for now.\n\nMay these baskets receive Nalorakk's blessing and provide for de Revantusk once more." }
WordHunterWoW_QuestEN[93261] = { title = "A Crab of Unusual Size", description = "I followed de Void pollution trail upriver and spotted a beast before it ran off to its cave: an enormous, void-addled crab. It was shedding those shards dat were polluting de river!\n\nAs long as dis beast lives, it'll keep spreading pollution and infecting crabs with de Void. It must be stopped!\n\nI'd stay and fight, but I must warn everyone at de Overlook.\n\nPlease, {name}. Slay dat crab and remove de source of its corruption before it can hurt more of my people!", objectives = "Defeat the Mania-Crab and remove the source of its corruption.", progress = "I don't know if de Twilight's Blade created dat beast or not, but it needs to GO!", completion = "So de Twilight's Blade hasn't just hurt de Revantusk, but our wildlife as well? We must keep an eye on de cultists and protect Nalorakk's Prowl from their pollution!\n\nDe health of our people and our crabs is my top priority. Seeing my people starve under my watch filled me with rage, and guilt... like I was tarnishing my mother's memory as head river-walker.\n\nYour aid has helped me become de leader my river-walkers need.\n\nThank you, <name>. You're forever welcome with de Revantusk." }
WordHunterWoW_QuestEN[93262] = { title = "Endeavor", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[93263] = { title = "It Just Had to Be...", description = "Malacrass called these creatures the Children of Ula'tek.\n\nThen it is so. My vision led Zul'jan to Ula'tek and from Ula'tek to Malacrass. Together, they must seek her.\n\nI will do whatever is in my power to help, and make this right for Zul'jarra and her people.\n\nLet us kill as many of these monsters as we can.\n\nWe will fight side by side and uproot this shared foe.", objectives = "" }
WordHunterWoW_QuestEN[93265] = { title = "Severing the Serpent's Head", description = "<Zul'jarra is covered in sweat, blood, and venom. Her face is grim in a way you haven't seen before.>\n\nI need your help.\n\nI ordered soldiers to move to a hut in de north as a lookout and to protect some Witherbark civilians trapped there.\n\nBut one of de monster brutes caught their scent. Kill it and rescue de civilians before dey end up like Dak'zor!\n\nI will stay here and make sure none of these snakes get into de lodge.", objectives = "" }
WordHunterWoW_QuestEN[93266] = { title = "Drumming Up the Troops", description = "De loa have blessed our battle!\n\nNalorakk and Halazzi are rippin' at their flanks. Akil'zon and Jan'alai are knockin' dem from de skies.\n\nWe will stay to de ground and push through de center--all of us--and rid Zul'Aman of these pests.\n\nSound de drums again, hash'ura. Call our warriors to de battle in Atal'Aman. Now we are united and dey will heed us!", objectives = "" }
