WordHunterWoW_QuestEN[93339] = { title = "Trinket Trading", description = "I've never seen murlocs dis vicious. A few of dem are holdin' something feathered dat glints green. Dat might be de source of de darkness I sense.\n\nWhen you're out among de ruins, keep your eyes open for these objects. I think de murlocs unearthed somethin' dat's got them going mad.", objectives = "" }
WordHunterWoW_QuestEN[93340] = { title = "The Shadow Shard", description = "I thought de murlocs were driven into their frenzy by de trinkets, but they're just baubles made by de snakes. Once we drew closer to dat lighthouse, I began to suspect dey were not de cause.\n\nI can feel it from here. A pulsing darkness. Ancient. If you go up there, you may find de true source of de murlocs' madness.", objectives = "" }
