WordHunterWoW_QuestEN[93372] = { title = "Delver's Call: Shadow Enclave", description = "The perfidious cultists of the Twilight's Blade have infiltrated Eversong and set up their horrid operations in a nearby cavern. Clear them out before they spread any further!", objectives = "Complete the Shadow Enclave delve on any difficulty.", completion = "Good job and good riddance." }
