WordHunterWoW_QuestEN[93382] = { title = "Pardon the Interruption", description = "{name}! Glad to see you. The defenders in the fortress could use your help.\n\nOne of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on.\n\nShe needs the help of someone who can properly disrupt the robot's attacks so it can be repaired.\n\nDo you have a moment to help?", objectives = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 3 times.", completion = "Great work! Now I should have time to fix whatever bug actually caused this in the first place.\n\nMaybe I can just say it's a feature and call it a day!" }
WordHunterWoW_QuestEN[93384] = { title = "Delver's Call: Collegiate Calamity", description = "The arcane tome, clearly agitated by something, bears the mark of Silvermoon's Thalassian University.\n\nIt could be worth investigating.", objectives = "Complete the Collegiate Calamity delve on any difficulty.", progress = "Is something amiss at the university?", completion = "Thank you, <name>. The situation was hardly conducive to study." }
WordHunterWoW_QuestEN[93385] = { title = "Delver's Call: The Darkway", description = "Remnants of the Twilight's Blade scurry like rats through the Arcway tunnels beneath Suramar.\n\nExterminate the vermin before they spread.", objectives = "Complete The Darkway delve on any difficulty." }
WordHunterWoW_QuestEN[93386] = { title = "Delver's Call: Parhelion Plaza", description = "Adventurers! Quel'Danas is once more under attack by the Void, and any who are able to provide assistance should head to the battlements of Parhelion Plaza to help stem the tide.", objectives = "Complete the Parhelion Plaza delve on any difficulty." }
WordHunterWoW_QuestEN[93387] = { title = "Dealing with Pests", description = "Every time I leave my hut, I return to a mess and soggy little murloc footprints.\n\nI am plannin' a different approach to deal with those pestersome amphibian encroachers, but I need to sort out some ingredients.\n\nWhile I work out my list for those pests--there is a ghost named Jelvik dat keeps after me for somethin'. Tell him to move along.", objectives = "" }
WordHunterWoW_QuestEN[93388] = { title = "Unusual Alchemy", description = "My list is ready. I need you to gather de ingredients to keep dem murlocs away for good.\n\nFirst, talk to Maka de Trawler. He and de kelpweaver from Torga's Beak like to catch fish in de inlet. Bring me some fish guts--disgustin' and perfect.\n\nNext, head out to Mlurkkr Mire. I need dat dirty ol' pearl dey think is so special.\n\nWhile you're in de Mire, relieve some of dem irritatin' serpent folk of some scales.\n\nMind you, I only want de good ones.", objectives = "" }
WordHunterWoW_QuestEN[93389] = { title = "Rocksblood", description = "I've been here so long dat pieces of my memory are lost to time. I feel an emptiness for something I loved.\n\nThere will be no rest for me until I know who or what it was. I can only remember one word... Rocksblood. I don't know who or what dat is.\n\nCheck de murloc ruins to de south. There's someone who can point you in de right direction.\n\nSince Ofi is bein' stubborn, I need you to help me remember.", objectives = "" }
WordHunterWoW_QuestEN[93390] = { title = "Acceptable Apprentice", description = "Dis part is gonna be fun.\n\nI got de mixture started. It is already unpleasant, but now we will make it really vile.\n\nWhen you feel mentally prepared to be a useful one again, let me know.", objectives = "" }
WordHunterWoW_QuestEN[93391] = { title = "Make it Stinky", description = "Best you move our little deterrents out to de strip of land between my home and de maniacs' mire.\n\nThey may try to stop you, but hold fast. If it works, dey will be running with their tails between their legs.\n\nDo murlocs even have tails?", objectives = "" }
WordHunterWoW_QuestEN[93392] = { title = "Recovering Memories", description = "To de northeast, there's a small island. I remember long ago a great roarin' and howlin' dat echoed across de waters.\n\nI could hear de anger, but there was also pain. I could not venture to dat place. What if I became lost, my own feelings swallowed by de bigger ones?\n\nOne day, it became quiet again, but now I feel dis is de final key to de lock on my soul.\n\nGo there. Find de last piece.", objectives = "" }
WordHunterWoW_QuestEN[93393] = { title = "A Little Kindness", description = "You know, my friend, as happy as I am... I keep thinkin' how sad we made dat beast. I do not wish dat feelin' on another livin' soul.\n\nHe took care of dear Sava for all de years she was lost. Could you help us with one last request?\n\nIf you could bring him a friend of his own, it will repay our debt.\n\nThen we can move on once and for all--me and Sava will be free.", objectives = "" }
WordHunterWoW_QuestEN[93396] = { title = "Bursting at the Seams", description = "Veraan... alive...\n\n<Kifaan shakes his head in disbelief.>\n\nI've spent countless hours running this moment through my head, but now that it's here, I find myself grasping for words...\n\nThe Shadowguard attempted to raise Dimensius to power... they've sworn fealty to Xal'atath as she wages war on worlds. Am I supposed to just... pretend none of that happened? Is THAT what my oaths to family require?\n\nAnd what of Veraan? Does she regret her involvement?\n\nI should check on her.", objectives = "Help Kifaan check on his sister's well-being.", completion = "I've been focusing on my own feelings so much that I never stopped to think about how Veraan might feel.\n\nI may not have fared any better had they pumped ME full of Void." }
WordHunterWoW_QuestEN[93397] = { title = "Gnawing Hunger", description = "", objectives = "" }
WordHunterWoW_QuestEN[93400] = { title = "Sugar Run", description = "Ahh, Hallow's End. The perfect time for spooky stories, glowing pumpkins, and sweet, sweet candy!\n\nBut this year, I want to craft something truly unforgettable. A delicious range of candy inspired from regions across Azeroth!\n\nFor that, I've enlisted some help. A certain... eccentric culinary genius. You may know him. I've sent him off to Duskwood in search of haunted recipes that are sure to thrill everyone.\n\nFind him and bring back some of those cursed candies.", objectives = "" }
WordHunterWoW_QuestEN[93401] = { title = "Howling Honey Drops", description = "Quite the risk taker! Honey Drops are delicious, but can be a pain to retrieve - literally! Don't expect a warm welcome from the habitants of the hives that you will be extracting Honey Drops from.", objectives = "" }
WordHunterWoW_QuestEN[93409] = { title = "Delver's Call: Atal'Aman", description = "<The fallen scout's body bears terrible wounds, but still clutches tightly to a report detailing an imminent Vilebranch attack on Atal'Aman.>", objectives = "Complete the Atal'Aman delve on any difficulty.", completion = "Good. They should learn to stay in their holes." }
WordHunterWoW_QuestEN[93410] = { title = "Delver's Call: Twilight Crypts", description = "The ancient Amani crypts near the Broken Throne have been overrun.\n\nClear them of interlopers before the dead within can be defiled further.", objectives = "Complete the Twilight Crypts delve on any difficulty.", completion = "One day Zul'Aman will be free of their taint." }
WordHunterWoW_QuestEN[93413] = { title = "TO DEPRECATE Battle for Zul'jarra", description = "Zul'jan is the one who did this to Zul'jarra. He needs to answer for what he did to his sister.\n\nNow, we gather Zul'jarra's forces. Let them know that her hash'uras have come once again to aid the Amani.", objectives = "" }
WordHunterWoW_QuestEN[93414] = { title = "TO DEPRECATE Bloody Mercy", description = "Has Zul'jan really thrown in his lot with these snakes? I don't understand what possible reason he'd join with these monsters. What promises did they make him?\n\nZul'jan will face retribution in time. But first, these so-called Children of Ula'tek will. We'll carve a swath through them to the temple, together.", objectives = "" }
WordHunterWoW_QuestEN[93416] = { title = "Delver's Call: The Gulf of Memory", description = "Rumors of disturbances in the Gulf of Memory have begun to spread.\n\nDeal with the issue before it can take root.", objectives = "Complete the Gulf of Memory delve on any difficulty.", completion = "Thank you, <name>, for nipping that in the bud." }
WordHunterWoW_QuestEN[93417] = { title = "The Vaults of Atal'Utek: Altar of Fangs", description = "Orweyna told us what she saw...\n\nDamn it, Zul'jan! Does he truly not understand what he's done? Despite what we have accomplished, he sees the bonds Zul'jarra forged with the both of us as weakness and chases this idea of a \"supreme Amani Empire\" still.\n\nAnd in the process, he has gravely wounded his sister.\n\nBut maybe Zul'jarra is right--maybe he doesn't know.\n\nWe have to get that dagger. By making him see sense, or by force.", objectives = "" }
WordHunterWoW_QuestEN[93418] = { title = "The Venomous Abyss", description = "I saw things in de venom haze.\n\nHeard Zul'jan screamin', felt what's eatin' away at him. \n\nHeard Malacrass whisperin' in his ear.\n\nUla'tek has haunted de Amani from de beginning. De lengths we went to for power and empire, and de blood it cost...\n\nDat wasn't greatness. Deep down, Zul'jan knows it too.\n\nMalacrass stole my grandfather from me. I won't let him take Zul'jan too.", objectives = "" }
WordHunterWoW_QuestEN[93419] = { title = "Nature of Her Wounds", description = "The Fang is cursed from the summoning of Ula'tek. We can use it to cure Zul'jarra. I just--\n\nWe have to act fast. She's fading!", objectives = "" }
WordHunterWoW_QuestEN[93420] = { title = "Lor'themar's Judgement", description = "We need to tell Lor'themar what happened here. Meet me in Silvermoon.\n\nAs for Zul'jarra... she needs time. She needs her people, and her people need her.\n\nShe will survive this. I am sure of it. She must!", objectives = "" }
WordHunterWoW_QuestEN[93421] = { title = "Delver's Call: The Grudge Pit", description = "<This moldy hanging has been crudely painted over to depict one fungarian hitting another with what looks to be a chair.>\n\nSee big fight. Best fight!\n\nGrudge Pit. Be there!", objectives = "Complete The Grudge Pit delve on any difficulty.", completion = "Good fight? Yes.\n\nBest fight? Maybe!" }
WordHunterWoW_QuestEN[93423] = { title = "Sparks of War: Eversong Woods", description = "Mysterious creatures are out in the wild across the Eversong Woods. \n\nGo and see what you can find out about them.", objectives = "" }
WordHunterWoW_QuestEN[93424] = { title = "Sparks of War: Zul'Aman", description = "There's unknown danger out in Zul'Aman.\n\nGet out there and clear things up!", objectives = "Collect 100 Sparks of War in Zul'Aman, while in War Mode." }
WordHunterWoW_QuestEN[93425] = { title = "Sparks of War: Harandar", description = "Powerful creatures have grown through the lands across Harandar. Go look into it.", objectives = "Collect 100 Sparks of War in Harandar, while in War Mode.", progress = "There's more to explore.", completion = "That was a tremdenous effort - much thanks." }
WordHunterWoW_QuestEN[93426] = { title = "Sparks of War: Voidstorm", description = "Chaotic forces are being disruptive in the Voidstorm. Go investigate and clear things up!", objectives = "" }
WordHunterWoW_QuestEN[93427] = { title = "Delver's Call: Sunkiller Sanctum", description = "<A note is pinned to the slain voidwalker.>\n\nSunkiller Sanctum is a den of Xal'atath's most pathetic sycophants.\n\nI encourage any mercenaries, adventurers, or general do-gooders who happen upon this bounty to pay it a visit and dispense the justice you are all so happy to talk on and on about.\n\n - Perodius", objectives = "Complete the Sunkiller Sanctum delve on any difficulty.", completion = "Your fee, <class>.\n\nThat will teach them to rebuff a perfectly good bribe in the future." }
WordHunterWoW_QuestEN[93428] = { title = "Delver's Call: Shadowguard Point", description = "Witness the fates of those who bend their neck to Xal'atath.\n\nI issue a challenge to any creature of Void or flesh. Pursue the nearby ethereals and dispatch anyone who serves the so-called Harbinger.\n\n - Perodius", objectives = "Complete the Shadowguard Point delve on any difficulty.", completion = "For services rendered.\n\nIf only all mortals were as helpful as you." }
WordHunterWoW_QuestEN[93432] = { title = "Swords to Plowshares", description = "First Mor'duun and the Blade ambush Atal'Aman. Now it's overrun by these \"echoes...\"\n\nAt least, that's what Doru calls them: echoes. All I see are ghosts of a bloodier time. And like those days, no matter how many we cut through, they never stop swarming in.\n\nGet out there and see for yourself. Bring de echoes' remains as well. Doru wants to study what dey are and how dey work.", objectives = "Collect 20 Raider Ash Remains.", progress = "It's like a dream you can't wake from.", completion = "See? An endless ocean.\n\nPerhaps Doru will learn something from de ashes." }
WordHunterWoW_QuestEN[93433] = { title = "Shrine, Sealed, Delivered", description = "Curse de echoes. \n\nCurse Zul'jin, and Mor'duun, and dat snake Malacrass too.\n\nThey only cause more mess for de livin' to clean up.\n\nListen, hash'ura. I need you to deliver supplies to each of de shrines in de city. We've packaged food, water, bandages, and reagents to keep their barriers at full strength.\n\nAsk about their status as well. Though safe, they all likely feel boxed in.", objectives = "Deliver supplies to the Elders of the four Loa Shrines: Elder Shimarra, Eagletender Rhyd, Elder Thak, and Elder Vu'lona.", completion = "Barriers holdin'? Good.\n\nNow we can focus on de offensive." }
WordHunterWoW_QuestEN[93435] = { title = "Four Instigators", description = "De scouts report seein' a few unique faces among de echoes. I felt old angers rising when I heard de names.\n\nDey were not honorable fighters for us to challenge ourselves against, such as yourself. They were vermin--greedy opportunists that drove legions of connivin' adventurers to rob us of our possessions, our treasures, and... our tusks.\n\nSlayin' de echoes of these key figures should reduce de number of echoes appearin'.\n\nAnd it will make me grin to know they've fallen.", objectives = "Slay the echoes of Prigmon, Zungam, Budd Nedreck, and Harrison Jones.", completion = "I admit it, <name>: knowin' you have slain de instigators brings warmth to my old bones.\n\nDoes dat lower your opinion of me?" }
WordHunterWoW_QuestEN[93436] = { title = "Hex the Innocent, Disrupt the Guilty", description = "I will study de ashes you acquired, but we can get dis situation under control by means other than de axe.\n\nYou must disrupt de battlefield, hash'ura. De echoes believe dey're in de midst of a decades-old battle, so we must target de support dey relied on back then.\n\nPoison de feasts dey find respite at, hex their disrespectful civilian allies, and sabotage dat chest they seem so keen on lootin'!", objectives = "Poison 3 Raider's Feasts, hex 7 Civilians, and sabotage the Warlord's Chest.", completion = "De echoes are runnin' from de battlefield like scared hogs because of your work!" }
WordHunterWoW_QuestEN[93437] = { title = "In Their Own Blood", description = "After studying de ashes, Doru believes we can only fight with de past using weapons of de past.\n\nI cannot ask this of any Amani. Or Witherbark, Revantusk, or Shadowpine. Ya presence with us in these times must be fate... because we could only make this request to an outsider.\n\nYa must inhabit a soul of de profane ones: those that accepted Malacrass's vile bargain and consumed loa power during de era of Zul'jin.\n\nReturn to de shrine of de profane one ya wish to merge with.\n\nAncestors forgive us...", objectives = "Become one of the four Loa Avatars.\n\nSlay Raiding Echoes in Atal'Aman, and defeat the Raid Leader upon the Warlord's Stair.", completion = "Thank you, hash'ura. Truly.\n\nThe battle against de echoes will continue. However, it would seem dey cannot return after being slain now dat their leader has been dealt with.\n\nMemories stirred my blood these last few days. Now we can all rest. Perhaps even move on?\n\nBah! It's just de ravin' of an old warrior. Do not mind me. \n\nSimply consider myself in your debt." }
WordHunterWoW_QuestEN[93438] = { title = "Special Assignment: Precision Excision", description = "", objectives = "" }
WordHunterWoW_QuestEN[93440] = { title = "Personal History", description = "With Mor'duun slain and de Twilight's Blade defeated, my people want to return to Atal'Aman.\n\nIt should be a moment of great celebration but... somethin' unexpected is barrin' our way.\n\nSeek out Torundo and Elder Doru. Dey are supportin' de resettlement. They'll know how best to use your talents.\n\nPrepare yourself, hash'ura, and do not hesitate to defend Atal'Aman no matter who you meet there.", objectives = "Speak with Torundo the Grizzled in Atal'Aman.", completion = "Zul'jarra sent you, hash'ura?\n\nHeh. She must be tired of waitin' on us to make headway." }
WordHunterWoW_QuestEN[93449] = { title = "Trouble in the Swamp", description = "A group of my people went over to Mlurkkr Mire and have not returned. Dey were looking into an incursion of de Children of Ula'tek in de region. There are also troubling reports of de local murlocs actin' more violent than usual, and de priest Wa'kani said she detected a strong dark energy she wanted to check out.\n\nTheir leader, Zawadi, was due to report back an hour ago. Will you go find dem and lend aid if needed?", objectives = "" }
WordHunterWoW_QuestEN[93452] = { title = "Retrieved Crumpled Present", description = "<It seems the minions of the Greench have fled, leaving behind a small mangled, but still salvageable present.\n\nPerhaps one of the Winter Festivities planners would be able to help return it to the original intended recipient.>", objectives = "Talk to Joanna Copperpinch in the Razorwind Shores neighborhood.<It seems the minions of the Greench have fled, leaving behind a small mangled, but still salvageable present.\n\nPerhaps one of the Winter Festivities planners would be able to help return it to the original intended recipient.>You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[93453] = { title = "A Grave Concern", description = "Dearly Departed,\n\nHaving just tasted the bitter sting of mortality, there seems no better time to discuss with you the oft ignored subject of death and memorialization. Of what you leave behind in a real, physical sense.\n\nLeave discussion of love and other such frivolities to the philosophers and dandies. I speak of cold, hard stone and the deeds carved upon it.\n\nFind me in Silvermoon.", objectives = "Meet with Nelthius Shadestone in Silvermoon.", progress = "Have you made your selection?", completion = "Excellent. Feel free to make new arrangements whenever you would like.\n\nI, like death, am a patient man." }
WordHunterWoW_QuestEN[93454] = { title = "Words to Hear", description = "Malacrass helped my grandfather lead de Amani to ruin. Now he's gonna do de same to my brother. If we could just separate de two of them... \n\nBut Jan won't listen.\n\nHe thinks Ula'tek is a weapon dat will bring de return of de Amani Empire. After de vision he saw--and who knows what else Malacrass told him--I can't convince him otherwise.\n\nDe hash'ey requires counsel, my hash'ura. Gather de others and join me.", objectives = "" }
WordHunterWoW_QuestEN[93495] = { title = "A Soaring Journey Through Time", description = "The sands of time flow back and forth like ocean waves.\n\nJourney once more through the timeways, to the time of Dragon Aspects and Primal Incarnates.\n\nBring me tales of victory in an era of great adventure and danger.", objectives = "" }
WordHunterWoW_QuestEN[93497] = { title = "A Soaring Path Through Time", description = "It was a time of forging new alliances and enemies. Reminisce with me about the great Dragon Aspects and their return to glory.\n\nVenture back in time to the Dragon Isles and return with what knowledge you can.", objectives = "" }
WordHunterWoW_QuestEN[93499] = { title = "Enshrouded in Arenas", description = "An important test to being a strong warrior is coordinating with others in combat. Find fellow combatants to join you in battle in the arena.", objectives = "" }
WordHunterWoW_QuestEN[93501] = { title = "The Season Starts: Midnight", description = "Things have started to get interesting, {name}. I'm hearing of all sorts of treasures popping up in delves.\n\nI'm compiling my notes in this book, and our illustrious hosts have even broken out some of their own artifacts to trade for what we uncover.\n\nWhy don't you take a look before we head out. Better prepared than dead.", objectives = "" }
WordHunterWoW_QuestEN[93502] = { title = "Enshrouded Solo", description = "Independence is key to excel in battle. Display your solo capabilities in then come back to me.", objectives = "" }
WordHunterWoW_QuestEN[93503] = { title = "Enshrouded in Teamwork", description = "The ability to work with a group to take objectives is key in training. Practice this on the battlefield.", objectives = "" }
WordHunterWoW_QuestEN[93504] = { title = "Enshrouded in Skirmishes", description = "Practice makers perfect. A great place to practice is with others like yourself looking to practice. Set off and find others like yourself to practice small-scale skirmishes, then return to me.", objectives = "" }
WordHunterWoW_QuestEN[93505] = { title = "Enshrouded in War", description = "Large conflicts get you to take a look at the larger picture. Give it a try then come back to me.", objectives = "" }
WordHunterWoW_QuestEN[93506] = { title = "Enshrouded in Battle", description = "You can learn a lot on the battlefield on your own. Go ahead and see what you observe.", objectives = "" }
WordHunterWoW_QuestEN[93507] = { title = "Disrupting the Void", description = "", objectives = "" }
WordHunterWoW_QuestEN[93511] = { title = "A Missing Member", description = "He took him! Finley...big...purple...man!\n\n<Reno is clearly distraught and both physically and emotionally exhausted.>", objectives = "" }
WordHunterWoW_QuestEN[93514] = { title = "Emissary of the Singularity", description = "", objectives = "" }
WordHunterWoW_QuestEN[93519] = { title = "Midnight Delves!", description = "Things are starting to get interesting in Delves.\n\nCome see me in Silvermoon.", objectives = "" }
WordHunterWoW_QuestEN[93523] = { title = "Short-Supply Reward", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[93524] = { title = "Trench Run", description = "", objectives = "" }
WordHunterWoW_QuestEN[93525] = { title = "Nulling Nullaeus", description = "That thing looked tough, and it took Reno out as an afterthought.\n\nWe'll want the best gear we can get before trying to take it down.\n\nThankfully, I have some leads on bountiful delves we can start with.", objectives = "" }
WordHunterWoW_QuestEN[93548] = { title = "A Trove of Voidlight Marl", description = "", objectives = "" }
WordHunterWoW_QuestEN[93549] = { title = "A Cluster of Voidlight Marl", description = "", objectives = "" }
WordHunterWoW_QuestEN[93566] = { title = "Renowned with the Amani Tribe", description = "You continue to prove yourself to de Amani and de other forest tribes alike.\n\nSpeak to me when next you are in Amani'Zar. Zul'jarra asked me to put a few items aside as our way of sayin' thanks.You will receive:", objectives = "Speak with Magovu in Amani'Zar Village.You continue to prove yourself to de Amani and de other forest tribes alike.\n\nSpeak to me when next you are in Amani'Zar. Zul'jarra asked me to put a few items aside as our way of sayin' thanks.You will receive:" }
WordHunterWoW_QuestEN[93569] = { title = "Exaliburn", description = "", objectives = "" }
WordHunterWoW_QuestEN[93571] = { title = "Dispersing Shadows", description = "", objectives = "" }
WordHunterWoW_QuestEN[93575] = { title = "Maisara Caverns: Maisara Hungers", description = "I will not leave my people to die to de Vilebranch's dark rituals. We must go after dem.\n\nThe heart of Maisara Caverns is where de Vilebranch keep their secrets. I expect dis to be a bloody trip. We will have to face de ugliness of the Vilebranch greed, and what it is costin' all of us.\n\nWe must discover what purpose they have for my stolen kin. If any still be alive. I will be dere to aid you... but bring a fierce party of warriors. We will need it.", objectives = "Complete the Maisara Caverns dungeon.", progress = "Gather your warparty. I will see you in Maisara Caverns.", completion = "Dat be a dark business indeed. So many lost, to such a terrible fate!\n\nBut no more, thanks to you. You have de Witherbark's gratitude... and mine." }
WordHunterWoW_QuestEN[93576] = { title = "The Search for Wa'kani", description = "While you were keepin' de snakes busy, I was lookin' for Wa'kani and de other scouts. De scouts are still missin', but Wa'kani is in dat temple over there.\n\nI tried gettin' closer, but it's too heavily guarded. You should have no problem, though. Please rescue my fool sista before de snakes do something foul to her.", objectives = "" }
WordHunterWoW_QuestEN[93577] = { title = "Captured Instinct", description = "", objectives = "" }
WordHunterWoW_QuestEN[93578] = { title = "Where Shadows Gather", description = "", objectives = "" }
WordHunterWoW_QuestEN[93579] = { title = "Path of Purgation", description = "", objectives = "" }
WordHunterWoW_QuestEN[93581] = { title = "Against Overwhelming Odds", description = "Friends - I sense some troubles out there. There's foes out there that harbor grudges and are looking for a fight. Join others and show those looking for a battle who is mighty.", objectives = "Slay 25 Level 90 Horde anywhere within Midnight." }
WordHunterWoW_QuestEN[93582] = { title = "Against Overwhelming Odds", description = "Friends - I sense some troubles out there. There's foes out there that harbor grudges and are looking for a fight. Join others and show those looking for a battle who is mighty.", objectives = "Slay 25 Level 90 Alliance anywhere within Midnight." }
WordHunterWoW_QuestEN[93586] = { title = "Conditional - Multiple Objectives, Non Sequenced", description = "I be sent out here ta prove dat I can be an amani warrior.\n\nDis trial needs me ta collect as many trophies from dese gnarldin as possible. \n\nDe two of us should work together! I be helpin' you get recognized as an amani warrior, yeah?\n\nJust go out dere and get as many trophies from de gnarldin as possible. \n\nI be stayin' behind ta watch our backs, eh?", objectives = "Recover 1 trophies from gnarldin and their allies." }
WordHunterWoW_QuestEN[93593] = { title = "A Call to Battle", description = "Ours is a world of constant struggle, wouldn't you agree? Even in between times of peace, there is value in keeping one's battle skills sharpened.\n\nI have heard much of your prowess. Let us see what you are capable of.", objectives = "" }
WordHunterWoW_QuestEN[93595] = { title = "A Call to Delves", description = "Seeking out challenge and treasure can test one's skills, all while uncovering that which will give us even greater power.\n\nWere I you, I would delve into places that provide both.", objectives = "" }
WordHunterWoW_QuestEN[93598] = { title = "Emissary of War", description = "It is only when we push ourselves beyond our limits that we truly grow... or fail and make way for others.\n\nProve yourself by challenging the deadliest of places. Shorel'aran.", objectives = "" }
WordHunterWoW_QuestEN[93599] = { title = "The Very Best", description = "Even the smallest amongst us must play their part. That includes our little friends.\n\nIf you would strengthen both their prowess and your bond, challenge others. Only the fittest will survive.", objectives = "Defeat 5 players through Find Battle with a team of level 25 pets." }
WordHunterWoW_QuestEN[93600] = { title = "The Arena Calls", description = "Old, musty dungeons and battlefields are one thing, but the arena is where the wheat and the chaff are separated.\n\nCan you prove yourself, {class}? Show me. Let me hear your name shouted from the stands by those crying for blood.", objectives = "" }
WordHunterWoW_QuestEN[93605] = { title = "The World Awaits", description = "Sinu a'manore, {class}. It is true in the past, I have been less than... egalitarian in my outlook. Yet in these times of trouble, there is much to be done--whether here in Quel'Thalas or elsewhere.\n\nWill you face the challenge and prove yourself once more?", objectives = "" }
WordHunterWoW_QuestEN[93607] = { title = "An Original Path Through Time", description = "Greetings, {class}. You come to me because you seek answers. I have nothing for you but guidance.\n\nPerhaps the answers you seek lie in the past? Return to that time mere years after the conclusion of the Third War. Face its threats once again and see what wisdom you can glean.", objectives = "" }
WordHunterWoW_QuestEN[93608] = { title = "A Burning Path Through Time", description = "On the other side of the Dark Portal lies Outland. I've never been--my history is tied to the Kirin Tor rather than Silvermoon. Yet the elves of Quel'Thalas went through much turmoil during that period of time. \n\nPerhaps you could learn a thing or two from that fractured world. Take up the challenge, if you feel worthy of it.", objectives = "" }
WordHunterWoW_QuestEN[93610] = { title = "A Frozen Path Through Time", description = "The lessons of the past must be revisited from time to time and brought back to the present as a reminder.\n\nWalk the timeways and return to when the Lich King and the armies of the Scourge emerged from the icy wastes of Northrend and threatened all of Azeroth. There is much to be learned from that time.", objectives = "" }
WordHunterWoW_QuestEN[93611] = { title = "A Shattered Path Through Time", description = "The Cataclysm was terrifying for all of Azeroth. The existential threat of Deathwing echoes down through the ages. Isn't it interesting that no matter how things change, such threats return time and time again, but in different forms?\n\nGo back and face those threats again. See if there's something new to learn from the past.", objectives = "" }
WordHunterWoW_QuestEN[93612] = { title = "A Shrouded Path Through Time", description = "My memories of Pandaria are... complicated, {class}. Many lessons were learned during that tumultuous period of time--some good, some painful. \n\nThe world has changed a great deal since then. We've all changed--I hope for the better.\n\nTravel back through the mists of time. Relearn what lessons you can.", objectives = "" }
WordHunterWoW_QuestEN[93613] = { title = "A Savage Path Through Time", description = "Perhaps you can untangle the depth of knowledge to be found in Draenor--not the shattered remains of Outland, but the Draenor of the Iron Horde. It is, in its own ways, just as harsh if not harsher than Outland ever was. \n\nSee what wisdom you can find there.", objectives = "" }
WordHunterWoW_QuestEN[93614] = { title = "A Fel Path Through Time", description = "I have faced many enemies, but the Burning Legion was perhaps the greatest threat our world ever faced. At least... until now.\n\nOf course, there are our inner demons to contend with as well.\n\nDo you still have what it takes to defeat the Burning Legion?", objectives = "" }
WordHunterWoW_QuestEN[93627] = { title = "A Scarred Path Through Time", description = "I remember well the battles of the Alliance and Horde that played out in Kul Tiras and Zandalar. Return there, relive the memories. \n\nWill you seek glory, or knowledge? Or perhaps both?", objectives = "" }
WordHunterWoW_QuestEN[93628] = { title = "A Shadowed Path Through Time", description = "Would you return to the realm of death and risk your very existence? Rebirth, eternal peace, endless torment? All can be found across the veil. \n\nTravel to the Shadowlands once more. If you can defeat its most dangerous places, perhaps you will return to the living wiser and more powerful.", objectives = "" }
WordHunterWoW_QuestEN[93640] = { title = "Fish Finagling", description = "I had wanted to bring the tea set home to my wife to surprise her...\n\nBut that won't make up for me not bringing home any fish for supper.\n\nHm. I'll make a deal with you, {class}. I've been standing here all day trying to catch some fish for my beautiful wife to cook for us. But the crabs keep stealing my catch--and my bait! Run them off so I can catch and keep some fish, and I will give you this teapot.", objectives = "I had wanted to bring the tea set home to my wife to surprise her...\n\nBut that won't make up for me not bringing home any fish for supper.\n\nHm. I'll make a deal with you, <class>. I've been standing here all day trying to catch some fish for my beautiful wife to cook for us. But the crabs keep stealing my catch--and my bait! Run them off so I can catch and keep some fish, and I will give you this teapot." }
WordHunterWoW_QuestEN[93641] = { title = "Against Overwhelming Odds", description = "Friends - I sense some troubles out there. There's foes out there that harbor grudges and are looking for a fight. Join others and show those looking for a battle who is mighty.", objectives = "Slay 25 Level 90 Horde anywhere within Midnight." }
WordHunterWoW_QuestEN[93642] = { title = "Against Overwhelming Odds", description = "Friends - I sense some troubles out there. There's foes out there that harbor grudges and are looking for a fight. Join others and show those looking for a battle who is mighty.", objectives = "Slay 25 Level 90 Alliance anywhere within Midnight." }
WordHunterWoW_QuestEN[93647] = { title = "Lumber For You", description = "", objectives = "Ye look like someone who could learn the art of bein' a lumberjack!\n\nI can teach ye real quick how to identify which trees are prime for gettin' some lumber.\n\nLumber has all sorts of uses when crafting stuff for yer house. Or other folks' houses, if you care to sell your goods. Might want to visit some o' your old craftin' teachers to brush up while you're at it. They've got some new things to teach, I'd wager!\n\nSo get what ye can and see what ye can make of it!" }
WordHunterWoW_QuestEN[93651] = { title = "The Blinding Vale: Lightbloom Roots", description = "We have traced Ruia's flight through the Rootways. As we suspected, he has sought refuge deep within The Blinding Vale, where the Lightbloom first took root within Harandar.\n\nWith Alndust empowering our command of life, we are able to keep the Lightbloom from spreading uncontrolled. But we will run out of Alndust long before Ruia runs out of patience.\n\nRuia is wise and powerful. But his actions in Eversong prove that his conviction has grown into an uncontrollable fanaticism. He must be stopped.", objectives = "Complete The Blinding Vale dungeon.", completion = "So it is done, then.\n\nRuia's demise is a tragedy. You never knew him as such, but he was once a man of honor and conviction. To think that the Light would blind him so completely to the folly of his ambitions...\n\nIn the end, he thought he was doing what was best for Harandar. I can only hope his soul finds both peace and forgiveness, as it seeks Aln'hara in death." }
WordHunterWoW_QuestEN[93667] = { title = "Camp Stonewash", description = "You're not the first strange thing I've seen today.\n\n<Scout Zel'kanra shakes her head.>\n\nSaw a big, shelled creature along the path to Jan'Alor. Amaxi took a bunch of scouts and went after it.\n\nThey've been gone a while. Think you could check in on them?", objectives = "Find Amaxi outside Camp Stonewash in Zul'Aman.", completion = "Who are you? What are you doing here?\n\n<Amaxi tenses, but relaxes after a moment.>\n\nShadebasin sent you. Yes, we're fine. But these tortollan should not be here!" }
WordHunterWoW_QuestEN[93668] = { title = "An Old Game for a New Age", description = "Greetings, {class}. Have you heard of my joint venture with Aethas Sunreaver and Auric Sunchaser? We have been attempting to rekindle interest in an old arcane tournament of stealth versus perception, called Decor Duel.\n\nWe're currently training new players, so if you'd like to learn the ropes of the game, feel free to meet us in the Decor Duel training area, just west of here.", objectives = "" }
WordHunterWoW_QuestEN[93683] = { title = "Conditional Objectives - Singular", description = "{name}! Glad to see you. The defenders in the fortress could use your help.\n\nOne of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on.\n\nShe needs the help of someone who can properly disrupt the robot's attacks so it can be repaired.\n\nDo you have a moment to help?", objectives = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times." }
WordHunterWoW_QuestEN[93687] = { title = "Taste True Power", description = "", objectives = "This quest line will unlock:" }
WordHunterWoW_QuestEN[93690] = { title = "Alchemy Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", objectives = "Fill Alchemy Crafting Orders for the Artisan's Consortium.", progress = "Bring back proof of completed orders and I'll see that you're adequately compensated.", completion = "You have our gratitude, <class>. Silvermoon stands stronger thanks to your skills." }
WordHunterWoW_QuestEN[93691] = { title = "Blacksmithing Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", objectives = "Fill Blacksmithing Crafting Orders for the Artisan's Consortium.", progress = "Bring back proof of completed orders and I'll see that you're adequately compensate", completion = "You have our gratitude, <class>. Silvermoon stands stronger thanks to your skills." }
WordHunterWoW_QuestEN[93692] = { title = "Engineering Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", objectives = "Fill Engineering Crafting Orders for the Artisan's Consortium.", completion = "You have our gratitude, <class>. Silvermoon stands stronger thanks to your skills." }
WordHunterWoW_QuestEN[93693] = { title = "Inscription Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", objectives = "Fill Inscription Crafting Orders for the Artisan's Consortium.", completion = "You have our gratitude, <class>. Silvermoon stands stronger thanks to your skills." }
WordHunterWoW_QuestEN[93694] = { title = "Jewelcrafting Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", objectives = "Fill Jewelcrafting Crafting Orders for the Artisan's Consortium.", progress = "Bring back proof of completed orders and I'll see that you're adequately compensated.", completion = "You have our gratitude, <class>. Silvermoon stands stronger thanks to your skills." }
WordHunterWoW_QuestEN[93695] = { title = "Leatherworking Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", objectives = "Fill Leatherworking Crafting Orders for the Artisan's Consortium.", completion = "You have our gratitude, <class>. Silvermoon stands stronger thanks to your skills." }
WordHunterWoW_QuestEN[93696] = { title = "Tailoring Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", objectives = "Fill Tailoring Crafting Orders for the Artisan's Consortium.", progress = "Bring back proof of completed orders and I'll see that you're adequately compensated.", completion = "You have our gratitude, <class>. Silvermoon stands stronger thanks to your skills." }
WordHunterWoW_QuestEN[93697] = { title = "Shimmering Melodies", description = "Have you heard it? The magic of Eversong. It emanates a subtle melody, if you listen closely enough. The complex interwoven strands of magic move against each other and create a beautiful harmony.\n\nThe dust distilled from such magic is exceptionally potent. Bring some to me and I will show you its uses.", objectives = "" }
WordHunterWoW_QuestEN[93698] = { title = "Splintered Radiance", description = "When captured at just the right moment, the power exuding from an object can be crystallized into splinters of raw magical energy. The result is dazzling, like beams of sunlight splitting as they stream through a window.\n\nBring me some of these shards. My work cannot continue without them.", objectives = "Collect 10 Radiant Shards and deliver it to Dolothos in Silvermoon.", progress = "A few shards should be sufficient.", completion = "Oh, they glow with such wonderful power! These should do nicely." }
WordHunterWoW_QuestEN[93699] = { title = "A Ray of Sunlight", description = "There is great magic in the dawn. It illuminates and awakens all it falls upon, rousing the land to action. It is potential in its purest form.\n\nAs enchanters, we can crystallize that potential. Bring a parcel of the dawn to me.", objectives = "Collect 1 Dawn Crystal and deliver it to Dolothos in Silvermoon." }
WordHunterWoW_QuestEN[93700] = { title = "Experience Tranquility", description = "Are you an herbalist? Oh, thank goodness.\n\nI've found myself in need of an exorbitant amount of tranquility bloom. The orders from the alchemists keep piling up and I only just finished restocking our argentleaf and--\n\n<Nathera stops to take a deep breath.>\n\nCould you please bring me as much tranquility bloom as you can carry? I'd be in your debt.", objectives = "" }
WordHunterWoW_QuestEN[93701] = { title = "Brittle and Brilliant", description = "Argentleaf is always in high demand whenever war draws near.\n\nIt practically falls apart when you dry it out, but that powder can be used in a variety of medicines. It calms the nerves, focuses the mind, and can even work as a mild anesthetic in a pinch.\n\nIf you find any out in the field, please bring it to me.", objectives = "" }
WordHunterWoW_QuestEN[93702] = { title = "The Root of Life", description = "Most tuberous roots have some sort of healing potential, but azeroot is by far the most potent and versatile.\n\nJust a small amount, juiced or powdered, can stave off infections, promote healing, and soothe both body and mind. I've even seen it used to keep lumber from rotting!\n\nIf you could bring me a few bushels, I'll put it to good use.", objectives = "" }
WordHunterWoW_QuestEN[93703] = { title = "Sin'dorei Vices", description = "While most of our harvests supply the scribes and alchemists in the city, we do occasionally receive orders from the public.\n\nLord Saltheril is one of our most prolific customers. He has an estate in western Eversong that he keeps well-supplied with offerings for guests at his soirees.\n\nHe has requested a large quantity of mana lilies and sanguithorn this week. Could you help us fulfill the order?", objectives = "Collect 5 Mana Lilies and 2 Sanguithorn and deliver it to Botanist Nathera in Silvermoon.", progress = "Lord Saltheril's business is always welcome, even if a bit eccentric.", completion = "Excellent. With your help and what we already have in stock, this should cover his order." }
WordHunterWoW_QuestEN[93704] = { title = "Traditional Harvests", description = "Tranquility bloom and argentleaf are the backbone of countless potions, elixirs, inks, and so much more.\n\nIt never hurts to keep a surplus around. If you find yourself with any extra, we would gladly take it off your hands.", objectives = "" }
WordHunterWoW_QuestEN[93705] = { title = "Copper for Your Thoughts?", description = "It's easy to overlook in favor of more extravagant materials, but copper is an extremely reliable and versatile material. Weapons, armor, wiring, jewelry, and of course the humble copper coin--it does it all!\n\nNaturally, copper is always in high demand across the city and beyond. If you happen across any extra ore, I would gladly take it off your hands.", objectives = "" }
WordHunterWoW_QuestEN[93706] = { title = "Aggressive Tin-dencies", description = "There's been an influx of newly recruited soldiers lately. Marvelous fighters in the making, but a little too enthusiastic. They've already done a number on the stock of training weapons.\n\nWe usually make training weapons out of tin or other soft metals. They keep the recruits from doing real damage to the training dummies or each other, but they don't last long.\n\nWe'll need a lot more tin than what we have in stock to keep up. Bring us some more!", objectives = "Collect 10 Umbral Tin Ore and deliver it to Belil in Silvermoon." }
WordHunterWoW_QuestEN[93707] = { title = "It's Called Silvermoon", description = "Elegant gold filigree may be a favorite of the sin'dorei, but our city also boasts some of the finest silversmiths in Azeroth.\n\nThey have been receiving a particularly high number of orders with all of the new visitors passing through. If you come across any high-quality silver, they can put it to good use.", objectives = "" }
WordHunterWoW_QuestEN[93708] = { title = "Conductive Metals", description = "Our arcane constructs might look purely magical, but there's quite a bit of advanced wiring going on beneath the surface. Silvermoon's engineers truly are spell-workers in their own right.\n\nThey've been ramping up production lately to help fortify our defenses. Naturally, they look to us for supplies. I have most of the materials they ordered, but I'm low on tin and silver.\n\nCould you help me fulfill the order?", objectives = "Collect 5 Umbral Tin Ore and 5 Brilliant Silver Ore and deliver it to Belil in Silvermoon.", progress = "Tin and silver are both remarkably conductive. I could elaborate, if you have a few hours?", completion = "Ah, yes. This quantity should be sufficient. I'll have it packaged up for the engineers." }
WordHunterWoW_QuestEN[93709] = { title = "Stocking the Staples", description = "One can never have too much copper and thorium on hand. Even with all the new miners we brought on, we still nearly deplete our stocks every week.\n\nAt this rate, we'll have to start importing--and I do not want the headache that sort of paperwork brings.\n\nIf you could help us replenish our stock of copper and thorium, I would be in your debt.", objectives = "" }
WordHunterWoW_QuestEN[93710] = { title = "Tempered in Darkness", description = "The beasts of Quel'Thalas produce leather of unparalleled quality, but the Void has been doing something strange to it.\n\nNormally, we harden leather by heating it under specific conditions. But the darkness clinging to these hides seems to be tempering the leather on its own. I have no idea how this is possible, but we can make use of it.\n\nBring me as much as you can gather. We have an army to supply.", objectives = "" }
WordHunterWoW_QuestEN[93711] = { title = "The Chill of the Void", description = "When we mobilized troops to Northrend many years ago, we had to outfit our soldiers to withstand the icy chill of the frozen wastes. The secret is lining the inside of the armor with fur and plating it securely to trap warmth inside.\n\nWe kept detailed records of those techniques. The Void may not be as cold as Northrend, but I'd rather be prepared for the worst.\n\nBring me a supply of fur and plating and I'll see you compensated.", objectives = "" }
WordHunterWoW_QuestEN[93712] = { title = "Style and Skill", description = "In battle, appearances are nearly as important as raw skill. If you can intimidate your foe before you've even drawn your sword, you're already that much closer to victory.\n\nOur fletchers take this a step further and insist that beautiful feathers make our Farstriders' arrows do more damage. I'm... not certain about that, but I can appreciate the aesthetic.\n\nHere's a list of what they need for this week's batch of arrows. Supply whatever you can and I'll handle the rest.", objectives = "Collect 5 Carving Canines and 5 Peerless Plumage and deliver it to Tyn in Silvermoon.", progress = "You can ignore the note about whether the feathers should be crimson or scarlet.", completion = "Ah, these should make excellent arrows." }
WordHunterWoW_QuestEN[93713] = { title = "Essential Materials", description = "The Horde's penchant for teeth and animal pelts has worn off on some sin'dorei. It's not uncommon in recent years to receive bulk orders for both.\n\nThis is one of those times. If you have any spare hides, or come across any particularly sharp teeth in your hunts, I'd gladly trade you for them.", objectives = "" }
WordHunterWoW_QuestEN[93714] = { title = "Minor Scales", description = "A well-made suit of scalemail is a sight to behold. It requires quite a bit of patience and attention to fine detail, but Silvermoon's leatherworkers are masters of the craft.\n\nIf you happen to hunt any scaled beasts, we could use those materials. A large quantity of smaller sized ones, if you could--they layer more nicely in the armor.", objectives = "Collect 20 Void-Tempered Scales and deliver it to Tyn in Silvermoon." }
WordHunterWoW_QuestEN[93716] = { title = "Learning the Cloaks - Part 1", description = "In this game of Decor Duel, one side uses illusion to disguise themselves as, and hide amongst, everyday objects in the area.\n\nThe other side uses pre-approved lists of illusion-piercing abilities to find and then capture those hiding cloaked in disguise.\n\nAt the end of the round, the teams switch roles, so each side has a chance to hide and seek. \n\nTime for you to try! This armchair has been enchanted to cloak you with its disguise. Don its appearance, then change your disguise a few times.", objectives = "" }
WordHunterWoW_QuestEN[93717] = { title = "Learning the Cloaks - Part 2", description = "When disguised, you will have the ability to magically teleport yourself to a nearby piece of decor.\n\nPick up the chair's disguise again, and this time try swapping your location a few times. Feel free to change your disguise between swaps if you'd like.", objectives = "" }
WordHunterWoW_QuestEN[93719] = { title = "Nothing Captured, Nothing Gained", description = "There are three Seeker classes in Decor Duel, but everyone starts off with the Spellbreaker kit. Don't worry--you can earn access to the others.\n\nSome fundamentals: you can break the shield of a disguised hider's illusion by using Dispel Magic. Once the hider has been marked as Found, you'll have a brief window to Tag them, taking them out of the match.\n\nMy statue has been enchanted to outfit you with a Spellbreaker kit. Once outfitted, use Dispel Magic to find and tag decoys hiding around here.", objectives = "" }
WordHunterWoW_QuestEN[93723] = { title = "Crafters Needed", description = "Greetings. Come to lend a hand?\n\nThe war effort has been taxing on Silvermoon's resources. We need to keep our soldiers armed and supplied, but even our seasoned crafters have been overwhelmed. To keep up with demand, we have struck a deal with the Artisan's Consortium.\n\nIf you have your own skills to offer, speak to Mar'nah. She can help you view and place crafting orders.", objectives = "Talk to Mar'nah in the Bazaar.", progress = "Have you talked to Mar'nah?", completion = "Fulfilling these work orders is imperative to the war effort. Your services are greatly appreciated." }
WordHunterWoW_QuestEN[93724] = { title = "Crafting Orders: Alchemy", description = "Ah, you're an alchemist?\n\nYou should speak with Camberon. He's a skilled alchemist who runs a shop here in Silvermoon.\n\nCamberon has a work table at his shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek him out and see what work is available for you.", objectives = "Find Camberon in the Bazaar and use his Alchemist's Lab Bench.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "It is ever an honor to meet a fellow alchemist. Clean up your spills and we'll be well on our way to friendship." }
WordHunterWoW_QuestEN[93726] = { title = "Crafting Orders: Blacksmithing", description = "Ah, you're a blacksmith?\n\nYou should speak with Bemarrin. He's a skilled blacksmith who runs a shop here in Silvermoon.\n\nBemarrin has a work table at his shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek him out and see what work is available for you.", objectives = "Find Bemarrin in the Bazaar and use his Blacksmith's Table.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "A pleasure meeting you. But if you misplace my good pair of tongs, I'll have you thrown right out." }
WordHunterWoW_QuestEN[93727] = { title = "Crafting Orders: Engineering", description = "Ah, you're an engineer?\n\nYou should speak with Danwe. She's a skilled engineer who runs a shop here in Silvermoon.\n\nDanwe has a work table at her shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek her out and see what work is available for you.", objectives = "Find Danwe in the Bazaar and use her Tinker's Workbench.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "Good engineers are hard to come by. Get a handle on those arcane constructs and you'll be drowning in work from the Magisters alone." }
WordHunterWoW_QuestEN[93728] = { title = "Crafting Orders: Inscription", description = "Ah, you're a scribe?\n\nYou should speak with Zantasia. She's a skilled scribe who runs a shop here in Silvermoon.\n\nZantasia has a work table at her shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek her out and see what work is available for you.", objectives = "Find Zantasia in the Bazaar and use her Scribe's Drafting Table.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "You have a fine and steady hand, <name>. I look forward to seeing what you can create." }
WordHunterWoW_QuestEN[93729] = { title = "Crafting Orders: Jewelcrafting", description = "Ah, you're a jewelcrafter?\n\nYou should speak with Amin. He's a skilled alchemist who runs a shop here in Silvermoon.\n\nAmin has a work table at his shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek him out and see what work is available for you.", objectives = "Find Amin in the Bazaar and use his Jeweler's Bench.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "It seems like every set of armor these days needs a dozen gems inlaid. Not that I am complaining, especially not with your aid whittling down the work orders." }
WordHunterWoW_QuestEN[93730] = { title = "Crafting Orders: Tailoring", description = "Ah, you're a tailor?\n\nYou should speak with Galana. She's a skilled tailor who runs a shop here in Silvermoon.\n\nGalana has a work table at her shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek her out and see what work is available for you.", objectives = "Find Galana in the Bazaar and use her Tailor's Work Table.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "Fine spellcasters demand fine robes, but their high standards keep our skills sharp. Perhaps you and I can share techniques." }
WordHunterWoW_QuestEN[93731] = { title = "Crafting Orders: Leatherworking", description = "Ah, you're a leatherworker?\n\nYou should speak with Talmar. He's a skilled leatherworker who runs a shop here in Silvermoon.\n\nTalmar has a work table at his shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek him out and see what work is available for you.", objectives = "Find Talmar in the Bazaar and use his Leatherworker's Tool Bench.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "The beasts of Quel'thalas have the finest leather you will ever work with. I look forward to seeing what you make of it." }
WordHunterWoW_QuestEN[93734] = { title = "Precious Trinkets", description = "Finally we get to see what treasures Groffa was hoarding.\n\n<Furgh's eyes go black as he looks at the bag. The drool on his jowls turns to foam and his claws dig into the sides of the bag as his grip on it tightens.>\n\nMaybe the loa speaker's gifts aren't so bad. We should not be so hasty. I'll take a look. You watch and keep me safe.", objectives = "Keep Furgh safe and investigate the treasures.", progress = "Whatever Groffa had is bad. Right?", completion = "You didn't need to burn my things..." }
WordHunterWoW_QuestEN[93744] = { title = "Unity Against the Void", description = "", objectives = "" }
WordHunterWoW_QuestEN[93745] = { title = "Har'athir, Village of Memory", description = "You have been permitted to range about beneath our Goddess' light. But that doesn't mean we trust you out of hand.\n\nIf you wish to prove yourself a friend to the haranir, make yourself useful in Har'athir. It is there that we make the paints for our murals and watch over the newest roots to seek the Goddess' light.", objectives = "Meet Rootwarden Ku'paal in Har'athir.", completion = "So you survived your meeting with the elders. I am surprised, but also pleased.\n\nYou aided the children of Har'athir without hesitation. For that, I welcome you and offer you the hospitality of Amirdrassil's roots." }
WordHunterWoW_QuestEN[93751] = { title = "Windrunner Spire", description = "Former home of the Windrunners... now desecrated beyond thought. Since the Scourge invasion, the spire houses our greatest nightmares: banshees, abominations, hateful spirits.\n\nThere is no redeeming such a place, but perhaps we may help lay the tormented to rest.", objectives = "" }
WordHunterWoW_QuestEN[93752] = { title = "Murder Row", description = "I've always disagreed with Lor'themar about the existence of Murder Row. But I guess like any forest, a city should and will have its secrets.\n\nThough recently, Lor'themar has expressed concern about rising fel activity in the area. With the majority of Silvermoon's watch on the Voidstorm, many folks are testing boundaries, taking advantage, making a play for power...\n\nYou have my permission to investigate and crush any such illegal activities.", objectives = "Complete the Murder Row dungeon on any difficulty.I've always disagreed with Lor'themar about the existence of Murder Row. But I guess like any forest, a city should and will have its secrets.\n\nThough recently, Lor'themar has expressed concern about rising fel activity in the area. With the majority of Silvermoon's watch on the Voidstorm, many folks are testing boundaries, taking advantage, making a play for power...\n\nYou have my permission to investigate and crush any such illegal activities.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[93753] = { title = "Magisters' Terrace", description = "Powerful monsters of the void have taken over Magister's Terrace! These halls contain untold amounts of knowledge and arcane power. We cannot lose any of it to our enemy.\n\nClear the voidspawns and their masters. You'll likely have to solve the terrace's defenses as well, which are designed to prevent and shutdown unauthorized access at any cost.", objectives = "Complete the Magisters' Terrace dungeon on any difficulty.", progress = "If the Void gains access to Silvermoon's most exclusive repository of magic... Rommath will throw a fit of epic proportions.", completion = "That was a close call. As for Rommath and Umbric, that's a puzzle for another day." }
WordHunterWoW_QuestEN[93754] = { title = "Maisara Caverns", description = "While Lady Liadrin was in Zul'Aman, she took note of one tribe, the Vilebranch, brutalizing the other forest trolls and their loa. They live up to their name by wanton use of necromancy.\n\nEnter their caverns and put a stop to their black magic!", objectives = "" }
WordHunterWoW_QuestEN[93755] = { title = "Den of Nalorakk", description = "A trial of skill and strength... I'd go myself if I wasn't needed in Silvermoon.\n\nGood luck, champion. I look forward to hearing about your victory against the Amani Loa of War.", objectives = "" }
WordHunterWoW_QuestEN[93756] = { title = "The Blinding Vale", description = "This place in Harandar is the Lightbloom's epicenter. Orweyna did what she could, which was much, but we must strike at the taproot of all roots for the plant to die.\n\nBe on your guard, even if you think yourself experienced with the Lightbloom by now. The vale is different from the rampant, but ultimately wild growth in Eversong. It's a calculated force of nature led by a Rootwarden who seeks to strangle you and everything else it desires.", objectives = "" }
WordHunterWoW_QuestEN[93757] = { title = "Voidscar Arena", description = "If I didn't know that the domanaar thirst for battle, and all the pain and strife that comes with it, I'd say this is trap. Either way, I suppose it's an invitation to get yourself killed.\n\nIf you insist on participating in the Void's fighting games, I can't stop you. Just don't hesitate to kill as many voidspawn as possible while you're there, okay?", objectives = "" }
WordHunterWoW_QuestEN[93758] = { title = "Nexus-Point Xenas", description = "We must continue to keep an eye on this overpowered facility. If breached, disaster will spread beyond the Voidstorm. Unfortunately this magical and mechanical complex is beyond my area of expertise.\n\nPrepare yourself, and ensure that the Nexus-Point Xenas remains dormant.", objectives = "" }
WordHunterWoW_QuestEN[93766] = { title = "Midnight: World Quests", description = "The Void seeks to divide us, to drive a wedge between kin and kingdom alike. We cannot allow it.\n\nEverywhere I turn, I hear of those struggling--families displaced, defenders overwhelmed, healers stretched thin. No blade nor spell alone will turn this tide, but the strength of many hearts united can.\n\nGo forth and lend your aid where it is needed most.", objectives = "Complete World Quests in Midnight." }
WordHunterWoW_QuestEN[93767] = { title = "Midnight: Arcantina", description = "The Arcantina welcomes all who seek respite.\n\nStep inside its lively halls, share a brew, and trade stories with friends old and new.\n\nWhere the Void brings chill and silence, here you'll find warmth, laughter, and the spark of fellowship.", objectives = "Visit the Arcantina and have a brew with one of the patrons.", completion = "Ah, you've returned. I am glad you allowed yourself that well-earned moment of peace." }
WordHunterWoW_QuestEN[93769] = { title = "Midnight: Housing", description = "A strong community is built not by walls, but by the hands and hearts of those within it. \n\nLend your voice, your time, and your spirit to the neighborhood. Help your fellows, share in their burdens, and take your place as an active part of the home we build together.", objectives = "Participate in neighborhood Endeavors and collect Community Coupons." }
WordHunterWoW_QuestEN[93771] = { title = "Har'kuai, Village of Rain", description = "All waters in Harandar are sacred. They feed the roots of the world and Aln'hara's myriad creations in equal measure. Perhaps none are more spectacular than those that fall from the roots of the tree called Nordrassil.\n\nTo the north, you will find Har'kuai. The rains that fall from the sky there carry a remarkable vitality. If you wish to witness all of Aln'hara's majesties, then a trek to Har'kuai would serve you well.", objectives = "Meet Rootwarden Kamari in Har'kuai.", completion = "I have heard of your travels, outsider. I am Kamari, Rootwarden of Nordrassil.\n\nThe mists of Har'kuai hold many mysteries. I hope you will find them enlightening, during your stay here." }
WordHunterWoW_QuestEN[93774] = { title = "When is a Chair not for Sitting?", description = "Aethas Sunreaver, Riftblade Maella, and Auric Sunchaser have recently revitalized an old arcane twist on hide and seek called Decor Duel.\n\nThey're looking for new participants to help spread the entertainment.\n\nYou should meet them over in Falconwing Square.", objectives = "" }
WordHunterWoW_QuestEN[93775] = { title = "Har'mara, Village of Balance", description = "Ah! The outsider who saved Har'mara. Word travels fast through Aln'hara's roots. No doubt Elder Hagar was grateful for your aid.\n\nShe would never admit it, but things have been difficult since the roots above her village burned. The rutaani and fungarians each grow bolder in their eccentricities. And the lingering flare-ups on Teldrassil's roots present a constant threat.\n\nIf your travels afford another trip to Har'mara, I do not doubt she would benefit from additional help.", objectives = "Return to Hagar in Har'kuai.", completion = "Ah! <name>. Welcome back. As you can see, our hands are full as ever, here.\n\nI assure you, I have things well in hand. But if you do wish to explore a bit further afield, I am sure some of the others could benefit from your assistance." }
WordHunterWoW_QuestEN[93776] = { title = "Har'alnor, Village of Twilight", description = "Our efforts in the Blinding Bloom have halted the Lightbloom's encroachment for now. But with Rootwarden Ruia gone, there are scarce few who remain to handle the rest of the village's troubles.\n\nI'm going back to Har'alnor to help out where I can. If you have the time and the inclination, your further assistance would be most appreciated.", objectives = "Meet with Hannan in Har'alnor.", completion = "Thank the goddess you returned.\n\nAs you can see, we're still in fairly dire straits here. Though we quelled its spread beneath Shaladrassil's roots, the Lightbloom remains a threat. There are rumors of fungarians acting erratically in Fungara Village. And there is no Rootwarden in Har'alnor to deal with either.\n\nThankfully, we have the next best thing: an intrepid outsider with a habit of helping others." }
WordHunterWoW_QuestEN[93782] = { title = "Conditional - Multiple Objectives, Sequenced", description = "I be sent out here ta prove dat I can be an amani warrior.\n\nDis trial needs me ta collect as many trophies from dese gnarldin as possible. \n\nDe two of us should work together! I be helpin' you get recognized as an amani warrior, yeah?\n\nJust go out dere and get as many trophies from de gnarldin as possible. \n\nI be stayin' behind ta watch our backs, eh?", objectives = "Recover 1 trophies from gnarldin and their allies." }
WordHunterWoW_QuestEN[93783] = { title = "Conditional - Just One Objective", description = "I be sent out here ta prove dat I can be an amani warrior.\n\nDis trial needs me ta collect as many trophies from dese gnarldin as possible. \n\nDe two of us should work together! I be helpin' you get recognized as an amani warrior, yeah?\n\nJust go out dere and get as many trophies from de gnarldin as possible. \n\nI be stayin' behind ta watch our backs, eh?", objectives = "Recover 1 trophies from gnarldin and their allies." }
WordHunterWoW_QuestEN[93784] = { title = "A Gnawing Void of Curiosity", description = "<The artifact crumbles in your hand, leaving only a faint but distinctly ancient arcane footprint. Naleidea Rivergleam will want to hear about this.>", objectives = "Report your discovery to Naleidea Rivergleam in Silvermoon City.<The artifact crumbles in your hand, leaving only a faint but distinctly ancient arcane footprint. Naleidea Rivergleam will want to hear about this.>You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[93792] = { title = "Blessings of the Loa", description = "My name is Du'gal. And you are hash'ura.\n\nKinduru has ordered me to train you in de ways of loa worship. Take honor in it. Very few gokinye have earned de right as you have.\n\nBeside me is de Altar of Blessings. You may use it to worship any of our loa, and you shall receive a sliver of power in thanks.\n\nGo ahead now, if ya be so kind.", objectives = "Worship at the Altar of Blessings.\n\nGain a blessing by choosing to combine the power of Akil'zon, Halazzi, Jan'alai, or Nalorakk with that of any lesser loa you've formed a bond with.", progress = "De loa are quite generous indeed.", completion = "Ya spirit is flowing with strength!\n\nYou may use de altar as often as ya wish. But ya can only hold one blessing on ya self at a time." }
WordHunterWoW_QuestEN[93801] = { title = "Calculated Culling", description = "This pathogen is spreading rapidly among the denizens of the Molt.\n\nA swarm of netherwasp hatched shortly after our arrival. The infection spread throughout the region as they fought over territory. If their numbers continue to grow, they could carry the pathogen to the rest of Voidstorm.\n\n{name}, can I ask you to reduce the number of infected creatures in the Molt?", objectives = "Cull creatures endemic to the Molt.", progress = "This place has such vitality. It's no wonder the pathogen has spread so easily.", completion = "Your efforts and assistance are both noted and appreciated." }
WordHunterWoW_QuestEN[93810] = { title = "Masters' Perch", description = "Not every creature of the Void serves Xal'atath's whims. Conquest was our way long before her arrival.\n\nTo the north, you find Slayer's Rise. It is the vast battleground where three domanaar vie for power. And I hear your ren'dorei allies have set up in Masters' Perch, the main citadel, as well.\n\nI am certain great battles await you there. Go forth.", objectives = "Seek void elf allies in Masters' Perch.", completion = "Good, we need more capable arms." }
WordHunterWoW_QuestEN[93811] = { title = "Renowned with the Silvermoon Court", description = "The people of Quel'thalas appreciate your continued support. With threats on all sides, it is good to know we can rely on champions such as yourself to protect us.\n\nThe Court wishes to reward you for your efforts.You will receive:", objectives = "Speak with Caeris Fairdawn at Saltheril's Haven.The people of Quel'thalas appreciate your continued support. With threats on all sides, it is good to know we can rely on champions such as yourself to protect us.\n\nThe Court wishes to reward you for your efforts.You will receive:" }
WordHunterWoW_QuestEN[93816] = { title = "Putting it Together", description = "You have the basics now. All that's left is to experience the Arcane Propagator for yourself in a match of Decor Duel!\n\nWhat is the Arcane Propagator, you ask? A mystic relic wrought from glamours. It lets players cloak themselves in the guise of enchanted objects.\n\nWe've partially recreated it with the chair for training, as you've seen, but the real thing is much better. Why not play a match for real right now?", objectives = "" }
WordHunterWoW_QuestEN[93841] = { title = "Ghosts of the Ring", description = "I was at de Ring of Glory earlier. Have you been? De place is crawlin' with spirits and one of dem gave me quite de fright! Came right up and tried to talk to me! I was too nervous to stick 'round and find out what he wanted.\n\nYou look brave and strong. Maybe you oughta check it out.", objectives = "" }
WordHunterWoW_QuestEN[93842] = { title = "Bloom and Fade", description = "My time is runnin' out and I need to see if I can rescue my beloved, Eshaye. She's stuck in de loop, and I want to break her from de cycle before I fade entirely.\n\nI used to be able to get through to her with bouquets of sweetsaw blooms. I can't grasp dem anymore, though. Will you gather some for me?", objectives = "" }
WordHunterWoW_QuestEN[93843] = { title = "Ectoplasmic Extractions", description = "Up near de Ring of Glory, there are spirits like myself who are merchants. Dey sell a variety of things to other spirits, but I got Eshaye's attention in de past using a beverage from Mab'jul.\n\nDe market goods can be purchased with ectoplasm, which can be gathered from de frayed spirits around de Ring. Especially de cultists, who steal it from de others.", objectives = "" }
WordHunterWoW_QuestEN[93849] = { title = "Ectoplasmic Emporium", description = "Eshaye is sure to love these flowers! Now all we need is de spectral brew. Take de ectoplasm to Mab'jul and exchange it for a bottle of spectral brew.\n\nIt's a vintage made from harvested ectoplasm, and is quite refreshing. It sometimes has de ability to stall fraying.", objectives = "" }
WordHunterWoW_QuestEN[93850] = { title = "Windrunner Spire: Haunting Melodies", description = "So much grief... So much pain. It binds us to this place.\n\nHis melodies once soothed us, but now they are drowned out by the din of violence.\n\nPlease help us. Follow the sound of the lyre. He will guide you.", objectives = "Quell the restless spirits inside Windrunner Spire.", progress = "Please... help us.", completion = "The pain, the fear... I can feel that music washing it all away.\n\nThank you, friend." }
WordHunterWoW_QuestEN[93851] = { title = "Communing with Ghosts", description = "Dat was a long shot, but I still wanted to try.\n\n<He pauses a moment and shudders, seeming to flicker at the edges.>\n\nI am out of ideas, {name}. Will you ask around? Some of de others here may have some ideas of how to get through to Eshaye. I am not welcome too close to dem, or I would come with you.", objectives = "" }
WordHunterWoW_QuestEN[93852] = { title = "Lost Iridescent Flightstone", description = "The flightstone glimmers with the colors of all aspects. Within the glittering light you have visions of noble dragon houses locked in battle against Primal Incarnates. A vicious cacophony of roars as Shadowflame consumes swaths of land. And the soothing sounds of nature as a world tree blooms.\n\nThe soaring skies of Valdrakken call.", objectives = "" }
WordHunterWoW_QuestEN[93865] = { title = "Carve Your Way", description = "We permit the presence of your kind for one reason. Your willingness to fight. Show us the skills of mortal duelists.\n\nGo, find others of your kind. The pit below is an ideal site for demonstrations of combat prowess.", objectives = "Win a duel against another player or the Masters' Champion.", progress = "Go. Show me a bout.", completion = "Good. But one victory proves nothing. The path to supremacy requires sustained practice.\n\nReturn tomorrow and demonstrate your skills further." }
WordHunterWoW_QuestEN[93870] = { title = "The Ephemeron Masquerade", description = "The deeds of today becomes the tales of dusk!\n\nSeekers and Hiders, alike, make their mark through thrilling game play and strategic out maneuvering.\n\nThe sun shines its light on a new day, shattering the illusions of yesterday, and elongating the shadows of today. Are you ready?\n\nDon you disguise, secure your kit, and show your peers no one can hold a candle to you ... literally!", objectives = "" }
WordHunterWoW_QuestEN[93877] = { title = "Conditional Objectives - Sequential", description = "{name}! Glad to see you. The defenders in the fortress could use your help.\n\nOne of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on.\n\nShe needs the help of someone who can properly disrupt the robot's attacks so it can be repaired.\n\nDo you have a moment to help?", objectives = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times." }
WordHunterWoW_QuestEN[93878] = { title = "Conditional Objectives - Multiple Steps, No Sequence", description = "{name}! Glad to see you. The defenders in the fortress could use your help.\n\nOne of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on.\n\nShe needs the help of someone who can properly disrupt the robot's attacks so it can be repaired.\n\nDo you have a moment to help?", objectives = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times." }
WordHunterWoW_QuestEN[93879] = { title = "Conditional Objectives - Conditional After Sequence", description = "{name}! Glad to see you. The defenders in the fortress could use your help.\n\nOne of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on.\n\nShe needs the help of someone who can properly disrupt the robot's attacks so it can be repaired.\n\nDo you have a moment to help?", objectives = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times." }
WordHunterWoW_QuestEN[93889] = { title = "Midnight: Saltheril's Soiree", description = "Champion, you would do well to attend Saltheril's Soiree.\n\nThere, amidst Silvermoon's intricate politics and quiet struggles for influence, our most distinguished military orders each have matters they wish to see addressed.\n\nProve your worth to these factions, and you may find their gratitude and favor richly rewarded.", objectives = "Participate in Saltheril's Soiree and earn favor with one of the Silvermoon factions.", completion = "You've done well to navigate the Court without being swallowed by its politics. Silvermoon needs those who can act with purpose, not those lost in the machinery of ambition." }
WordHunterWoW_QuestEN[93890] = { title = "Midnight: Abundance", description = "The trolls of Zul'Aman draw their strength from the loa: ancient spirits that grant power to those who honor them. These boons can be wondrous or perilous, depending on the loa's nature and the devotion of its followers.\n\nThere are whispers of a Loa of Abundance dwelling within Zul'Aman, its blessings said to bring prosperity to those deemed worthy.\n\nSeek it out, learn what drives it, and see if its favor would serve our cause.", objectives = "Participate in Zul'Aman's Abundance Harvest and gain Loa's favor." }
WordHunterWoW_QuestEN[93891] = { title = "Midnight: Legends of the Haranir", description = "For the Haranir, art is a language of memory. \n\nTheir history endures not in words but in vivid stories painted upon stone with pigments imbued with power. Through these works, the Zur'ashar, their revered historians, entwine living visions of the past to the present. Each vision draws us deeper into the haranir's mysteries, guiding us closer to the truths that shaped their world.You will learn:", objectives = "Step into the memories of the Haranir through the enchanted paintings.For the Haranir, art is a language of memory. \n\nTheir history endures not in words but in vivid stories painted upon stone with pigments imbued with power. Through these works, the Zur'ashar, their revered historians, entwine living visions of the past to the present. Each vision draws us deeper into the haranir's mysteries, guiding us closer to the truths that shaped their world.You will learn:" }
WordHunterWoW_QuestEN[93892] = { title = "Midnight: Stormarion Assault", description = "The fight against Xal'atath tests our resolve, but it will not break us.\n\nVoid anomalies twist the halls of Stormarion Citadel, but they will find no weakness here. The Void Elves stand as our allies. Prove to our enemies that our strength when united is beyond the reach of even the Void.\n\nGo, {name}--aid them, and see the Citadel cleansed of corruption.", objectives = "Participate in the Stormarion Assault event." }
WordHunterWoW_QuestEN[93897] = { title = "Home for the Holidays", description = "There's a holiday celebration goin' on at yer neighborhood! Get yerself back home and check it out.", objectives = "" }
WordHunterWoW_QuestEN[93898] = { title = "A Haunted Home", description = "I've heard tell of spooky apparitions and tasty treats popping up around the neighborhoods. If ye get a chance, you may want to look into it.", objectives = "" }
WordHunterWoW_QuestEN[93899] = { title = "Slayer's Rise", description = "We've received reports of escalated troubles between some domanaar. Go investigate the battle in Slayer's Rise, then report to Deminos Darktrance in Masters' Perch.", objectives = "Complete the Slayer's Rise battleground.", completion = "<name>, you made it through. Well done." }
WordHunterWoW_QuestEN[93904] = { title = "Defying Gravity", description = "Now, we descend. The Void energy below is unlike any I've felt before, as if gravity itself yields to the Void. Once you enter the cave, its influence will be upon you.\n\nKalgorg has already slain and claimed power from the creatures within. Their violent deaths have left behind some kind of cursed terrain. But we must proceed and claim the power within. Fill the reliquary to the brim. \n\nI know not what to expect from my voidwalker. We will need all the power we can manage.Upon completion of this quest you will gain:", objectives = "Gather Void energy within the Lair of Predaxas." }
WordHunterWoW_QuestEN[93905] = { title = "Ongoing Stoppage", description = "The Shadowguard may once have defied Xal'atath, but they're part of her army now. Whatever they're doing with the energies gathered here must be stopped.\n\nPut down their soldiers, harvesters, and machines. I'll do the same, and meet you deeper within.Upon completion of this quest you will gain:", objectives = "Slay Shadowguard and disrupt the Manaforge at the Ethereum Refinery." }
WordHunterWoW_QuestEN[93906] = { title = "Untethering the Two", description = "It never occurred to me to attack Eshaye. I been wasting time tryin' to get her to talk to me, without knowin' how to talk to her.\n\nWill you do dis for me? Challenge Eshaye and beat her. Could dis wake her up? I feel hope stirrin'.", objectives = "" }
WordHunterWoW_QuestEN[93907] = { title = "Edification of the Worthy", description = "When you acquire a new Seeker kit, it always starts off relatively lean.\n\nBut you'll earn Illusionary Coins as you play, and may trade them in with Gamemaster Fleurian for expanded abilities, and even additional kits!\n\nTake these. Add them to what you earned and demonstrate your shopping prowess.", objectives = "" }
WordHunterWoW_QuestEN[93909] = { title = "Midnight: Delves", description = "Many have ventured into the delves' depths, but few have returned with more than dust and bruises.\n\nValeera Sanguinar has taken a keen interest in these ventures. She leaves no stone unturned and has a remarkable talent for getting in to places others cannot.\n\nSeek her out, and see what fortune or danger awaits beneath the surface.", objectives = "Complete 3 Delves in Midnight.", progress = "Stay sharp, <name>.", completion = "You've braved the delves and returned stronger for it.\n\nValeera was right--opportunity favors the bold." }
WordHunterWoW_QuestEN[93910] = { title = "Midnight: Prey", description = "Silvermoon is beset on all sides by threats both known and unknown. There are those who seek to track these threats and put an end to the strife and chaos they create.\n\nSpeak with Magister Astalor Bloodsworn in Murder Row. He will guide you toward the urgent threats.", objectives = "Complete Prey Hunts for Astalor Bloodsworn in Silvermoon." }
WordHunterWoW_QuestEN[93911] = { title = "Midnight: Dungeons", description = "The dungeons of Azeroth hold great challenges and even greater rewards. Within them lay treasures that may aid you in battles yet to pass, and powerful foes to overcome.\n\nEnter the dungeon, and see what awaits you there.", objectives = "Complete any Seasonal Dungeon at Normal difficulty or higher.", progress = "Be ready for anything. Fortune often walks hand in hand with peril.", completion = "You've proven your mettle once more. \n\nMay your victories within strengthen you for what lies ahead." }
WordHunterWoW_QuestEN[93912] = { title = "Midnight: Raid", description = "Gather your allies, you will face the great trials ahead. \n\nThe rewards are vast, and can aid you in the battles ahead. You and your allies need only vanquish a small number of these terrible foes.", objectives = "Defeat any 2 raid bosses in Midnight on any difficulty.Gather your allies, you will face the great trials ahead. \n\nThe rewards are vast, and can aid you in the battles ahead. You and your allies need only vanquish a small number of these terrible foes.You will learn:" }
WordHunterWoW_QuestEN[93913] = { title = "Midnight: World Boss", description = "Powerful enemies roam Azeroth, their strength growing with each passing battle.\n\nOnly through courage and unity will you emerge victorious.", objectives = "Defeat a World Boss in Midnight.Powerful enemies roam Azeroth, their strength growing with each passing battle.\n\nOnly through courage and unity will you emerge victorious.You will learn:" }
WordHunterWoW_QuestEN[93922] = { title = "A Singular Focus Unleashed", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[93923] = { title = "Tenacity of the Shul'ka", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[93924] = { title = "An Unrelenting March", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[93929] = { title = "The War Within Recap", description = "<A parchment reaches you from an unknown sender.>\n\n<It speaks of perusing a tome to catch up on current events, and how it is vital to understand a looming threat.>\n\n<Perhaps you should seek out this tome to understand more when you are ready.>", objectives = "Consult the Tome of History to learn about the War Within saga.", completion = "<The tome floats in front of you. Its pages are filled with knowledge of all that has happened.>" }
WordHunterWoW_QuestEN[93930] = { title = "Courting Success", description = "You seek an audience with Saltheril? And you're wearing... that? Excuse me for a moment while I laugh into my handkerchief.\n\n<Caeris laughs lightly behind his handkerchief.>\n\nNow, let me be professional. You are cordially invited to attend Saltheril's soiree.\n\nDon't embarrass yourself, <name>. The best of Silvermoon are watching.", objectives = "Participate in Saltheril's Soiree and empower Eversong's runestones.", completion = "I half expected you to run back home in tears! I hope you had a stunning time." }
WordHunterWoW_QuestEN[93931] = { title = "An Abundance of Wealth", description = "De Loa of Abundance may not be one of de four great ones, but his worshippers are certainly de most devout.\n\nSeek him out yaself. You can find him in northern Zul'Aman near Halazzi's Temple, but I also hear he's established harvest sites in Eversong Woods, Harandar, and even de land of Void through de gargantuan skymouth.\n\nIf nothing else, de rewards he grants are glorious--to de worthy, at least.", objectives = "Harvest wealth for the Loa of Abundance.", progress = "Did you find de loa, hash'ura?", completion = "Heh! So ya finally met Dundun.\n\nEven de smallest are some of de greatest among de loa!" }
WordHunterWoW_QuestEN[93932] = { title = "Legendary Prosperity", description = "Harandar hides wisdom in every annal of its history, <name>. You would do well to seek out its legends for yourself. I suspect you may learn something of this world and our places in it.", objectives = "Discover a legend of the Haranir.", completion = "I wonder what it is that the stones showed you. I hope you found it enlightening, <name>. But remember: there is always more to learn." }
WordHunterWoW_QuestEN[93933] = { title = "Guarded Treasures", description = "Our sojourn to this world has brought the ren'dorei an even deeper understanding of the Void than before. The domanaar with whom we share a common enemy are almost strangely generous with their knowledge. I believe they want us to become as fearsome as they are.\n\nThere is a Singularity Anchor in Stormarion Citadel. I have learned how to draw upon some of its power to craft you a powerful item.\n\nBut first, we must ensure it does not fall into the hands of our enemies.", objectives = "Defend the Singularity Anchor in Stormarion Citadel.", progress = "Have you defended the anchor from the encroaching void forces?", completion = "Well done, <name>." }
WordHunterWoW_QuestEN[93942] = { title = "Spark of Radiance", description = "A vision of radiance permeates your mind.\n\nEldara Dawnrunner might have more information regarding these Sparks of Radiance.", objectives = "Speak to Eldara Dawnrunner in Silvermoon.", completion = "This is a Spark of Radiance.\n\nEvery week, one of these sparks will appear while on your adventures. In its current state, it's rather useless, but acquiring more will allow you to craft powerful items. Reagents like these are malleable, robust, and the prize for many crafters.\n\nThis is a unique crafting material that can help an item achieve expertise beyond that of mortal ability." }
WordHunterWoW_QuestEN[93943] = { title = "Ancient Curiosity: Combat", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important.>", objectives = "Use and equip a Combat Curio to your delve companion." }
WordHunterWoW_QuestEN[93945] = { title = "Ancient Curiosity: Utility", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important.>", objectives = "Use and equip a Utility Curio to your delve companion." }
WordHunterWoW_QuestEN[93965] = { title = "Pet Wranglin'", description = "Seems like you've got the spurs for this ride. Just takes a little gettin' used to is all.\n\nCritters of all kind are crawling around Eversong and beyond. Cute, cuddly, creepy--whatever strikes your fancy.\n\nYou look tough enough to nab your own. Why don't ya give it a try?", objectives = "Capture a Wild Pet in any Midnight zone.", completion = "You're back. Hope you found a critter you fancy.\n\nThere are plenty more where that came from. Reckon you'll wrangle 'em all? I leave that up to you." }
WordHunterWoW_QuestEN[93969] = { title = "Call Shot", description = "Critters of all kind are crawling around Eversong and beyond. Cute, cuddly, creepy--whatever strikes your fancy.\n\nYa might be used to havin' varmints bash heads until one was weak enough to nab. Got a new way to try. All you need is a crate. You've got one, yeah?\n\nJust throw the crate from the start. It's mighty effective, I tell ya.\n\nYou look tough enough to nab your own. Why don't ya give it a try?", objectives = "Capture a Wild Pet in any Midnight zone." }
WordHunterWoW_QuestEN[93970] = { title = "Researching the Storm", description = "The urgent nature of our mission to these lands should not preclude us from embarking on new and meaningful research. Long have my people studied the void, and any opportunity to break new ground must be seized. \n\nOur scouts have been finding peculiar void manifestations throughout Voidstorm. If my hypothesis is correct, I believe we can use our host's facilities to further refine and understand these samples.", objectives = "Help Anomander unlock the Research Console in Howling Ridge.", progress = "Please do not drop the sample.", completion = "Did you hear that? It most certainly did something! \n\nHuzzah!" }
WordHunterWoW_QuestEN[93979] = { title = "Lingering Memories", description = "Dimensius threatens us once more. There is no one who knows his methods better than his former Harbinger, Xal'atath. I would not say we can trust her, but we can work with her. She fears the All-Devouring's wrath after her betrayal.\n\nWe can't afford to turn away any potential ally. Think how many we will save from the Void Lord's hunger. Get your bearings in this city the four of us saved together. I will convince Alleria.", objectives = "Meet Alleria and Locus-Walker at the docks.", completion = "This is what we are fighting for, <name>. We can only save fragments of K'aresh, but we can prevent other worlds from sharing our dreadful fate." }
WordHunterWoW_QuestEN[93997] = { title = "Void Post Control", description = "Vidious is moving to claim Slayer's Rise, sending his proxies to occupy the Void Posts. I shall not be outmaneuvered.\n\nSeize full control of each of the Void Posts and eliminate any of Vidious's forces that try to stop you.", objectives = "Enter War Mode and seize full control of each of the Void Posts in Slayer's Rise.", completion = "You have done well. Your loyalty has earned you a great prize." }
WordHunterWoW_QuestEN[93998] = { title = "Guardian of the Tree", description = "Oi! You there!\n\nHave you seen those big shiny trees in the neighborhood? Yeah, well, some nasty little creatures keep popping up to burn them down or nick the goodies. Unacceptable! That trees are under official goblin protection!\n\nSo here's the deal: I need you to get rid of those creatures when they appear. Punt em, fling em, smash em, I don't care, whatever you have to do to protect the tree.\n\nI've set up some practice dummies for you to get the hang of things.", objectives = "" }
WordHunterWoW_QuestEN[93999] = { title = "Void Post Control", description = "Ziadan vies for control of Slayer's Rise, sending her proxies out to seize the Void Posts. Show her two can play at this game.\n\nStrike quickly: seize control of the Void Posts, slaying any who stand in your way.", objectives = "Enter War Mode and seize full control of each of the Void Posts in Slayer's Rise.", completion = "A difficult task, completed with skill. Your loyalty deserves a reward." }
WordHunterWoW_QuestEN[94005] = { title = "Stellar Stash", description = "", objectives = "" }
WordHunterWoW_QuestEN[94012] = { title = "Lost Lil' Strider", description = "Howdy, pardner. Folks at this here pet store asked for my help straighten' out this place. But while I was distracted, a hawkstrider chick I've been rearin' slipped out the front door. Prettiest purple plumes you ever did see.\n\nWould you do me the kindness of finding her and bringing her back for me? I take her for a stroll in the garden every so often. I'll betcha that's where you'll find her.", objectives = "Capture Tiff in the Gardens of Remembrance in Silvermoon City.", progress = "Ya find her?", completion = "Fine work. Even some of these handlers wouldn't have been able to track down that wily bird." }
WordHunterWoW_QuestEN[94031] = { title = "Bones of My Soul", description = "Do you have time to break a curse, {class}?\n\nI'm what remains of a loa speaker of Gral. I kept de prisoners in line on Gral's Belly. But we crashed, I died, and de prisoners escaped.\n\nMy powers didn't work on de livin' anymore. But they did work on de captain, who'd died with me.\n\nTerrified of his anger at my failure, I set up a ritual to trap him in de ship using my own bones.\n\nMy soul has leeched into de bones after all this time, and now I can't move them. Would you bring my bones to me?", objectives = "" }
WordHunterWoW_QuestEN[94035] = { title = "Meat for the Bones", description = "To move my soul out o' de bones and into me, I need to do a ritual.\n\nGral is de loa of many things, but mostly de sea. He's a shark. And he likes meat!\n\nGet meat from de sea creatures around here. It will be easier to perform de ritual with somethin' red and oozing to ground me.", objectives = "" }
WordHunterWoW_QuestEN[94036] = { title = "One Final Prisoner", description = "I cannot pretend I am any better than de captain.\n\nWe both enjoyed lording our power over de prisoners. When he'd lash out, I did not stop him.\n\nBut in our time trapped here together, I've reflected. De minute I wasn't useful to him, he got angry. And now I want this to end.\n\nI cannot enable him any more. Would you put him to rest?", objectives = "" }
WordHunterWoW_QuestEN[94040] = { title = "Meat and Bone and Soul", description = "We have everything we need for de ritual.\n\nMeet me at de Tooth o' Sargoth. You'll help me get my soul back in one piece, then this curse will finally be over.\n\nMay Gral judge me on de other side for my failures here.", objectives = "" }
WordHunterWoW_QuestEN[94052] = { title = "The Domanaar's Plan", description = "If I am to defeat Ziadan, I need information.\n\nMaps, strategy scrolls, battle reports, anything that gives me an edge!\n\nScour the Hate Spire and nearby grounds. Search every chest and cut down guards to find the information I need.", objectives = "Enter War Mode and collect 6 Ziadan's Battleplans from chests or slain guards.", progress = "Have you obtained the battle plans?", completion = "This information shall give me the edge in the upcoming battles." }
WordHunterWoW_QuestEN[94055] = { title = "The Domanaar's Plan", description = "To counter Vidious' foul plans, I need information.\n\nMaps, strategy scrolls, battle reports, anything that turns the battle in my favor!\n\nScour the Grief Spire and nearby grounds. Search every chest and cut down guards to find the information I need.", objectives = "Enter War Mode and collect 6 Vidious' Battleplans from chests or slain guards.", progress = "Have you obtained the battle plans?", completion = "This information shall give me the edge in the upcoming battles." }
WordHunterWoW_QuestEN[94056] = { title = "A Golden Pull", description = "A unique and valuable gift has been sent to me, hidden in the supply crates that drop upon Slayer's Rise. \n\nShould Ziadan obtain this gift instead, her insufferable gloating would never cease!\n\nEnter War Mode, and seize control of a supply crate. Then recover the gift for me!", objectives = "Enter War Mode and collect the Golden Vidious Card from a War Supply Crate in Slayer's Rise.", progress = "Have you obtained my gift?", completion = "This gift honors me, I knew you would succeed in obtaining it." }
WordHunterWoW_QuestEN[94057] = { title = "A Golden Pull", description = "A unique and valuable gift has been sent to me, hidden in the supply crates that drop upon Slayer's Rise.\n\nShould Vidious obtain this gift instead, his taunts would be incessant.\n\nEnter War Mode, and seize control of a supply crate. Then recover the gift for me!", objectives = "Enter War Mode and collect the Golden Ziadan Card from a War Supply Crate in Slayer's Rise.", progress = "Have you obtained my gift?", completion = "This gift honors me, I knew you would succeed in obtaining it." }
WordHunterWoW_QuestEN[94058] = { title = "Emissary of the Amani Tribe", description = "", objectives = "" }
WordHunterWoW_QuestEN[94210] = { title = "Feathering the Nest", description = "A house isn't quite a home without the perfect furnishings. It looked like there were some vendors in town. Perhaps it would be worth checking what they have in stock.", objectives = "Learn where to obtain Decor.", progress = "Have you met all the local vendors? They have some great furnishings available.", completion = "Did you find any good pieces for your house? We hope to have more vendors visit in the future, so be sure to check back often!" }
WordHunterWoW_QuestEN[94361] = { title = "The Abundant Life", description = "You are ready, acolyte! Ready to spread your wings or what have you?\n\nI have projected my presence into today's most active and tumultuous lands, rummaging about their natures and environs for areas ripe with abundance. With a little provocation from me, these forgotten corners are blooming bright with glorious harvestables!\n\nSeek me out! A crypt of phantasms in Eversong! A grove of verdant flora in Harandar! Even a quarry of living rock in Voidstorm! And, of course, right here too!", objectives = "Complete each Abundance event once. They are located in Eversong, Zul'Aman, Harandar, and Voidstorm.", progress = "Temperance, acolyte.\n\nThere is still more abundance to be collected yet.", completion = "Well done, fellow acolyte!\n\nLet our harvests be bountiful, our rewards glorious, and our lives abundant!" }
WordHunterWoW_QuestEN[94363] = { title = "The Gloves Are Off", description = "If you've found yourself an invite you'll be wanting to put it to good use, no?\n\nUse your Blood-Soaked Invitation first then talk to a Bouncer in the Brawlpub and get to brawling!", objectives = "Talk to a Bouncer in Bizmo's Brawlpub in the Deeprun Tram after using your Blood-Soaked Invitation." }
WordHunterWoW_QuestEN[94370] = { title = "Slithering Closer", description = "Do you bring tidings from Numia? She was supposed to be here and help me assess these fair flowers.\n\nShe must be occupied. The naga have encroached on my town and hers... they have kept to the beach so far, but that could change quickly.\n\nWill you check on my friend?", objectives = "Find Numia Golden in Goldenmist Village.", completion = "I will make it up to Fern. Thanks for speaking with her.\n\nAnd now, will you help me subdue this typical Farstrider? Nearly decapitated by a snapdragon, and he's acting like he just finished lunch!" }
WordHunterWoW_QuestEN[94371] = { title = "A Ranger's Dream", description = "Apprentices! Who can keep them tied down?\n\nTaemin was a particularly talented arcanist, but his head was always in the clouds. Or in the woods, really.\n\nInstead of studying, he buried his nose in storybooks! The legends of Eversong! The Rangers of old! Heroes of the Sin'dorei! He couldn't get enough, the dreaming fool!\n\nAnd now... no, he's not dead. Did I imply that?\n\nHe's just run off to join the Farstriders. Check in on him, won't you? See if he's come to his senses?", objectives = "Check in on Arcanist Taemin at Farstrider Hold.", completion = "It was good of you to check on me, but I'm committed to the Farstriders!" }
WordHunterWoW_QuestEN[94372] = { title = "The Gloves Are Off", description = "If you've found yourself an invite you'll be wanting to put it to good use, no?\n\nUse your Blood-Soaked Invitation first then talk to a Grunt in the Brawl'gar Arena and get to brawling!", objectives = "Talk to a Grunt in the Brawl'gar Arena in Orgrimmar after using your Blood-Soaked Invitation." }
WordHunterWoW_QuestEN[94379] = { title = "This Old Hearth", description = "It looks like your house is ready for an upgrade. This doesn't normally happen so fast, but you've really made an impression around here.\n\nHead on over to our general contractor for next steps.", objectives = "Level up your house.", progress = "Did you get your house upgraded?", completion = "Did the renovation go well? I hope it gives you a little more room for all the treasures you find in your adventures.\n\nBe sure to visit the general contractor again when you're next ready for an upgrade.\n\nOh, and a letter arrived for you while you were away." }
WordHunterWoW_QuestEN[94380] = { title = "Ranger Captain's Summons", description = "Pardon the intrusion, {name}!\n\nI'm delivering a summons from Ranger Captain Lilatha. She's requested your presence at her staging grounds overlooking the Bazaar near the north gate of Silvermoon.\n\nOur lands are once again under threat and we'll need all the support we can get.\n\nReport to her when you can!", objectives = "" }
WordHunterWoW_QuestEN[94381] = { title = "Outfitting and Allies", description = "Halduron Brightwing has made sure that our task force is well equipped to handle any threat. I want you to check in with our quartermaster, Maren Silverwing. She will help you get outfitted. \n\nI also want you to talk with our \"liaison.\" She is the troll with the guards. You may already know we are not alone in being targeted. \n\nBrightwing has reminded us that these enemies do not respect borders, so threats to Zul'Aman require our attention just as much as Eversong. We must deal with the troll.", objectives = "" }
WordHunterWoW_QuestEN[94382] = { title = "Ritual Problems", description = "To get right to it, I have laid out some lessons and some scout objectives for us as we approach the various dangers we might see in these ritual sites.\n\nI have also marked on your map the location of one of these rituals. Take care, as the magics we have seen woven at these sites can overwhelm even the most stalwart warrior.", objectives = "" }
WordHunterWoW_QuestEN[94383] = { title = "Ritual Interest", description = "I am here at the behest of the great Zul'jarra! May she lead her people to greatness.\n\nWe face dire threats. Your Captain General is focused on the martial stakes, but the terrible magics unleashed recently pose an even greater danger. Our scouts have discovered rituals that risk ruin for us all.\n\nYour Ranger Captain has recruited the Lady Darkglen, who appears to be a knowledgeable and capable ritual expert.\n\nSeek her out in the tent nearby to find out how best to approach these ritual sites.", objectives = "" }
WordHunterWoW_QuestEN[94384] = { title = "Ritual Studies", description = "This is not my first ritual. \n\nI have created a diagram that should help us approach and counter these rituals. You have gained valuable Field Research, now we need to put it to use. \n\nI have created a Research Diagram for you. It will enable powerful boons for you to use and counter the various challenges you will find in a Ritual Site.", objectives = "" }
WordHunterWoW_QuestEN[94385] = { title = "Void Assaults: Eversong Woods", description = "We are seeing a Void Assault in Eversong. We need you to head out immediately to counter these threats. I will mark the strikes on your map as our scouts identify them and direct your efforts from here.", objectives = "" }
WordHunterWoW_QuestEN[94386] = { title = "Void Assaults: Zul'Aman", description = "My scouts report a Void Assault in Zul'Aman. We need your help to counter these threats. \n\nI will direct you, and my scouts will continue to mark new activities on your map.", objectives = "" }
WordHunterWoW_QuestEN[94388] = { title = "Second Time's a Choice", description = "A little lesson. Trying to fool me twice is a grave error.\n\nMy dim-witted pupil has yet to return from their rendezvous with their acquaintance. Normally I would not bat an eye, but he has a journal of mine. I want that journal back.\n\nWould you be a dear and remind him?", objectives = "Remind Magister Meledor in the West Sanctum.", completion = "<Magister Meledor appears to be lost in thought...>" }
WordHunterWoW_QuestEN[94390] = { title = "Special Assignment: A Hunter's Regret", description = "", objectives = "" }
WordHunterWoW_QuestEN[94391] = { title = "Special Assignment: Push Back the Light", description = "", objectives = "" }
WordHunterWoW_QuestEN[94393] = { title = "Career Counseling", description = "How good are you at teaching, {name}?\n\nOne of my pupils, Kyltus, has been having particular trouble with deciding what path along the road of life he wants to pursue. \n\nPerhaps a talk with you will aid his tumultuous heart?", objectives = "Check in on Kyltus Bloodburn in the Sunstrider Isle.", completion = "Instructor Thalendir sent you?! I will have to give him my apologies.\n\nBut I am glad you are here. Could you lend me an ear?" }
WordHunterWoW_QuestEN[94396] = { title = "Down a Peg", description = "There seems to be a problem student at the academy.\n\nI have heard reports that a student, Tytalor Goldenblade, is stirring up trouble in Sunstrider Isle. I'd go myself but I have my hands full running practice here already.\n\nCould you go check on him and... educate him of his misgivings?", objectives = "Check in on Tytalor Goldenblade in the Sunstrider Isle.", completion = "Truly, I am incredibly talented!\n\n<Tytalor appears to be lost within his own thoughts.>" }
WordHunterWoW_QuestEN[94402] = { title = "Old War Grudge", description = "Ziadan has allied with some of the most die-hard Horde champions. The kind who despise peace and fight on whenever and wherever possible.\n\nShow them that Vidious also commands mighty champions!", objectives = "Enter War Mode, slay Gar'chak Skullcleave and bring me his Head.", progress = "Have you slain the enemy?", completion = "You make the Alliance proud! Vidious has authorized me to grant you a reward." }
WordHunterWoW_QuestEN[94403] = { title = "Old War Grudge", description = "Vidious has allied with some of the  most die-hard Alliance champions. The kind who despise peace and fight on whenever and wherever possible.\n\nShow them that Ziadan also commands mighty champions!", objectives = "Enter War Mode, slay Hardin Steellock and bring me his Head.", progress = "Have you slain the enemy?", completion = "You make the Horde proud! Ziadan has authorized me to grant you a reward." }
WordHunterWoW_QuestEN[94408] = { title = "Contract of Service", description = "It is not honor or glory that drives your kind to war...it is gold. You and your enemies are always paid for the blood you spill upon the battlefield.\n\nEvery enemy you slay in Slayer's Rise carries a contract from Ziadan. Bring me those contracts, and I will pay you what their loyalty once cost her.", objectives = "Collect 10 Contracts of Service off slain players in War Mode.", progress = "Are you here to deliver their contracts?", completion = "See I was correct. In the end the price of blood is always in gold." }
WordHunterWoW_QuestEN[94409] = { title = "Contract of Service", description = "It is not honor or glory that drives your kind to war...it is gold. You and your enemies are always paid for the blood you spill upon the battlefield.\n\nEvery enemy you slay in Slayer's Rise carries a contract from Vidious. Bring me those contracts, and I will pay you what their loyalty once cost her", objectives = "Collect 10 Contracts of Service off slain players in War Mode.", progress = "Are you here to deliver their contracts?", completion = "See I was correct. In the end the price of blood is always in gold." }
WordHunterWoW_QuestEN[94415] = { title = "Plumbing the Void", description = "", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative." }
WordHunterWoW_QuestEN[94416] = { title = "Rehoming Technology", description = "", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has allowed you to take a small selection of our technology back to your world, if you choose." }
WordHunterWoW_QuestEN[94417] = { title = "Crests of the Dawn", description = "Using what I've learned from Silvermoon's artisans, Cuzolth and I can infuse your gear with additional power!\n\nPowerful equipment requires Dawncrests to upgrade it to its full potential. These crests are rewarded through many different activities. Dawncrests have five tiers, and more dangerous tasks reward you with higher-tier crests. Adventurer Dawncrests are the lowest tier, but still quite powerful!\n\nBring me thirty Adventurer Dawncrests and we can help you upgrade your gear further.", objectives = "Acquire 30 Adventurer Dawncrests by defeating unique creatures, completing world activities, or by looting caches. Speak to Cuzolth to upgrade an Adventurer track item using those crests, then return to Vaskarn in Silvermoon.", progress = "If you're having a hard time finding Adventurer Dawncrests, you can search for hidden treasures around Eversong, Zul'Aman, Harandar, and Voidstorm. There's no shortage of those treasures!", completion = "This is wonderful. I'm excited for you to grow in power!\n\nAnd to advance my research, of course. But yes, your power is my top priority!" }
WordHunterWoW_QuestEN[94418] = { title = "Crest Transmutation", description = "Did you know that crests can be transmuted into different tiers?\n\nIf you find yourself with crests that are too powerful for the gear you've acquired, I can help you transmute those crests into lower tiers that you can use.\n\nAnd once all of your gear is sufficiently powerful, I'll be able to transmute your spare lower crests into higher ones!\n\nLet's practice the transmutation process. Here's a few Veteran Dawncrests. Speak to me and I can transform them into Adventurer Dawncrests for you.", objectives = "Bring 10 Veteran Dawncrests to Vaskarn in Silvermoon, then trade them for a Bundle of Adventurer Dawncrests.", progress = "If you lose those Veteran Dawncrests, you can find more from powerful creatures around Eversong, Zul'Aman, Harandar, and Voidstorm. I've heard there's quite a variety of them!", completion = "Remarkable!\n\nKeep in mind I can only transmute crests into a higher tier when you have outgrown their usefulness, and it will be a costly process. Thank you for all of your help, <name>!" }
WordHunterWoW_QuestEN[94423] = { title = "Sanctum Secure", description = "Our control here is only the beginning. Xal'atath has left other pockets of anomalies across the land. The defenses we've devised here can be used to secure those areas as well.\n\nTravel to Sunkiller Sanctum and construct five additional defenses to solidify our hold on that location.\n\nI will supply the Stormarion Core necessary to activate those defenses.", objectives = "Deploy 3 defenses at Sunkiller Sanctum." }
WordHunterWoW_QuestEN[94430] = { title = "Adventuring Gear", description = "{name}, you're just in time! I was exchanging research notes with the artisans here in Silvermoon all day. Did you know they can infuse weapons and armor with the power of the dawn itself? Fascinating!\n\nI've been itching to put some of these new techniques to the test. Bring me a piece of Adventurer equipment and I'll let you know what we need to make it more powerful.\n\nThere should be plenty of people in Silvermoon and beyond willing to reward you with some Adventurer equipment in exchange for your aid.", objectives = "Obtain a piece of Adventurer track gear, then return to Vaskarn in Silvermoon.", completion = "This piece of equipment will be perfect!\n\nI can help you make this more powerful, but we'll need some reagents." }
WordHunterWoW_QuestEN[94432] = { title = "Veteran Equipment", description = "We have only just begun to scratch the surface of how powerful your gear can become!\n\nHowever, every piece of equipment has a limit to how much it can be upgraded. The more powerful an item is at its baseline, the more powerful it will become as we upgrade it. An item's upgrade track determines which crests we must use to upgrade it.\n\nBring me a piece of Veteran equipment this time along with some Veteran Dawncrests. Just like before, Cuzolth will help you upgrade the item using those crests.", objectives = "Obtain a piece of Veteran track gear and 10 Veteran Dawncrests. Speak to Cuzolth to upgrade a Veteran track item using those crests, then return to Vaskarn in Silvermoon.", progress = "If you're having trouble finding a piece of Veteran equipment, try completing a Heroic dungeon or a challenging weekly activity in Eversong, Zul'Aman, Harandar, or Voidstorm. You can find more powerful gear this way!", completion = "You're a natural! It looks like you have a handle on things already.\n\nEvery time you want to upgrade a piece of equipment, the process works the same way. Bring us the item and the crests that go with it, then Cuzolth will help you upgrade it." }
WordHunterWoW_QuestEN[94444] = { title = "Choose a Path", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", objectives = "Talk to Chromie in Orgrimmar.", completion = "Carry your traditions with pride, for their roots intertwine within you.\n\nAln'hara bless your path." }
WordHunterWoW_QuestEN[94445] = { title = "Choose a Path", description = "Welcome to Stormwind, {race}. I invite you to explore our fair city. Say, you look like someone who appreciates the great outdoors! Elwynn is lovely this time of year.\n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of yours is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay, {name}!", objectives = "Talk to Chromie in Stormwind City.", completion = "Carry your traditions with pride, for their roots intertwine within you.\n\nAln'hara bless your path." }
WordHunterWoW_QuestEN[94446] = { title = "A Nightmarish Task", description = "Excellent work so far, {name}. \n\nBut there is always more to be done.\n\nGo out and hunt the most powerful targets available to us with all the fury our magic has to offer.", objectives = "" }
WordHunterWoW_QuestEN[94447] = { title = "Ophidia the Broodmother", description = "Zawadi safe, eh? Good. No harm should come to her. We need to deal with these oversized worms.\n\nJust over there, by de beach, is one of their broodmothers. Vile creature! Responsible for all de eggs you see 'round here. Kill her. Their invasion will stall, giving my people more time to organize a strike.\n\nI need to tend my wounds. I will hide and wait for you.", objectives = "" }
WordHunterWoW_QuestEN[94450] = { title = "Twenty Five Percent Completed", description = "We're still getting things setup for rewarding endeavors. This is a temporary quest to grant you community coupons.\n\nCommunity Coupons will normally be earned by completing endeavor tasks, not via a quest like this.", objectives = "We're still getting things setup for rewarding endeavors. This is a temporary quest to grant you community coupons.\n\ncommunity coupons will normally be earned by completing endeavor tasks, not via a quest like this.You will receive:" }
