WordHunterWoW_QuestEN[94455] = { title = "Home at Last", description = "It's time to cross the threshold into a new chapter.", objectives = "Approach your front door and enter your new house." }
WordHunterWoW_QuestEN[94457] = { title = "Midnight: Battlegrounds", description = "Battlegrounds stand as crucible where soldiers clash for honor, resources, and glory.\n\nEach victory hones your skill and strengthens your resolve.\n\nGo, test yourself against worthy foes and bring pride to your banner.", objectives = "Complete any Battleground in Midnight.Battlegrounds stand as crucible where soldiers clash for honor, resources, and glory.\n\nEach victory hones your skill and strengthens your resolve.\n\nGo, test yourself against worthy foes and bring pride to your banner.You will learn:" }
WordHunterWoW_QuestEN[94464] = { title = "Heritage of the Haranir", description = "You have travelled far and learned much of Aln'hara's grace.\n\nIt is time to return home and share the wisdom you have earned with your people.", objectives = "Tell Orweyna of your travels at the Den in Harandar.", completion = "You have seen many battles and met many peoples. Your journeys continue to bring us closer to the wisdom and grace of Aln'hara. \n\nSince you left, roots and vines began to rapidly grow within your old home. Eventually, their purpose became clear: armor, grown for you from the roots of the great trees as a blessing from Aln'hara herself!\n\nWear it with pride as you continue your journey, <name>. Thank you." }
WordHunterWoW_QuestEN[94469] = { title = "A Handful of Voidlight Marl", description = "", objectives = "Thanks to you, the singularity anchor survived another assault. Take this as a sign of our appreciation." }
WordHunterWoW_QuestEN[94470] = { title = "A Cluster of Voidlight Marl", description = "", objectives = "" }
WordHunterWoW_QuestEN[94471] = { title = "A Trove of Voidlight Marl", description = "", objectives = "" }
WordHunterWoW_QuestEN[94474] = { title = "The Great Vault", description = "In wake of recent events, the Vanguard of the Light has recovered and preserved relics of exceptional power and craftsmanship. To safeguard these treasures from prying eyes, the Magisters of Silvermoon have conjured a vault within Silvermoon's bank.\n\nOnly the most proven of champions may earn the right to draw from its splendor. If the Light deems you worthy, you may be bestowed an artifact of great power.", objectives = "Obtain a piece of loot from the Great Vault." }
WordHunterWoW_QuestEN[94475] = { title = "The Voidspire: Flicker in the Hollow", description = "There's little light in these lands. What remains is fractured, hidden, or fading.\n\nFetch me Echoes of Radiance and I will grant you passage where no path should exist.", objectives = "" }
WordHunterWoW_QuestEN[94476] = { title = "The Voidspire: Flicker in the Hollow", description = "There's little light in these lands. What remains is fractured, hidden, or fading.\n\nFetch me Echoes of Radiance and I will grant you passage where no path should exist.", objectives = "" }
WordHunterWoW_QuestEN[94477] = { title = "The Voidspire: Flicker in the Hollow", description = "There's little light in these lands. What remains is fractured, hidden, or fading.\n\nFetch me Echoes of Radiance and I will grant you passage where no path should exist.", objectives = "Collect 3 Echoes of Radiance within The Voidspire on Mythic difficulty." }
WordHunterWoW_QuestEN[94478] = { title = "Emissary of Silvermoon Court", description = "", objectives = "" }
WordHunterWoW_QuestEN[94492] = { title = "Paragon of the Slayer's Duellum", description = "", objectives = "Speak with Thraxadar in Masters' Perch.You will receive:" }
WordHunterWoW_QuestEN[94519] = { title = "What Hope in the Light?", description = "Ever since the terrible events of the Voidspire, Arator has suffered. He has kept to himself, or prayed alone at the Dawnwell.\n\nWe all feel the loss of Alleria and Turalyon, but Arator only reunited with them recently, after their long fight against the Burning Legion.\n\nI worry that if he is left to his own thoughts for too long, he may not come out of this the same.\n\nLet us go to the Dawnwell and check on him.", objectives = "" }
WordHunterWoW_QuestEN[94520] = { title = "Resurgence in Deatholme", description = "While we cannot know yet where Xal'atath has gone, or if Alleria and Turalyon are still alive, we can still pursue information.\n\nRiftblade Maella has kept me up to date on the Twilight cultists. They have been gathering strength, gathering numbers, and seem to be searching for... something. Now is the time to act.\n\nLet us travel to the Ruins of Deatholme and see why the cultists there have reinvigorated themselves.", objectives = "" }
WordHunterWoW_QuestEN[94521] = { title = "The Direct Method", description = "The information we need has to be here! We just need to get it from the Twilight's Blade.\n\nThere's nothing wrong with the direct method. Apply force, and see what you can learn.\n\nI brought Benthar's Scarlet Spire, the relic we rescued from the Scarlet Crusade. It's already been used to help protect the Sunwell, and maybe it can help us here.", objectives = "" }
WordHunterWoW_QuestEN[94522] = { title = "They Always Write It Down", description = "An organization as widespread and diverse as the Twilight's Blade must need to write down their objectives.\n\nOr at the least, whatever they have collected should shed light on what they're up to. \n\nSee if you can find anything that points to their current direction.", objectives = "" }
WordHunterWoW_QuestEN[94523] = { title = "My Poor Beautiful Self", description = "Oh, please don't hurt me!\n\n<The pathetic voidling cowers at the sight of you.>\n\nIt's not my fault. I could have gotten them out of this.\n\nIt's those new commanders! They have led the Twilight cult down the wrong path.\n\nGlaivh is the worst of them. If he was gone, perhaps, perhaps...", objectives = "" }
WordHunterWoW_QuestEN[94524] = { title = "Under New Management", description = "The rank-and-file Twilight's Blade didn't have much to tell us, but their new leadership may know more.\n\nYou've already bested one of them. Let's see if there are others who also aspire to lead, and learn what they know.\n\nYou can still use the Scarlet Spire on them. If Umbric won't use his magic, then perhaps the Light will make them talk.\n\nThey should be below us, in the chasm.", objectives = "" }
WordHunterWoW_QuestEN[94525] = { title = "A Comeback Story", description = "No one notices a creature like me...\n\nNo one appreciates how much I have lost.\n\nBut in that underestimation... knowledge.\n\nHelp me regain some strength, and I will regain the words you need.", objectives = "" }
WordHunterWoW_QuestEN[94526] = { title = "Verifiably Untrustworthy", description = "As soon as we met that little voidling, I thought there was something I recognized. \n\nHow Antenorian survived, I know not. But it's clear that we cannot let him get away. We need to know what he knows, and then his time on Azeroth should truly be ended.\n\nCome, let's get what we need and finish this.", objectives = "" }
WordHunterWoW_QuestEN[94527] = { title = "Null Space", description = "Arator jumped after Antenorian like a man possessed. He's so blinded by this crusade, he... he must not know how dangerous it is for someone like him to simply leap into the Void blindly.\n\nNo, we must think calmly about this. Analyze the situation.\n\nWe have no way of knowing what's on the other side of that portal. \n\nBut we must go in. We must find Arator.", objectives = "" }
WordHunterWoW_QuestEN[94528] = { title = "Carving Out Room", description = "I need a moment, after what we just went through. I feel like my body is fighting with itself.\n\nBut we're in hostile territory. I can't let us fall to enemies just because I was... because I had to jump in after him. We need to keep Umbric safe.\n\nCan you clear out the Twilight's Blade around us to give us some room to recover?", objectives = "" }
WordHunterWoW_QuestEN[94529] = { title = "A Dark Shadow Looms", description = "We are lucky to have survived that tear through the Void, but now we are presented with an opportunity.\n\nAntenorian must have been going somewhere in this direction, which is why we find ourselves no longer in Eversong. But we interrupted his journey, and he is still here somewhere.\n\nI can feel it like a chill along my spine.\n\nSee if you can find any more information from the Twilight's Blade here. What of that gateway that Antenorian spoke of? What of those Amani prophecies?", objectives = "" }
WordHunterWoW_QuestEN[94530] = { title = "The Call of the Void", description = "I've been able to trace where Antenorian fled. He is more powerful than he was before, after that jaunt through the void space. \n\nFortunately, this makes him easy to track. He's below us, in an open cavity underground. I can open a portal there.\n\n<Umbric glances over at Arator.>\n\nI hope that we can put an end to this, and Arator is no worse for wear. When we started this, I thought we would find a few scrolls, uncover their plan, and put a stop to it ourselves.\n\nI did not anticipate this.", objectives = "" }
WordHunterWoW_QuestEN[94531] = { title = "Like Mother, Like Son", description = "<Arator quietly seethes.>\n\nWe need to tell Lor'themar what we've learned. Not because I want to stop looking for Xal'atath, but this is important.\n\nCome, let's leave Zul'Aman and return to Silvermoon.", objectives = "" }
