WordHunterWoW_QuestEN[94623] = { title = "Building the Voidforge", description = "I have been considering how I may offer you greater strength, my friend. I've come up with something, but I need your help building a proper Voidforge.\n\nWhat? Oh, fear not, all my ulterior motives are still aligned with your cause. For now.\n\nTo begin, I need one Elementary Voidcore. You will be able to find shards from the more powerful foes you habitually encounter. Inflict your usual violence, return the shards, and I can weave them back into a true Voidcore to serve as the forge's foundation.", objectives = "Deliver Elemental Voidcore Shards from Midnight Season 1 raid bosses, Bountiful Delves, and Mythic+ dungeons to begin constructing the Voidforge." }
