WordHunterWoW_QuestEN[94675] = { title = "Voidforge Reforged", description = "As ever, your persistence is admirable.\n\nIt's time to put the finishing touches on the Voidforge, and then the real work can begin.", objectives = "" }
WordHunterWoW_QuestEN[94677] = { title = "The Missing Rootwarden", description = "Something keeps troubling me about this, {name}. Where is the Rootwarden?\n\nRuia has a solemn duty to watch over the World Tree and the land around it. He should be here, with his people in need. So where could he be when they are in crisis? What is he thinking?\n\nI am sure that we can find clues to where he has gone if we search his town. Perhaps we can learn more about his state of mind along the way.", objectives = "Find 3 Ruia's Musings in Har'alnor.", progress = "The Rootwarden should be here. We must find out what would be so pressing that would take him away from his responsibilities.", completion = "This is troubling news. The Lightbloom hasn't seemed to affect any haranir thus far. Has it somehow infested the Rootwarden? Or is this his pride speaking? He's always been a zealous one, but...\n\nWe must move quickly." }
