WordHunterWoW_QuestEN[94790] = { title = "Research Console: Exploring the Void", description = "No rest for the researchers, as they say.\n\nAs much as I would love to go traipsing around this blasted voidscape, I need to remain at this post. But you! You can be our eyes and ears in the abyss.\n\nGo and explore the Voidstorm, maybe we can find some additional samples to feed into the console.", objectives = "Complete 3 World Quests for Void Researcher Anomander in Howling Ridge.", completion = "More samples, excellent! The console hungers..." }
WordHunterWoW_QuestEN[94794] = { title = "Fine Fashion Funding", description = "", objectives = "Thank you for your assistance. Please accept this token as thanks." }
WordHunterWoW_QuestEN[94795] = { title = "Special Assignment: Agents of the Shield", description = "", objectives = "" }
WordHunterWoW_QuestEN[94796] = { title = "Curing Curse Resistance", description = "Now that the Hoarder is gone, the fish population has boomed. There's a flood of fish with no curse at all!\n\nCaptain Tokka wants to study these curse-resistant fish. Go and collect a few of their livers so we can see what keeps them swimming.\n\nIf we want to use the venom-curse for ourselves, we need more cursed fish!", objectives = "" }
WordHunterWoW_QuestEN[94798] = { title = "Ssak'mozek's Desire", description = "Captain Tokka finished the lure for Ssak'mozek. It's time to kill the beast!\n\nTake the lure into the marsh, near the wreck of Pa'ku's Talon. Ready yourself, then place it on the rocks there.\n\nSsak'mozek will be drawn to the lure. Kill it.", objectives = "" }
WordHunterWoW_QuestEN[94800] = { title = "Crushed Crabs", description = "Hegvosh the Hoarder is back!\n\nHe's already started killing anything that gets in his way. This time, he's stomped on all of our crab traps in the south.\n\nSalvage any working trap pieces you find. We'll need to rebuild them.", objectives = "" }
WordHunterWoW_QuestEN[94802] = { title = "Death from the Dead", description = "Ssak'mozek always has three heads. Captain Tokka's lure targets each of them.\n\nThe next piece of the lure is ethereal beads from ghosts on the Isle. They exist somewhere between here and the beyond and shine in just the right way that the hydra can't ignore them.\n\nYe can find some of these beads in the Crypt of the Lost Mason. Be careful--the ghosts may not like you entering that place.", objectives = "" }
WordHunterWoW_QuestEN[94803] = { title = "Going for the Crown", description = "The final pieces of Captain Tokka's hydra lure are feathers from the Children of Ula'tek themselves.\n\nSsak'mozek is trained to listen to the orders of these monsters. It lies in wait for them to call it from the murky depths. The lure can't work without something tying it to Ssak'mozek's masters.\n\nAny of the children at the Gate of the Eastern Fang will have feathers perfect for the lure. Bring as many as you can.", objectives = "" }
WordHunterWoW_QuestEN[94804] = { title = "A Collection of Rot", description = "Have you noticed fewer fish on the south side of Atal'Utek lately? That's the Hoarder at work.\n\nHe's this big ugly sea giant we can't seem to shake. You'll know you've found him when you see piles of dead fish rotting away.\n\nMake him think twice about taking too much from these waters.", objectives = "" }
WordHunterWoW_QuestEN[94805] = { title = "The New Hoard, Poached", description = "The Children of Ula'tek eat venom-cursed fish straight from the water. Now that we've made the fish stronger, the children have gone into a feeding frenzy!\n\nCaptain Tokka says to stop the poaching. The children have plenty of venom already!", objectives = "" }
WordHunterWoW_QuestEN[94806] = { title = "Wriggling and Wet", description = "Captain Tokka wants us to fish for Ssak'mozek.\n\nThe Children of Ula'tek raise a hydra more vicious and venom-cursed than all the rest. We've caught and killed it before, but they always raise another and give it the same name: Ssak'mozek.\n\nWe're going to craft one of Tokka's best lures to draw it in.\n\nStart by collecting the legs of leeches. When broken, they have a smell the children and their creations cannot resist.", objectives = "" }
WordHunterWoW_QuestEN[94808] = { title = "LFGDungeons - Midnight - Normal Random - 1st", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
