WordHunterWoW_QuestEN[94813] = { title = "Fine Fashion Funding", description = "", objectives = "Thank you for your assistance. Please accept this token as thanks." }
WordHunterWoW_QuestEN[94815] = { title = "HIDDEN QUEST - Special Assignment: The Grand Magister's Drink [DNT]", description = "", objectives = "" }
WordHunterWoW_QuestEN[94816] = { title = "Fine Fashion Funding", description = "", objectives = "Thank you for your assistance. Please accept this token as thanks." }
WordHunterWoW_QuestEN[94831] = { title = "An Idol in Hand", description = "<The idol appears to be a figure of Ohn'ahra carved from serevite, an ore used in many titan temples.\n\nPreservationist Kathos would surely be interested in this.>", objectives = "Return the Idol of Ohn'ahra to Preservationist Kathos in Valdrakken." }
WordHunterWoW_QuestEN[94834] = { title = "Blessings of Abundance", description = "<This idol proves the depth of your bond with abundance.\n\nSpeak with Du'gal at the Altar of Blessings in Amani'Zar to begin worshipping Dundun.>", objectives = "Speak with Du'gal at the Altar of Blessings in Amani'Zar.", completion = "Ah, an Idol of Abundance.\n\nDe lord of glory and plentitude must favor you highly above his many other acolytes." }
WordHunterWoW_QuestEN[94835] = { title = "Early Morning Training", description = "Interested in enrolling in a training program? Some of the strongest warriors have emerged from hard work and dedication. \n\nWith some practice, {name}, you surely can join their ranks. Begin today!", objectives = "" }
WordHunterWoW_QuestEN[94836] = { title = "Late Night Training: Week 1 of 3", description = "Welcome back to this multi-course training - only a few weeks left! Let's put into practice what you learned last week. Go and participate in Battlegrounds in the Training Grounds or against other combatants, then return back to me.", objectives = "" }
WordHunterWoW_QuestEN[94837] = { title = "Midnight Training: Week 2 of 3", description = "You're over half way done with your training! Again, let's take some of the lessons you have learned previously and apply them in the battle fields. Enter Training Grounds or Battlegrounds then return to me.", objectives = "" }
WordHunterWoW_QuestEN[94838] = { title = "Final Training: Week 3 of 3", description = "This is the final week of training. Take all of the lessons you've learned and put them into practice in the Training Grounds or against other players. Once complete, speak with Captain Dawnrunner in Falconwing Square.", objectives = "" }
WordHunterWoW_QuestEN[94839] = { title = "Blessings of Peril", description = "<This idol proves the depth of your bond with peril.\n\nSpeak with Du'gal at the Altar of Blessings in Amani'Zar to begin worshipping Puul.>", objectives = "Speak with Du'gal at the Altar of Blessings in Amani'Zar.", completion = "An Idol of Peril...\n\nMany shy away from de realm of perils. There is much danger surroundin' de immense power Puul blesses their worshippers with.\n\nWill you risk your life for it?" }
WordHunterWoW_QuestEN[94840] = { title = "Blessings of The Depths", description = "<This idol proves the depth of your bond with the Depths.\n\nSpeak with Du'gal at the Altar of Blessings in Amani'Zar to begin worshipping Pahk.>", objectives = "" }
WordHunterWoW_QuestEN[94844] = { title = "Voidscar Arena: For My Horde", description = "We must repel this attack.\n\nYour Horde is strong. You do not give in to the hypocritical claims of the Alliance. You do not let them besmirch your honor.\n\nI want my forces to learn from you. Go, take this Voidclarion. Use it to inspire my void minions.\n\nLet them see the power of the Horde.", objectives = "Empower 8 Hatebound forces at the Bastion of Might in Slayer's Rise.", completion = "Good. My minions must grow stronger." }
WordHunterWoW_QuestEN[94845] = { title = "Voidscar Arena: The Bastion of Might", description = "Vidious presses an attack. I do not see this Alliance he recruited, but monsters.\n\nIllogical. Vidious would not recruit another force until we had our fun with the recent additions.\n\nFight these monsters. Find out what they are. Bring me evidence.\n\nPerhaps you need a cause to fight for beyond amusement? If Vidious tires of me, he will turn his conquest to Azeroth next. You'll want to stop that, right?\n\nThen aid me.", objectives = "Collect 12 Spiteful Shadowgraft from wild creatures in the Bastion of Might.", progress = "What trickery have you found?", completion = "Shadowgraft? Pathetic.\n\nOnly domanaar with less skill and intelligence use it. It empowers creatures--makes them blind with violent urges.\n\nBut the creatures lose all cunning. All interest. It is a single flavor, not the complex notes of heartache and betrayal. It is boring." }
WordHunterWoW_QuestEN[94847] = { title = "Preparations Underway", description = "As you may or may not recall, I once helped young paladins obtain their first armored mount.\n\nIt was a tedious task that involved months of obtaining materials and sending them all over Azeroth.\n\nThankfully, times have changed and we now have most of those materials at hand. That being said, I wish to help you obtain a new mount, something worthy of your title as Highlord.\n\nIn order for us to begin, I only require that you obtain a barding for us. Something strong, thick, and heavy.", objectives = "Obtain a Stonehide Leather Barding from a leatherworker. You may also obtain it from the auction house if you're not a leatherworker or don't know a leatherworker.", completion = "<Grayson examines the barding.>\n\nThis is... well, a good start, Highlord. But I think it will have to be strengthened a bit." }
WordHunterWoW_QuestEN[94848] = { title = "Voidscar Arena: Pre-Provoked Violence", description = "Vidious, using shadowgraft? Unbelievable. He is better than this.\n\nHow dare he disappoint me.\n\nI need no shadowgraft to convince mighty {class}s like you to fight for me.\n\nShow him the error of his ways before he disappoints me further and abandons this conflict in favor of helping Xal'atath conquer Azeroth.\n\nTake the fight to him. Siege his bastion. And if you do not wish to stain your hands with Alliance blood, there are many void minions awaiting your prowess.", objectives = "Slay Void creatures or players in the Bastion of Valor in Slayer's Rise.", completion = "So, Vidious is also under attack by shadowgrafted monsters? \n\nI see. \n\n<Ziadan almost smiles.> \n\nSo, he did not betray my expectations after all. Perhaps we keep him alive a little longer. \n\nBut there is a third. An interloper." }
WordHunterWoW_QuestEN[94849] = { title = "Voidscar Arena: A Familiar Grudge", description = "Vidious will have a favorite, much like I do: a mortal from your world filled with grief turned to violence.\n\nThey do not have the support of your leaders, but they will always have support from us domanaar.\n\nFind this favorite. I hear of a warlock that has slain many Horde. I feel their grief wafting in the air. They are so lost in it, they would give up the war to save Azeroth for a chance to kill your people.\n\nGo. Savor the fight.", objectives = "Slay Emrin Sparkpox at the Bastion of Valor in Slayer's Rise.", completion = "Good work. The mortal was blinded by their pain, so they never would have listened to reason. \n\nAll they cared for anymore was the fight." }
WordHunterWoW_QuestEN[94850] = { title = "If You Build It", description = "If we wish to achieve a sustained connection to Xoroth, we'll need a particularly resilient portal. Unfortunately, we can't just summon this one up from the ground.\n\nI will need you to gather the requisite materials. Once we have them, I will have the mo'arg begin construction at once. \n\nHere's the list of what you'll need.", objectives = "Collect 5 Felslate, 3 Chaotic Spinel and an Unbending Potion. These can be gathered and crafted using profession skills or purchased on the Auction House.", completion = "Excellent. This Unbending Potion should shore up the Felslate enough to hold the portal's structure, and these Chaotic Spinel crystals should focus the portal's magic nicely.\n\nI will set the mo'arg to work posthaste." }
WordHunterWoW_QuestEN[94855] = { title = "Voidscar Arena: Setting It Aside", description = "So, we have another enemy? One who would get in between me and Vidious?\n\n<Ziadan tightens her fist around her weapon.>\n\nUnacceptable.\n\nThe Voidscar Arena to the north is the most strategic position outside of our bastions. An interloping domanaar will have staged their forces there, I guarantee it.\n\nI can set aside my quarrel with Vidious long enough to deal with this shared threat. Fortunately for you, he hasn't brought his Alliance forces with him.", objectives = "Meet the domanaar at the Voidscar Arena in Slayer's Rise.", completion = "Who dares stage forces here? Without announcing themselves?\n\nNoxian? Decimus? We will root them out and make them pay." }
WordHunterWoW_QuestEN[94865] = { title = "Special Assignment: What Remains of a Temple Broken", description = "", objectives = "" }
WordHunterWoW_QuestEN[94866] = { title = "Special Assignment: Ours Once More!", description = "", objectives = "" }
WordHunterWoW_QuestEN[94867] = { title = "Lost in Atal'Abasi", description = "Tolbani and Jehnira have been missin' for some time. Last I heard, dey were scoutin' Atal'Abasi for supplies.\n\nThat area is covered in murlocs. Too many of 'em is dangerous even for an Amani.\n\nFind dem and make sure dey alright!", objectives = "Find Tolbani and Jehnira in Atal'Abasi.", completion = "Vakala sent you? She was right to think dis place was dangerous." }
WordHunterWoW_QuestEN[94868] = { title = "It Takes Two", description = "Jan'alai is a hen! And dat means eggs!\n\nDe eggs of de loa are volatile! Dey must be hatched carefully. My family carried dis honor for generations, but de tradition died when my older brothers followed de false promises of Zul'jin. Sadly, I am de only brother left, and we need two hatchers for de ritual!\n\nFind my niece, Shaja, down by de shore. She is too young to know de ritual, but de loa's favor flows through her veins as it did my brothers'. It is time for her to know this honor.", objectives = "" }
WordHunterWoW_QuestEN[94869] = { title = "Hungry Hungry Hatchlings", description = "We will soon be blessed with eggs! Jan'alai has told me so. And once dem eggs hatch, we'll have many hungry mouths to feed! Dey will crave somethin' soft, delicate, and pungent.\n\n<Brek eyes you up and down.>\n\nYa best scurry down to de shore and find somethin' to tempt de hatchlings with or dey may take a nibble out of you!\n\n<Brek laughs.>", objectives = "" }
WordHunterWoW_QuestEN[94870] = { title = "Eggstra Protection Never Hurts", description = "De eggs are nearly ready!\n\n<Brek glances eagerly at both clutches of eggs.>\n\nYa may know somethin' about dis, eh? Jan'alai tells me so. What ya lack in blood, ya make up for in spirit. Help me teach Shaja! Ya spirit alone is not enough for dis ritual. De eggs are imbued with de power of de loa herself and will burst with fiery energy!\n\nWe can protect ya from dis, but first we need feathers. Loa feathers! Collect dem from around de temple... unless ya dare ask de loa herself!", objectives = "" }
WordHunterWoW_QuestEN[94871] = { title = "Eversong", description = "Magistrix Landra Dawnstrider has sent a request for aid in dealing with the local Lightbloom. While typically harmless, it has recently begun to grow at an incredible rate.\n\nMeet up with Arator in Fairbreeze Village to investigate the threat and provide what assistance you can.", objectives = "Journey to Fairbreeze Village.", completion = "The wildlife is going out of control!" }
WordHunterWoW_QuestEN[94882] = { title = "Perfect Timing", description = "All is ready! I will now guide ya both through de hatchin' ceremony!\n\nTalk to Shaja and she will use de feathers to protect ya from dem powerful loa energies.", objectives = "" }
WordHunterWoW_QuestEN[94883] = { title = "Like Dragonhawks to a Flame", description = "I know my uncle can seem... off at times. His talk of de loa always felt like childhood stories to me.\n\nBut ever since Jan'alai returned, I feel her energy too! She flickers, she smolders, she burns red hot. She also brings warmth, light, and life!\n\nBut what I feel from her right now is distress--dat of a mother hen counting her chicks but comin' up short.\n\nLet's check on de hatchlings. We can cover more ground if we split up.", objectives = "" }
WordHunterWoW_QuestEN[94909] = { title = "Blessings of Pestilence", description = "<This idol proves the depth of your bond with pestilence.\n\nSpeak with Du'gal at the Altar of Blessings in Amani'Zar to begin worshipping Mot'amra.>", objectives = "Speak with Du'gal at the Altar of Blessings in Amani'Zar.", completion = "Many dread Mot'amra. And they aren't wrong to.\n\nBut pestilence, disease, death--these are natural occurrences. Those dat brave their own fear unlock de powerful understandin' of how to cure--or manipulate--these forces." }
WordHunterWoW_QuestEN[94910] = { title = "Blessings of Growth", description = "<This idol proves the depth of your bond with growth.\n\nSpeak with Du'gal at the Altar of Blessings in Amani'Zar to begin worshipping Oe.>", objectives = "" }
WordHunterWoW_QuestEN[94920] = { title = "Hal'hadar Battery Core", description = "<The Hal'hadar battery core has been damaged, exposing its inner workings.\n\nAmidst the thin energy wires and familiar metalwork seen in K'areshi technology, you spot gleaming yellow crystals fitted into a golden frame. Small runic letters on the metal are inscribed under it.\n\nPerhaps one of the ethereals in the Howling Ridge in the Voidstorm could help identify this.>", objectives = "" }
WordHunterWoW_QuestEN[94932] = { title = "Bindings of the Windlord", description = "With Thunderaan risen again as the lord of Skywall, there may indeed be an arrangement you can make in exchange for those wretched implements. But one binding is of no use on its own.\n\nReturn to me with both bindings, and with powerful enough ore to bind them, and I will arrange your audience with Thunderaan the Windlord.", objectives = "Retrieve both Bindings of the Windlord and 10 Infernal Brimstone.", progress = "Yes, <race>?", completion = "And so you return with the bindings in hand. The Firelord shall be very displeased to have lost these." }
WordHunterWoW_QuestEN[94933] = { title = "Lessons in the Void", description = "Ah, you're there!\n\nOur esteemed Magister Umbric has tasked me with wrangling an able-bodied champion to assist him. An apprentice of his, Leona Darkstrider, is investigating the techniques and methods of the illidari.\n\nIt appears her inquiries may have put her in a bit of trouble.\n\nThe Magister can fill you in. He's in K'aresh now, and he's allowed me to open the way for you if you require transportation.", objectives = "Meet up with Umbric in Shand'orah in K'aresh.", completion = "I'm glad you've chosen to join me here, <name>." }
WordHunterWoW_QuestEN[94936] = { title = "A Bond of Brothers", description = "My brother Tekkan and I were part of a team. Our friend Kariz died fighting de snakes.\n\nKariz's younger brother, Jabat, was consumed by vengeance. He is young and hot-headed, blind to his actions. He took off to kill de snakes. He is in great danger.\n\nThe Right Spear doesn't want to send a rescue, and I won't let their mother cry twice. We are going to get Jabat.\n\nWe need to plan an escape route for when we find Jabat. Tekkan can handle snake burrows with his explosives, but we need a muscle. You in?", objectives = "" }
WordHunterWoW_QuestEN[94937] = { title = "Too Quiet on the Northern Front", description = "I only have one small explosive left. Even if Aol'ggin is right about my methods, we can't go back now. I...\n\n<Tekkan chokes on his words, then clears his throat.>\n\nWe can do dis. You lure de snakes out and deal with dem so I can safely blow up de burrow. De escape route will be cleared after dat.", objectives = "" }
WordHunterWoW_QuestEN[94941] = { title = "Saving Recruit Jabat", description = "That large snake was the one who killed Kariz. And now I see Jabat is wounded and in danger. Tekkan is not responsive. I don't know what is wrong with him. There is no time to waste and I don't want to ask what else can go wrong. Dis is bad luck.\n\nCheck on Jabat or take out de large snake right away. Whatever you decide to do first, dat large snake must die.", objectives = "" }
WordHunterWoW_QuestEN[94954] = { title = "Darkspear Dash", description = "Today, celebrate da Darkspear footrunners. \n\nLong ago, our footrunners ran 'round all da troll empire deliverin' important messages. Dey carried their messages through battle an' storm an' were famous for dey courage. \n\nToday we be celebratin' not dey courage in war, but da courage of some of da messages dey carried--messages of peace an' hope for a better world.\n\nHelp us send a message of hope by joinin' our symbolic run ta Silvermoon. \n\nYa be ready? Well go, mon!", objectives = "" }
WordHunterWoW_QuestEN[94957] = { title = "War of Light and Shadow", description = "The Vanguard has begun to rally its forces to confront the Devouring Host.\n\nReport to Lady Liadrin at the Sunwell to join the offensive.", objectives = "" }
WordHunterWoW_QuestEN[94993] = { title = "Adventuring in Midnight", description = "The Void encroaches on Azeroth from all sides. Visit the Scouting Map in the Sanctum of Light and choose where you will make your stand.", objectives = "Review the Scouting Map and choose where to begin the Midnight campaign." }
WordHunterWoW_QuestEN[94995] = { title = "To Dye For", description = "", objectives = "Welcome, neighbor! I've got just the thing for you here. These dyes I have here will let you give the decor you buy from our local decor vendors an extra pop of color. Take these and try them out, no charge. Be careful, though. Each only works once.\n\nAnd if you want more, alchemists and scribes can grind up herbs to create pigments, when use those pigments at this dye station to create more dyes. You can also probably find them on the Auction House, if you're not interested in making your own." }
WordHunterWoW_QuestEN[95008] = { title = "Adventuring in Midnight", description = "It's rare that we get to choose our paths in life, but you seem like someone who's seen it all before.\n\n<Soridormi winks.>\n\nDon't dally, this war won't win itself. Go to the Sanctum of Light. Choose where you'll make your first stand.", objectives = "Review the Scouting Map and choose where to begin the Midnight campaign." }
WordHunterWoW_QuestEN[95009] = { title = "Doing the Dash", description = "Have you heard about the race today?\n\nThousands of trolls are gathering to run to Silvermoon City for a celebration!\n\nKalaya could tell you more. They're setting up at the Echo Isles now!", objectives = "" }
WordHunterWoW_QuestEN[95012] = { title = "Run On Gnome", description = "Have you heard about the race today?\n\nThousands of gnomes are preparing to run from New Tinkertown to Booty Bay in celebration!\n\nMina Gleespanner could tell you more. They're just about to start!", objectives = "" }
WordHunterWoW_QuestEN[95021] = { title = "Prey: Janoa the Fang (Nightmare)", description = "This creature has established a reputation for particularly vicious ambushes. Envenomed fangs flashing in the dark, followed by frenzied thrashing and then... stillness. \n\nSee if you cannot give it a taste of its own venom.", objectives = "" }
WordHunterWoW_QuestEN[95022] = { title = "Prey: Kursak the Coiled (Nightmare)", description = "Do not let this serpentine monstrosity get close, {name}, lest you have the life squeezed out of you. My servants recently found one of its unfortunate victims.\n\nLike a fistful of mashed grapes...\n\nApologies, I lost myself for a moment there.", objectives = "" }
WordHunterWoW_QuestEN[95023] = { title = "Prey: Batani the Scaled (Nightmare)", description = "I have heard that this creature has scales so thick and sharp you could use them to filet a fish. Do not let its diminutive stature fool you, {name}, it was bred for one purpose. \n\nTo kill. \n\nFortunately, not being killed is something you've grown quite proficient in.", objectives = "" }
WordHunterWoW_QuestEN[95024] = { title = "Prey: Kadani the Claw (Nightmare)", description = "The claw! A miracle of the natural world. An appendage located at the cutting edge of murderous millennia. This creature is all claw and cunning, and you would do best to not fall prey to its violent nature.", objectives = "" }
WordHunterWoW_QuestEN[95069] = { title = "Torn Twilight Missive", description = "<The Twilight Missive reads:\n\n\"Our search presses on yet we remain as divided as ever. If we don't unite, then we truly deserved to be abandoned by her!\n\nOf our surviving Speakers, two refuse my missives.\n\nLazaar rallies survivors in the ruins of Deatholme, while Ger'lock amasses a host at the Broken Throne.\n\nThe others have yet to declare for them, which buys us time to continue our search.\n\nWe may yet salvage our broken cause.\"\n\nThe Ranger Captain will want to see this.>", objectives = "" }
WordHunterWoW_QuestEN[95070] = { title = "Permafrosted Keystone", description = "<Several void-touched runes flicker across the keystone's surface before dissipating one by one. As the last rune fades, so does the faint hum of power within, leaving nothing but a painfully cold sphere of dark green metal.> \n\nAlthough it doesn't resemble other domanaar artifacts, there was no mistaking the cold, dark magic.\n\nPerhaps Decimus in the Howling Ridge can provide you with more information.>", objectives = "" }
WordHunterWoW_QuestEN[95071] = { title = "Enchanted Naga Scroll", description = "<The enchanted scroll shimmers with an arcane glint, the text vaguely resembling the elven language.\n\nYou presume it is written in the language of the naga, though the arcane-laced ink appears to move the letters around the scroll.\n\nPerhaps a mage in Silvermoon can help you translate it.>", objectives = "" }
WordHunterWoW_QuestEN[95114] = { title = "Prey: A Crimson Summons", description = "Ah, {name}. I have been looking for you. My... contacts have told me much regarding your continued attempts to defend our beloved city.\n\nBut there is another way.\n\nCome, join me in Murder Row and we can get to work.", objectives = "Meet with Astalor Bloodsworn in Murder Row.", completion = "Look at you.... following directions already. \n\nExcellent." }
WordHunterWoW_QuestEN[95175] = { title = "Anchoring the Defense", description = "We need your help to activate the Singularity Anchor. \n\nWith proper defenses we can counter enemy assaults long enough to activate the device. If the Anchor is destroyed our efforts will be halted.\n\nDo what you can to help us.", objectives = "Complete the Stormarion Assault event.", progress = "Have you helped us activate the Singularity Anchor?", completion = "We've neutralized numerous anomalies, but the additonal ones remain. We will prepare for additonal activations." }
WordHunterWoW_QuestEN[95215] = { title = "A New Direction", description = "<Your hand burns with felfire as a scroll materializes within your grasp. The seal bears the mark of the Illidari.>\n\n{name}, as leader of the Illidari in Lord Illidan's absence, you must choose your second-in-command.\n\nKayn or Altruis. You can only choose one.\n\nThe chosen shall become your personal champion, and their ideology will color our decisions for the Illidari going forward. No matter who is chosen, our mission remains unchanged.\n\n-Kor'vas Bloodthorn", objectives = "Choose between Kayn and Altruis.", completion = "I'm glad you selected your second-in-command, <name>.\n\nBut Stormwind mourns today, and we must act." }
WordHunterWoW_QuestEN[95220] = { title = "Midnight (30-79) E", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[95221] = { title = "Midnight (30-79) E", description = "", objectives = "Upon completion of this quest you will gain:" }
