WordHunterWoW_QuestEN[95242] = { title = "Midnight (81-89) E", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[95245] = { title = "Midnight: World Tour", description = "The immediate danger has passed, but there is still much to be done.\n\nGo out and work with our allies to secure what ground we have made against the darkness. Whether it is in Azeroth or beyond, there is still much to be done.", objectives = "Complete faction features in Midnight zones.", completion = "Back so soon? Impressive!" }
WordHunterWoW_QuestEN[95259] = { title = "Midnight (81-89) E", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[95268] = { title = "New Tools, New Heights", description = "There is another sort of Void power I know you will be interested in. An Ascendant Voidcore is difficult to come by, and even more difficult to work. With the Voidforge completed, I can now weave a magnificent Nilhammer capable of such things. Of course, I will need you to help with the materials. It will take time.\n\nTake this chunk of Hungering Oblivium. It can devour moments of extreme violence to be catalyzed to new heights of power, but I don't think you'll have any trouble managing that, will you?", objectives = "" }
WordHunterWoW_QuestEN[95271] = { title = "The Ascendant Nilhammer", description = "At last, we've collected enough power to fully weave the Nilhammer!", objectives = "" }
WordHunterWoW_QuestEN[95276] = { title = "The Last Push", description = "Our forces are starting to move out to take the fight to Xal'atath. \n\nI've received word there are many areas that you've visited that could still use some aid. \n\nWe must focus our attention on the counter offensive. Can you help those that are in need?", objectives = "Reach level 90.\n\nQuests in Silvermoon City, Eversong Woods, Zul'aman, Harandar, and Voidstorm will now scale to your level.\n\nWorld Quests are now unlocked.", progress = "There's plenty out there that can be done.", completion = "Fine work <name>. \n\nThere's plenty to do now that you've taken care of those issues." }
WordHunterWoW_QuestEN[95324] = { title = "The War Beyond the Roots", description = "Your actions in Harandar caused quite an uproar. The elders are up in arms. The rootwardens are worried. It's really quite exhausting.\n\nBut there is good news as well. Orweyna has heard rumblings from every corner of the roots. She tells me of haranir who wish to see the world as she does--who feel compelled to seek the goddess beyond the boughs of Harandar.\n\nI will handle things in Harandar. Go to your leaders. Tell them that the haranir are ready to join the fight.", objectives = "Bring word to Lor'themar in the Sanctum of Light.", completion = "The haranir seek to join the fight against the Void?\n\nFar be it from me to look a gift hawkstrider in the mouth. Halduron has vouched for both their strength and their tenacity. We shall need a great deal of both, in the battles to come." }
WordHunterWoW_QuestEN[95336] = { title = "Frenzied Fossicking", description = "Ya be down for helping me out with a little spot of bother?\n\nShajanji be over in the mountains collecting some local rocks. If you could go help her out, I'd be mighty grateful ta ya. Just bring them back ta me. I be keeping them safe for her.\n\nI--She needs a lot of them. She be an avid collector.", objectives = "" }
WordHunterWoW_QuestEN[95355] = { title = "The Messenger", description = "<This Lurker was carrying some items it looted from a fallen soldier.\n\n...These items feel familiar.\n\nThe letter is addressed to Namaji in Amani'Zar Village. Perhaps these items should be returned to her.>", objectives = "" }
WordHunterWoW_QuestEN[95373] = { title = "A Nebulous Endeavour", description = "I see you haven't come across a Nebulous Voidcore before. I can now weave them for you from the energies of the Catalyst as they accumulate, but you'll have to provide raw reagents.\n\nWith the Voidcore in hand, you'll have to seek out powerful enemies in order to transmute it into useful equipment. Its capable of capturing part of their essence to become something more powerful that you can put to use in the battles ahead.", objectives = "" }
WordHunterWoW_QuestEN[95406] = { title = "Lost Animals", description = "Oh thank goodness you are here!\n\nSome of my precious orange kitties were so eager to play in the neighborhood they've all run off to explore. Please help me find them!", objectives = "Find 10 Lost Cats" }
WordHunterWoW_QuestEN[95407] = { title = "Autumnal Addresses", description = "Race through the checkpoint rings marking the course.", objectives = "Ride through the rings." }
WordHunterWoW_QuestEN[95408] = { title = "Coastal Courier", description = "Race through the checkpoint rings marking the course.", objectives = "Ride through the rings." }
WordHunterWoW_QuestEN[95409] = { title = "High Road, Hollow Road", description = "Race through the checkpoint rings marking the course.", objectives = "Ride through the rings." }
WordHunterWoW_QuestEN[95410] = { title = "Cragthorn Certified", description = "Race through the checkpoint rings marking the course.", objectives = "Ride through the rings." }
WordHunterWoW_QuestEN[95411] = { title = "Desert Dispatch", description = "Race through the checkpoint rings marking the course.", objectives = "Ride through the rings." }
WordHunterWoW_QuestEN[95412] = { title = "Runetotem Run", description = "Race through the checkpoint rings marking the course.", objectives = "Ride through the rings." }
WordHunterWoW_QuestEN[95413] = { title = "Community Engagement", description = "Ah hello, {name}. I have a flier for you.\n\n<Vaeli hands you a glossy piece of paper.>\n\nDON'T MISS OUT!!!\n\nDon't miss this amazing deal available only to you! Present this coupon on your next purchase from your neighborhood endeavor trader, and get bonus items for free!\n\nCoupon valid for one week. Terms and conditions apply.", objectives = "" }
WordHunterWoW_QuestEN[95416] = { title = "Going Postal", description = "With so many new residents, mail in the neighborhoods is really starting to pile up. So many routes and just one of me! If only I could deputize an assistant mail carrier...\n\nSay, {name}, would you be willing to help out? I've got some juicy parcels from the dead letter office I could offer in thanks.", objectives = "" }
WordHunterWoW_QuestEN[95435] = { title = "Shade and Claw", description = "", objectives = "" }
WordHunterWoW_QuestEN[95438] = { title = "Lost Animals", description = "{name}, I am so glad to see you.\n\nA good friend of mine has sent a letter informing me she lost track of some of her tiny pets throughout the neighborhood! She's asking for assistance from anyone who can help!\n\nHelp find her lost animals right away!", objectives = "" }
WordHunterWoW_QuestEN[95439] = { title = "Lost Animals", description = "{name}, I am so glad to see you.\n\nA good friend of mine has sent a letter informing me of an issue she is having within the neighborhood, specifically having to do with her large collection of pets!\n\nShe seemed very stressed and worried, I would not delay on seeking her out to help!", objectives = "Find Kara in your neighborhood.<name>, I am so glad to see you.\n\nA good friend of mine has sent a letter informing me of an issue she is having within the neighborhood, specifically having to do with her large collection of pets!\n\nShe seemed very stressed and worried, I would not delay on seeking her out to help!" }
WordHunterWoW_QuestEN[95440] = { title = "Housewarming", description = "Kirin Tor scholars have argued for centuries over the semantics of a \"gathering\".\n\nHow many people are required? For how long must they remain? Who is bringing the beverages?\n\nDebates have raged into the night. Papers written. Research grants awarded.\n\nConsensus yet eludes the scholars, but they still meet often to deliberate. They take turns bringing beverages.", objectives = "" }
WordHunterWoW_QuestEN[95468] = { title = "Hope in the Darkest Corners", description = "I can't imagine what will happen to Quel'Thalas if the Sunwell falls to the forces of the Void.\n\nWe need you out on the battlefield, {name}. Bring hope and heroism to the people across these lands.", objectives = "Complete various activities in Midnight zones.", completion = "Well done, <name>!" }
WordHunterWoW_QuestEN[95482] = { title = "Lost Animals", description = "{name}, I am so glad to see you.\n\nA good friend of mine has sent a letter informing me of an issue she is having within the neighborhood, specifically having to do with her large collection of pets!\n\nShe seemed very stressed and worried, I would not delay on seeking her out to help!", objectives = "Find Kara in your neighborhood.<name>, I am so glad to see you.\n\nA good friend of mine has sent a letter informing me of an issue she is having within the neighborhood, specifically having to do with her large collection of pets!\n\nShe seemed very stressed and worried, I would not delay on seeking her out to help!" }
WordHunterWoW_QuestEN[95520] = { title = "Purging the Vaults", description = "De fiends of dis temple would see us all dead. We are all dat stands between them and de mainland, you understand? We hold dem here.\n\nNot one scale, not one bony finger, none of them will leave dis temple while we breathe.\n\nGet out there and cut them down.", objectives = "" }
WordHunterWoW_QuestEN[95521] = { title = "The Med'jai Medallion", description = "<The ancient gem pulses faintly. Scratches adorn its sides as if pried away with desperate eagerness. Perhaps the troll spirit, Me'si, will know where this came from.>", objectives = "" }
WordHunterWoW_QuestEN[95522] = { title = "Guardians of Death, Guardians in Stone", description = "In de legends passed down, dey speak of a group of heroic guardians whose sacrifice protect us to dis day. These honored few, known as de Med'jai, adorned their belts with gems like these--de better to draw their enemies in and defeat dem.\n\nWe were told dey went on a great expedition to fight de evil abroad, but it seems de greatest of de evils was within--below our feet.\n\nPlease, {name}, search for dis gem's true home. If our ancestor spirits watch over us, perhaps we will find their resting place.", objectives = "" }
WordHunterWoW_QuestEN[95523] = { title = "Worthy of the Past", description = "De Soulcoilers must pay, {name}.\n\nDe Soulcoilers believed their actions saved de Amani. Instead, our people and our future was plundered. We did not realize until it was too late.\n\nEnd them. Shatter their very souls so that even de great Mueh'zala cannot put dem back together.", objectives = "" }
WordHunterWoW_QuestEN[95524] = { title = "The Unremembered", description = "I am not de only Med'jai tasked with keeping sentinel over de priests. There were three of us, entombed in stone that matched how we looked in life.\n\nI must know if dey are still there. Can you help me find them? My body is bound in dis stone, but my spirit is not. Bring my gem to those places, if you can find dem.\n\nIf we cannot wake dem, we will at least honor dem.", objectives = "" }
WordHunterWoW_QuestEN[95525] = { title = "A Worthy Vigil", description = "De temple has changed since I began my watch, {name}. When you first woke me, all I saw was corruption and impure spirits. De consequence of our weakness.\n\nNow, I see dat we have not failed. De battlefield has changed, as dey always do.\n\nPlease take my gem and bring it back to de others like you. Perhaps my spirit can become a force for good on dis new battlefield, in a new way.", objectives = "" }
WordHunterWoW_QuestEN[95547] = { title = "Ritual Site Challenge Report: Tendrils", description = "<The information in the scrolls speaks of a mysterious vine attracted to the high levels of magic at Ritual Sites. This is the type of information Lady Darkglen needs to be told to better prepare for countering future Ritual Sites.>", objectives = "" }
WordHunterWoW_QuestEN[95548] = { title = "Tainted Sample", description = "<This sample is tainted and reeks of unknown scents.\n\nPerhaps Lady Darkglen would be interested in studying it further.>", objectives = "" }
WordHunterWoW_QuestEN[95549] = { title = "Raising Magical Alarms", description = "I have a request.\n\nThese Ritual Sites invoke some interesting magic. I would like you to obtain some sample readings.\n\nYou don't need to concern yourself with the details. Just visit the area I will mark on your map and press the button.\n\nYou may end up garnering some extra attention when you do so.", objectives = "" }
WordHunterWoW_QuestEN[95550] = { title = "Thin Their Ranks", description = "I don't like it.\n\nWe have far too many scouts returning wounded from these so-called ritual sites.\n\nThin out the ranks of these cultists.", objectives = "" }
WordHunterWoW_QuestEN[95551] = { title = "Misappropriated Treasures", description = "<It seems the cultists have added theft to their repertoire.\n\nYou should reclaim the stolen treasures from the Ritual Site and return them to Rae'ana.>", objectives = "" }
WordHunterWoW_QuestEN[95552] = { title = "Dark Obelisk Investigation", description = "{race}, we have reports that the leaders of the Ritual Sites are using dark obelisks to bolster their forces with malevolent boons.\n\nI need you to investigate the objects they are using to gain these boons.", objectives = "" }
WordHunterWoW_QuestEN[95553] = { title = "Manifested Density", description = "I'm hearing strange murmurings from my scouts.\n\nSome are claiming that strange manifestations are appearing and cursing intruders.\n\nCould I ask you to investigate and see if there is any truth to these rumors?", objectives = "" }
WordHunterWoW_QuestEN[95554] = { title = "Questionable Power", description = "<This creature was being enhanced by an unknown magic.\n\nPerhaps you should gather more of these fragments.>", objectives = "" }
WordHunterWoW_QuestEN[95564] = { title = "The Serpent's Tail", description = "De Shadowpine shamans are at our hash'ey's command. We speak de language of fire from de wing of Jan'alai, but we also need help.\n\nWith de help of the other tribes, we have secured this camp. But we won't hold it for long without your help.\n\nI have a few things I would ask you to do, hash'ura, if you are willin'.", objectives = "" }
WordHunterWoW_QuestEN[95673] = { title = "Suspicious Scare-gull", description = "Hey there, could ya help a poor troll down on their luck?\n\nI'm looking for some feathers from ya neighborhood.\n\nIf ya give the birds around here a good scare, they'll take off and drop some, just bring them back here.", objectives = "" }
WordHunterWoW_QuestEN[95768] = { title = "My Stuff's Better Than Your Stuff", description = "Hey there, {name}.\n\nI set up shop to trade some of our neighborhood goods with our new friends here, and I've been selling like hotcakes!\n\nI could use a break though, would you mind watching the shop for me? If any customers come by, just offer them what you think is best.", objectives = "" }
WordHunterWoW_QuestEN[95779] = { title = "Moments in a Mug", description = "A man who knows his way around a drink deserves the finest brew. I have just the thing in mind for my friend, Flynn.\n\nThe ingredients I need are within my family's brewery in the Valley of Four Winds. I would fetch them myself, but a brewmaster must also know when to sit, breathe, and appreciate what is within the mug.\n\nWould you go to Stormstout Brewery and bring those ingredients to me, friend?", objectives = "" }
WordHunterWoW_QuestEN[95780] = { title = "Hope for the Orphans", description = "Garona and I both don't talk about our childhoods much. There's not a lot worth saying.\n\nThe children in that orphanage in Shattrath--they're living what we lived. I'm not asking you to fix that. I'm asking you to show up and remind them the world holds something worth fighting for.\n\nFor me, revenge was worth fighting for. But maybe they can have a brighter future.\n\nGo play games with them. Try to show them what a person worth looking up to actually is.", objectives = "" }
WordHunterWoW_QuestEN[95781] = { title = "No Wax Like Home", description = "Skitter like Myritt. Myritt is sad, wants gift for his friend. \n\nCandle is best gift. Help find the best candle for Myritt.", objectives = "" }
WordHunterWoW_QuestEN[95804] = { title = "The Children of Ula'tek", description = "Are these tortollans lost? How long have dey been here?\n\nWe have a settlement of dem near de Shrine of Filo, but dis is a place dey should not be.\n\nA day not long ago, I would have chased dem off. But we've been havin' good luck with outsiders.\n\n<A hint of a smile crosses Zul'jarra's face. It's the first you've seen since before Malacrass's return.>\n\nWe should talk to dem. Maybe dey know how dis started.", objectives = "" }
WordHunterWoW_QuestEN[95842] = { title = "Midnight: Void Assaults", description = "Both Void forces and old enemies press us in this turbulent time. We must stay vigilant and let no faction gain a foothold.\n\nYou must put a stop to these Void assaults! Stay alert, our scouts report some factions may be using the smaller strikes to prepare for a major incursion. \n\nIf so, I know you will help with the defense.", objectives = "" }
WordHunterWoW_QuestEN[95843] = { title = "Midnight: Ritual Sites", description = "There have been many enemies that seek to use dark rituals to send horrors our way. The rangers have always risen to challenge and dealt with them. \n\nWith the pressure on our forces, I must ask you to take up this mission. There are dangerous Ritual Sites that must be disrupted. \n\nOur enemies will most likely try again, so you must be dogged and continue to thwart them each time they make the attempt.", objectives = "" }
WordHunterWoW_QuestEN[95933] = { title = "Traces in the Dark", description = "Champion, Riftblade Maella would like to speak with you again.\n\nThe dark particles you have brought us, the information you've been gathering on our enemies and the countless victories you have bought for Quel'Thalas have not gone unnoticed.\n\nIt seems Maella has a plan. Seek her out when you can.", objectives = "" }
WordHunterWoW_QuestEN[95954] = { title = "An Ancient Foe", description = "You have done well, {name}, but a shadow remains cast over the temple, in the form of the High Priest Jin'tal.\n\nA particularly fervent and ambitious priest in life, I am unsurprised that he has survived into undeath. I sense that he practices his abhorrent faith in the nearby Mortuary.\n\nPlease, {name}. End him. I will help you if I can.", objectives = "" }
WordHunterWoW_QuestEN[95973] = { title = "Echoes of the Darkwell", description = "Magister Umbric has been keeping an eye on the Twilight's Blade, receiving reports from the field. \n\nHe thinks something is afoot. \n\nThat is not all. He said that he has also been keeping an eye on Arator since the Darkwell, and has developed... concerns about him.\n\nGo, speak with him.", objectives = "" }
WordHunterWoW_QuestEN[96004] = { title = "Prey: A Slithering Threat", description = "Do you feel it, {name}?\n\nWe are being watched. \n\nI do not know by whom, or to what end, but it appears that our... efforts have drawn fresh attention. Go out and survey the field.\n\nLet us test the mettle of these newcomers.", objectives = "" }
WordHunterWoW_QuestEN[96048] = { title = "The Time to Strike", description = "<A void-touched missive materializes before you.>\n\n{name},\n\nYour efforts against the recent void and ethereal incursions have paid off. It's time we take the fight to them.\n\nMeet me at the Ranger-Captain's strike station in Silvermoon.\n\nDo not delay.\n\nRiftblade Maella", objectives = "" }
WordHunterWoW_QuestEN[96049] = { title = "Stalkers of the Stars", description = "With the help of Belath Dawnblade and Decimus, we've learned our enemies orchestrate their attacks from former Legion worlds.\n\nI've requested the demon hunter's aid in navigating these worlds and fortifying our defenses.\n\nSeek them out and lend them any assistance they need. Inform Belath we mobilize soon.", objectives = "" }
WordHunterWoW_QuestEN[96051] = { title = "Through the Cold Rift", description = "The Legion keystone and the dark particles you found gave us a needle in the endless, vast haystack of the Twisting Nether.\n\nWith the Cynosure of Twilight, the artifact used to open the way to the Voidstorm, we can thread this needle and open a rift to our enemy's doorstep.\n\nWith the components in place, my riftwardens stand at the ready.\n\nTake up the Cynosure and point and be ready, {name}.", objectives = "" }
WordHunterWoW_QuestEN[96052] = { title = "Through the Mana Rift", description = "The energy from the Hal'hadar battery core and dark particles allowed us to piece together a faint trail of nether energy.\n\nWith the Cynosure of Twilight, we can illuminate and ignite this trail, taking us directly to our enemy's doorstep.\n\nThe anchors are in place and my riftwalkers await your move.\n\nTake up the Cynosure and point. Let us see what awaits us on the other side.", objectives = "" }
WordHunterWoW_QuestEN[96053] = { title = "Surveying the Frozen Wastes", description = "We still hold the element of surprise, which gives us a moment to fortify our position.\n\nWhile Y'mera opens a more stable travel network for the rest of our forces, our scouts have gone ahead to survey the terrain.\n\nMeet with them in the field and activate our surveillance beacons.\n\nI will remain here to cover the arrival of our reinforcements.", objectives = "" }
WordHunterWoW_QuestEN[96054] = { title = "Surveying the Mana-Bog", description = "Our sudden arrival allows us a brief moment to fortify our hold here.\n\nWhile Y'mera works on bringing the rest of our forces through a more stable network, our scouts have gone ahead to survey the terrain and the enemy.\n\nMeet with them in the field and activate our surveillance beacons.\n\nI will remain here with Y'mera and Decimus should any of those skiffs overhead decide to pay us a visit.", objectives = "" }
WordHunterWoW_QuestEN[96070] = { title = "12.1-  Housing - Founders - Local Local Story 01 - Q01 - Escort - (POC)", description = "", objectives = "" }
WordHunterWoW_QuestEN[96071] = { title = "12.1-  Housing - Founders - Local Local Story 01 - Q02 - Escort - (POC)", description = "Ah, {name}, yer here.\n\nMy husbands been lying to me about where he's been going after work. I'm worried he's in some kind o' trouble.\n\nI hate to ask, but can ye follow him? I can't follow him meself, he'd notice me.", objectives = "" }
WordHunterWoW_QuestEN[96072] = { title = "12.1-  Housing - Founders - Local Local Story 01 - Q03 - Escort - (POC)", description = "<You've followed Thromnil to a secret rendevous with another woman.\n\nTime to report back to Greta, unless you want to overhear what they are saying.>", objectives = "" }
WordHunterWoW_QuestEN[96073] = { title = "12.1-  Housing - Founders - Local Local Story 01 - Q04 - Escort - (POC)", description = "", objectives = "" }
WordHunterWoW_QuestEN[96074] = { title = "12.1-  Housing - Founders - Local Local Story 01 - Q05 - Escort - (POC)", description = "", objectives = "" }
WordHunterWoW_QuestEN[96080] = { title = "Void Strike", description = "We have reports of new void strikes occurring around Eversong Forest and Zul'Aman. \n\nWe need you to head out immediately to investigate one of these strikes. I will mark your map with the latest location from our scouts.", objectives = "" }
WordHunterWoW_QuestEN[96089] = { title = "Somethin's Not Right", description = "Whatever's wrong with her, whatever those creatures did, I need her healed!\n\nWill you help?", objectives = "" }
WordHunterWoW_QuestEN[96090] = { title = "Venemetic", description = "I have the other ingredients for the emetic here. The last ingredient I need is some venom to trigger a response.\n\nI overheard the trolls talk about a place just to the north called the Serpent's Tail. They say it's chock-full of venomous baddies, but we only need the poison from the Children of Ula'tek.\n\nThey say there are even rivers full of the caustic stuff, but don't go swimming in them. They're too concentrated and will eat right through the collection bottle before you can scream, \"I'm melting!\"", objectives = "" }
WordHunterWoW_QuestEN[96091] = { title = "Get the Balance Right", description = "I've set up three bottles with different ingredients. All you have to do is add just the right amount... just a dash of venom to each. Balance them out.\n\nYou can use Ofi's cauldron right over there. I'm sure she won't mind. Whatever's in there has likely been bubbling since before she was born.\n\nNo, I'm not going to do it for you. I've lived long enough to know not to touch that stuff!\n\nOnce you have the results, give the emetic to your medic friend and we'll see what happens.", objectives = "" }
WordHunterWoW_QuestEN[96092] = { title = "That Fool, Ruma", description = "Unfortunately, this has moved beyond my area of expertise.\n\nFortunately, I know someone who can help. Probably.\n\nUnfortunately, he left for some \"great adventure\" on Gnarldor Isle to the south. More likely, he's on a great bender.\n\nHere, take this elixir and give it to our former ship's doctor, Ruma. I always like to keep one handy. It'll sober him right up.\n\nThen it's on you to convince him to devise a cure. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[96093] = { title = "It's a Satchel, Not a Bag", description = "Well, you see, I was on quite the adventure with my friend, Tormunda, and a few others. Seeing the world, sipping exotic drinks, rest and relaxation. But then, disaster struck our camp.\n\nGnarldin!\n\nWe were separated and I did what you're supposed to do when you're lost: stay where you are. So, I've been resting here.\n\nBut I'm afraid in all the commotion, I left my satchel behind. It has all of my best things in it.\n\nSo you see, if you want my help, you'll have to go and get it for me.", objectives = "" }
WordHunterWoW_QuestEN[96094] = { title = "To the Forum", description = "If we're to help this La'una of yours, we need to go to the source. You said they were scouting the western ledge of the Fangs when all of this happened?\n\nEveryone knows you don't go there. We should NOT go out there. But, that is precisely where we must go because that's where we'll find the cure.\n\nOr, meet our demise. Whichever comes first.\n\n<Ruma begins rummaging through his pack for a refreshment.>", objectives = "" }
WordHunterWoW_QuestEN[96095] = { title = "Sampling the Local Wildlife", description = "If I'm going to devise a cure, I need samples and plenty of them.\n\nLucky for us we have the two things we need: You and all of the infected wildlife roaming throughout this place.", objectives = "" }
WordHunterWoW_QuestEN[96096] = { title = "Scout Team Seven", description = "When we first came out here our leader, Dusk Prowler Hano'mon, took de team too far in. He always was a... not very well-liked.\n\nI was scoutin' de rear and by de time I came across La'una, she was already affected by whatever dis is.\n\nIt's possible de rest of my scout team is still out there. If dey are, I need to know their fate, one way or de other.\n\nTheir names are A'pone, Kamaina, Ko'ruku, Uha'ne, and Hano'mon.", objectives = "" }
WordHunterWoW_QuestEN[96097] = { title = "What the Scouts Saw", description = "If my guess is correct, I think I know what we're missing.\n\nWould you be so kind as to ask these scouts about what they've seen while they were out there? I suspect they already know what, or who, is behind all of this.", objectives = "" }
WordHunterWoW_QuestEN[96098] = { title = "The Final Reagents", description = "I saw de Children of Ula'tek as well, {name}. Dey both are conjurin' in their separate towers out there.\n\nNow it's time to put an end to de threat. We can't have dem comin' out of de Vaults of Atal'Utek and spreadin' dis infection all over Zul'Aman... or farther.\n\nAnd don't forget about de reagents de doctor needs!", objectives = "" }
WordHunterWoW_QuestEN[96099] = { title = "La'una's Fate", description = "The prescription is ready. Now all we have to do, all YOU have to do, is give it to the patient.\n\nDon't worry, it'll work. I'm sure of it. Well, I'm mostly sure. Let's say, sixty-seven percent certain. Those are pretty good odds considering the alternative.", objectives = "" }
WordHunterWoW_QuestEN[96110] = { title = "Venom Fishing: Proof is in the Ooze", description = "If ye mean to be part of my crew, ye best be ready to handle the venom curse.\n\nKnow how to fish? Every creature with gills on this isle is ready to sink its teeth into you.\n\nProve ye can fish up even the smallest of the venom-cursed fish and I'll show ye how to take on deadlier and nastier fishin'.", objectives = "" }
WordHunterWoW_QuestEN[96111] = { title = "Venom Fishing: Shell of Yourself", description = "You've learned some o' my secrets to fishin' in these cursed waters, but everything ye learn from here on serves a greater purpose than survival.\n\nRevenge.\n\nThe Great White Serpent that sank my ship is still alive. If we intend to kill it, we need the power o' my crew, now lost to the venom-curse.\n\nMaster Grenadier Birdie has one good shot: her first shot. Build yerself a decoy and you'll have a chance to kill her.\n\nTake her explosives. We'll need 'em to blow that snake to smithereens.", objectives = "" }
WordHunterWoW_QuestEN[96112] = { title = "Venom Fishing: Maddening Concoction", description = "We need somethin' to protect that shell-less back o' yers when we face the Great White Serpent.\n\nLeathertongue made dishes that made us immune to nigh anything, this being on account o' them nearly killin' us every mealtime!\n\nHis pots and pans could withstand any nightmare. We need that strength.\n\nThe key to defeating the cook is to challenge his skill. Make a dish of the foulest ingredients and he'll be there to face ye.", objectives = "" }
WordHunterWoW_QuestEN[96113] = { title = "Venom Fishing: Maximum Potency", description = "We're almost ready to face the Great White Serpent. We only need one more thing.\n\nI want ye to take my quartermaster's boat.\n\nInktail has plans on plans. Before the venom, she was cool and reserved even in the wildest storms. With the venom curse, she's become even more elusive.\n\nI've only seen her lose her deadly composure once. She has a mighty love of rare fish.\n\nIt's a gamble, but go into the temple and find a fish overwhelmed with venom. It may be enough to draw her out of hidin'.", objectives = "" }
WordHunterWoW_QuestEN[96114] = { title = "A Small Pouch of Crystals", description = "", objectives = "Thanks for helping get Undermine back on track. Here's somethin' for your trouble." }
WordHunterWoW_QuestEN[96115] = { title = "A Small Pouch of Crystals", description = "", objectives = "Thanks for helping get Undermine back on track. Here's somethin' for your trouble." }
WordHunterWoW_QuestEN[96116] = { title = "A Cache of Crystals", description = "", objectives = "The work of the Severed Threads proceeds apace. As such, our patrons have decided to reward your continued dedication.\n\nNow take this and begone. You're drawing suspicious eyes." }
WordHunterWoW_QuestEN[96117] = { title = "A Cache of Crystals", description = "", objectives = "The work of the Severed Threads proceeds apace. As such, our patrons have decided to reward your continued dedication.\n\nNow take this and begone. You're drawing suspicious eyes." }
WordHunterWoW_QuestEN[96118] = { title = "A Cache of Crystals", description = "", objectives = "The work of the Severed Threads proceeds apace. As such, our patrons have decided to reward your continued dedication.\n\nNow take this and begone. You're drawing suspicious eyes." }
WordHunterWoW_QuestEN[96120] = { title = "Crystals", description = "", objectives = "" }
WordHunterWoW_QuestEN[96121] = { title = "A Small Bundle of Goods", description = "", objectives = "Expressing gratitude. Please accept this as a reward for all your hard work." }
WordHunterWoW_QuestEN[96122] = { title = "A Small Bundle of Goods", description = "", objectives = "Task completed. The Council rewards you for assisting with earthen reunification." }
WordHunterWoW_QuestEN[96123] = { title = "A Small Bundle of Goods", description = "", objectives = "Task completed. The Council rewards you for assisting with earthen reunification." }
WordHunterWoW_QuestEN[96124] = { title = "A Small Bundle of Goods", description = "", objectives = "Task completed. The Council rewards you for assisting with earthen reunification." }
WordHunterWoW_QuestEN[96223] = { title = "The Magisters' Call", description = "<A floating missive hangs before you, written in a flowing magical script. At first, it appears to be nonsense.\n\nAs you approach the parchment, the words shift and change, and a message forms.>\n\nThe Magisters request your presence at Thalassian University. Please proceed to the upper levels overlooking the harbor.\n\nThis concerns a private matter of minor urgency.", objectives = "" }
WordHunterWoW_QuestEN[96224] = { title = "The Magisters' Conundrum", description = "Magisters' Terrace is home to many mysterious artifacts.\n\nAmong them is a relic once central to our pursuit of magical knowledge. A few years ago, the relic fell into a state of dormancy.\n\nAfter the Dawnwell reignited, this artifact began to stir. Upon returning it to the Lycaneum for study, the relic unleashed chaos upon the library.\n\nI believe your unique expertise may be helpful in quelling this chaos.", objectives = "" }
WordHunterWoW_QuestEN[96225] = { title = "The Magisters' Conundrum", description = "For the last few decades, a dormant artifact laid beneath the halls of Magisters' Terrace.\n\nOnce serving as a beacon of knowledge to the Magisters, the artifact abruptly fell silent some decades ago.\n\nAfter the Dawnwell's rebirth, the artifact reawakened. When we returned it to the Lycaneum for study, it unleashed chaos upon the library.\n\nYour assistance, and discretion, would be most appreciated.", objectives = "" }
WordHunterWoW_QuestEN[96226] = { title = "Omnium Anomalies", description = "Shortly after the Omnium awoke, it began manifesting arcane anomalies around the Lycaneum.\n\nWe believe these anomalies to be malfunctioning security protocols--the hostile projections they conjure can be quite lethal.\n\nIf we do not dispatch them quickly, they will continue to manifest.\n\nAs you deal with them, keep an eye out for anything peculiar that can help us understand the Omnium's current state.", objectives = "" }
WordHunterWoW_QuestEN[96227] = { title = "Lycaneum Chaos", description = "When the Omnium began to stir in its vault, we thought to move it here for observation. Evidently, this was a bad idea.\n\nThe arcane magics seeping out are causing chaos.\n\nFolios casting all sorts of incomplete spells, arcane sparks running amok--even the candle flames have sprung to life!\n\nBut we cannot simply destroy them, as the magics here are too volatile. I have procured a ward-lance from the arsenal of the spellbreakers. It will dispel the volatile magic.\n\nHere, take it. And do be careful.", objectives = "" }
WordHunterWoW_QuestEN[96228] = { title = "The Shadowed Spire", description = "Time and time again, Dar'Khan continues to haunt us in some form.\n\nTo think the Omnium also fell prey to his madness...\n\nIf he really severed the Void Magicule from the Omnium, then I have no doubt he would have hidden it well.\n\nI have a suspicion I know where to start looking.\n\nMeet me at Dawnstar Spire in Eversong Woods.", objectives = "" }
WordHunterWoW_QuestEN[96229] = { title = "The Void Reveals", description = "After reclaiming Silvermoon, the Magisters torched Dar'Khan's personal study and dwellings within the city walls.\n\nI had thought I had found everything I needed the first time I searched this place, but now...\n\nIt seems that Dar'Khan left some secrets.\n\nThis portal will take us to them. I do not know what we will find on the other side. Be on your guard.", objectives = "" }
WordHunterWoW_QuestEN[96230] = { title = "Unraveling the Wards", description = "The Magicules, the orbs you see on the relic, were never meant to be severed from the Omnium. By tearing one out, Dar'Khan likely sent the artifact into a frenzied state before it shut down. \n\nEven if the Void Magicule is restored, the Omnium will need recalibrating. We will need Belo'vir's key-cipher, now my key-cipher, to do this.\n\nI will meet you at my study and we can recover it.", objectives = "" }
WordHunterWoW_QuestEN[96231] = { title = "The Grand Magister's Key-Cipher", description = "After Belo'vir's death, I contemplated opening this vault. I talked myself out of it.\n\nA key for a shattered lock serves no purpose.\n\nAnd yet, even as Kael'thas tried to open it with his key, I couldn't help but wonder...\n\nIt doesn't matter, {name}. I am nearly done with the master ward on the upper floor. Meet me there.\n\nNo doubt, Belo'vir took extra steps to safeguard his vault.", objectives = "" }
WordHunterWoW_QuestEN[96232] = { title = "Return to the Omnium", description = "Well, now that we've recovered the piece Dar'Khan stole, we are one step closer to restoring the Omnium.\n\nHopefully your endeavor with Rommath was a little less troublesome?\n\nWhen you're ready, return to the Magisters' Terrace. I will clean up anything left behind here and join you shortly.", objectives = "" }
WordHunterWoW_QuestEN[96233] = { title = "The Omnium Reawakens", description = "For years, as Silvermoon and its people changed, this relic sat in a vault beneath the Terrace, unresponsive and dormant.\n\nWe may never truly understand why the relic fell silent when it did or why it refused the prince's call, but perhaps in time, we might.\n\nLet us hope the missing Magicule and the key-cipher will be enough to restore it.\n\nAre you ready, {name}?", objectives = "" }
WordHunterWoW_QuestEN[96238] = { title = "Return to the Omnium", description = "With Belo'vir's key-cipher recovered and Umbric in possession of the Void Magicule, we should return to the Lycaneum.\n\nHopefully we have all that we need to recalibrate the Sunstrider Omnium.\n\nI will meet you back in the Magisters' Terrace when I am done here.", objectives = "" }
WordHunterWoW_QuestEN[96242] = { title = "An Easy Path to Trickery", description = "You can always speak to me to enter a game of Decor Duel, but did you know there's an easier way?\n\nIf there's a group you want to find, we have \"magic\" to help!", objectives = "" }
WordHunterWoW_QuestEN[96245] = { title = "You've Seen it All Before", description = "<A fine parchment materializes in a shower of bronze dust. It is an invitation from Soridormi to visit her at the Wayfarer's Rest in Silvermoon City.>", objectives = "" }
WordHunterWoW_QuestEN[96267] = { title = "Ancestral Gems", description = "When de Children of Ula'tek seized dis temple, many of my ancestors died defendin' it. Sacred relics were seized by de snakes! Even now, dey twist those items into foul magic!\n\nAmong these items were some gems of great power.\n\nSearch de vaults, ritual chambers, and every deep corner of de temple and recover any gems you find.", objectives = "" }
WordHunterWoW_QuestEN[96271] = { title = "Cursed Existence", description = "When de poison spread through dis temple, many of our ancestors fell trying to defend dis place.\n\nNow Nek'zali has ensnared their spirits to serve her in restoring Ula'tek. Put de cursed spirits to rest so dey may pass beyond dis place.", objectives = "" }
WordHunterWoW_QuestEN[96273] = { title = "A Balance Paid in Blood", description = "De Children of Ula'tek have upset de balance of de spirit world. Many spirits are angry and demand justice before dey can move on.\n\nDe snakes' blood will restore de balance!\n\nSlay de Children of Ula'tek and all dat aid dem here in de temple.", objectives = "" }
WordHunterWoW_QuestEN[96275] = { title = "Wading In", description = "Too many spirits here have succumbed to de dark charms of Nek'zali, but there's still hope to save others.\n\nPlace spirit guardians throughout de lakes of venom so dey may offer sanctuary to spirits nearby. \n\nDe venom lakes are deadly, so go prepared!", objectives = "" }
WordHunterWoW_QuestEN[96276] = { title = "Dark Charms", description = "De Children of Ula'tek play cruel games on de spirits here. Dey use dark charms to keep dem trapped and tormented.\n\nDe charms are hidden throughout de temple. Find and burn them, so de spirits here can find peace.", objectives = "" }
WordHunterWoW_QuestEN[96305] = { title = "The Innocent Essence", description = "When de defenders fell, cursed to their fate, so too did de great eagle Tok'jara who flew with dem. Such innocence did not deserve dis curse.\n\nEven now, de spirit struggles to break free, forming a twisting geyser as it rises from the venomous pools.\n\nHelp it be free, claim its essence from the poison, and end its suffering.", objectives = "" }
WordHunterWoW_QuestEN[96310] = { title = "Disrupting the Order", description = "Great work defeating their forces. Every step we take will keep Azeroth safe.\n\nBut usurpers are still trying to seize control. Baraat has already spotted high ranking domanaar looking at the remaining resources.\n\nWe need to defeat the Umbrawardens and any of their forces along the way.", objectives = "" }
WordHunterWoW_QuestEN[96338] = { title = "Port of Entry", description = "{name}, take a look at that platform above. What do you think they use that for?\n\nThe void creatures steal wildlife from Azeroth and move them here to be broken, then added to their forces. That platform must be where creatures are first brought in.\n\nLet's force our way through any defenses up there and destroy that portal!", objectives = "" }
WordHunterWoW_QuestEN[96349] = { title = "Ancestral Gems", description = "When de Children of Ula'tek seized dis temple, many of my ancestors died defendin' it. Sacred relics were seized by de snakes! Even now, dey twist those items into foul magic!\n\nAmong these items were some gems of great power.\n\nSearch de vaults, ritual chambers, and every deep corner of de temple and recover any gems you find.", objectives = "" }
WordHunterWoW_QuestEN[96352] = { title = "Dark Charms", description = "De Children of Ula'tek play cruel games on de spirits here. Dey use dark charms to keep dem trapped and tormented.\n\nDe charms be hidden throughout de temple. Find and burn them, so de spirits here can find peace.", objectives = "" }
WordHunterWoW_QuestEN[96354] = { title = "A Balance Paid in Blood", description = "De Children of Ula'tek have upset de balance of de spirit world. Many spirits be angry and demand justice before dey can move on.\n\nDe snakes' blood will restore de balance!\n\nSlay de Children of Ula'tek and all dat aid dem here in de temple.", objectives = "" }
WordHunterWoW_QuestEN[96360] = { title = "Wading In", description = "Too many spirits here have succumbed to de dark charms of Nek'zali, but there's still hope to save others.\n\nPlace spirit guardians throughout de lakes of venom so dey may offer sanctuary to spirits nearby. \n\nDe venom lakes are deadly, so go prepared!", objectives = "" }
WordHunterWoW_QuestEN[96361] = { title = "Cursed Existence", description = "When de poison spread through dis temple, many of our ancestors fell trying to defend dis place.\n\nNow Nek'zali has ensnared their spirits to serve her in restoring Ula'tek. Put de cursed spirits to rest so dey may pass beyond dis place.", objectives = "" }
WordHunterWoW_QuestEN[96382] = { title = "A New Approach", description = "For this threat, you'll need to think more like the domanaar. Luckily, I can do just that.\n\nWhat we need is a puppet. Someone we can give the reins who has no aspirations for your precious Azeroth. Those new domanaar you saw will need evaluation.\n\nTake this veil. You'll be able to blend in and observe them. I understand your urge to strike, but be patient. The time will come to eliminate all in your path, as your kind seems to enjoy.\n\nSee if you can find a proper candidate.", objectives = "" }
WordHunterWoW_QuestEN[96388] = { title = "Joining the Abyss Anglers", description = "Ya ever heard of de Abyss Anglers?\n\nForest tribes have been hunting de land as well as de waters for generations.\n\nDon't be shy, hash'ura. Grab a suit and go for a dive!", objectives = "" }
WordHunterWoW_QuestEN[96389] = { title = "A Place to Negotiate", description = "While you were attuning the gem to the Void, I managed to acquire one of Impotus's projection devices. \n\nWe're going to use it to lure him to us, then prevent him from escaping with the gem. \n\nNot here, though. Let us find somewhere more discrete.", objectives = "" }
WordHunterWoW_QuestEN[96410] = { title = "Seeking Knowledge Week 1 of 5: The Omnium Folio", description = "Those who sought to learn from the Omnium had to contribute to it.\n\nWhile most Magisters studied within the Terrace, a select few were appointed as \"Seekers of Wisdom.\"\n\nSeekers would search for new and foreign magic to contribute to the Omnium's vast index for study.\n\nGiven your... adventurous experience, I think you'd make an excellent seeker.\n\nIf you're interested, the Grand Magister will explain more.", objectives = "" }
WordHunterWoW_QuestEN[96439] = { title = "Gone Dark", description = "These infernal nests are where de Children of Ula'tek spawn from. We must work to clear dem out if we are to have any hope of stemming de endless tide of snakes.\n\nI have been sending groups of my most fearless scouts to gather information on dem. All have returned... except for one.\n\nGo, track down Ulantu and Naj'kula in de Blistering Terrace. Find out why dey gone dark.", objectives = "" }
WordHunterWoW_QuestEN[96440] = { title = "Victory Within Hindsight", description = "Great work, {name}! I can already picture the walls of the Acropolis crumbling.\n\nIn fact, why don't we head there now and press our advantage? The Light can shine through the tiniest of cracks.\n\nI'll scout ahead and meet you on the way there.", objectives = "" }
WordHunterWoW_QuestEN[96441] = { title = "Seeking Knowledge Week 2 of 5: Ritualized Arcana", description = "The nature of the Dawnwell has sparked a question among the minds of Magisters' Terrace:\n\nIf magic can corrupt and suffuse other magics, how will the Dawnwell affect the ley lines branching out from it?\n\nWith inquiry, comes experiment.\n\nThe Ritual Sites in Quel'Thalas use the ley lines to fuel their magic.\n\nDisrupt these sites and retrieve samples of the arcana you find.", objectives = "" }
WordHunterWoW_QuestEN[96442] = { title = "Seeking Knowledge Week 3 of 5: Ley Line Assaults", description = "Unfortunately, most of the measurable samples were expunged by the Ritual Site's excessive energy.\n\nIf we are to accurately measure the various magics seeping into the ley lines, we'll need samples from a broader, less concentrated source.\n\nI am told the Farstriders continue to route the void strikes across Quel'Thalas.\n\nBring me coalesced ley energy from any of the assaulting forces.", objectives = "" }
WordHunterWoW_QuestEN[96443] = { title = "Seeking Knowledge Week 4 of 5: Magical Primessence", description = "Thanks to your efforts, we've isolated the effects of trace amounts of foreign magic coalescing with the ley lines.\n\nOur next phase is to compare these results against a pure sample of magic coalescing with the same energy.\n\nYour task is to track down a primessence of magic--be it arcane, Void, Light, or other--and acquire it from its deadly source.\n\nGood luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[96444] = { title = "Seeking Knowledge Week 5 of 5: Off-World Magic", description = "Although it made an excellent catalyst, the primessence you retrieved revealed a factor we did not account for.\n\nThe alien nature of the Void and ethereal magic used in their assaults proved incompatible with the experiment.\n\nWe need a sample of their magic if we are to make any progress--not from the assaults here in Quel'Thalas, but from the source of their attacks.\n\nI am told these enemies strike from off-world staging grounds. Good luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[96445] = { title = "[DNT]", description = "", objectives = "" }
WordHunterWoW_QuestEN[96446] = { title = "Spark of Tides", description = "A vision of tides permeates your mind.\n\nEldara Dawnrunner might have more information regarding these Sparks of Tides.", objectives = "" }
WordHunterWoW_QuestEN[96450] = { title = "Sideways", description = "Naj'kula and I were here to observe how the Children of Ula'tek reproduce.\n\nWe discovered dis lich, Lokago. Malacrass had him experimentin' on kidnapped Amani. I stole his records to try and figure out why, but de lich discovered us. I was injured. I dropped everythin'.\n\nNaj'kula was right behind me... We gotta recover de notes--and find Naj'kula!", objectives = "" }
WordHunterWoW_QuestEN[96451] = { title = "A Child of Ula'tek", description = "I don't like dis. We should have found her by now.\n\n<Ulantu's face is sweaty and pale. She rubs her wound absentmindedly.>\n\nDe lich must have dragged her back to where he was doin' his experiments. And if his notes are to be believed...\n\nWe need to find Naj'kula quickly--or she may not be who she was.", objectives = "" }
WordHunterWoW_QuestEN[96457] = { title = "Nothing Must Remain", description = "You saw what he did to Naj'kula. And who knows how many others.\n\n<Ulantu is sweating and pale, gripping her stomach.>\n\nToo many lives were sacrificed in de name of these awful... whatever Kuku became.\n\nIf only we could have killed de damned lich! But we can destroy his lab.", objectives = "" }
WordHunterWoW_QuestEN[96458] = { title = "Last Promise", description = "Lokago cut me with de same venom that twisted Naj'kula. I feel it burnin' me just the same.\n\nI intend to die an Amani. But my work is unfinished.\n\nPlease get these notes to Kul'amara.\n\nTell her she can find me at Naj'kula's side.", objectives = "" }
WordHunterWoW_QuestEN[96466] = { title = "Prey: Anguish Island", description = "Something is driving these creatures into our realm.\n\nI have sent one of my most capable servants to this \"Isle of Fangs\". Go and see what you can make of this den of snakes. In any other endeavor I would accompany you, of course--but I shall remain here. \n\nThis island sounds like a most dreadful place.\n\nDo have fun, though.", objectives = "" }
WordHunterWoW_QuestEN[96467] = { title = "Thirst for Knowledge", description = "Two brothers came with us to dis cursed place... Zei'ka and Jun'ka.\n\nZei'ka, he got de fire in him. Soon as we landed, he ran off, chasing whispers like dey were calling his name. But, Jun'ka, he ain't a fool. He went after his brother, tryin' to keep him from getting himself killed.\n\nI don't like dis. Dis island, it'll swallow us whole if we ain't careful. Go check on dem, eh?", objectives = "" }
WordHunterWoW_QuestEN[96469] = { title = "The Crypt of the Disgraced", description = "Jun'ka's my brother, but he frets too much to let me chase after my life's dream.\n\nEver since I was a child, I wanted to learn more of our history. While much of it is told by de talespinners back home, they always skipped one thing: Atal'Utek. De more I dug, de more mysterious it became, and de more I became engrossed.\n\nNow, de scouts tell me that this crypt is filled with tablets inside. Tablets that could have de history of our people. I need to see those tablets, even if it kills me. You in?", objectives = "" }
WordHunterWoW_QuestEN[96471] = { title = "Crumble and Tumble", description = "Blast it all! I dragged y'all into dis muck just 'cause my brother's worried about my hide!\n\nYou're gettin' outta here quick! I lead, you follow, and don't lag behind, or you're squashed!", objectives = "" }
WordHunterWoW_QuestEN[96472] = { title = "The Nexus-Captain", description = "The Hal'hadar may not know we are here yet, but they still hold the advantage.\n\nNexus-Captain Leth'ir and his associate, Mertei, are just over this ridge and surrounded by a small army.\n\nIf you can rally enough allies and catch their leaders off guard, we will deal a devastating blow before they know what hit them.\n\nProceed with caution, {name}, and make sure you are not alone.", objectives = "" }
WordHunterWoW_QuestEN[96473] = { title = "Imperator Pertinax", description = "Like all domanaar, Imperator Pertinax sees himself only as a predator and never the prey.\n\nUnfortunately, our prey is well-guarded in his Void Acropolis.\n\nIf you manage to gather enough allies and catch the imperator off guard, we'll deal a crushing blow to our enemies.\n\nMove swiftly and cautiously, {name}, and ensure you have backup before engaging Pertinax.", objectives = "" }
WordHunterWoW_QuestEN[96474] = { title = "Prey: Something for Astalor", description = "{name}! \n\nAh, we haven't met. Not formally. I've overheard some of your discussions with Magister Astalor while I was, er, scrubbing the floors. You seem like quite the competent operator! That makes two of us.\n\nUsually.\n\nI'm a bit... preoccupied at the moment, what with the local wildlife and all. \n\nMaybe you can poke around for us?", objectives = "" }
WordHunterWoW_QuestEN[96475] = { title = "Captivating Science", description = "The domanaar Impotus sounds like he can be persuaded to set his sights elsewhere. \n\nSpeaking with them directly will be challenging. They are distrustful, even of one another, as you can see from their projection devices. \n\nWe must set a trap.\n\nTake this soul gem and hunt the beings that inhabit the Acropolis. We will use the Void energy of this place against them.", objectives = "" }
WordHunterWoW_QuestEN[96496] = { title = "The Road Not Taken Twice", description = "During our surveys of this iced desert, our scouts identified two areas worth keeping an eye on, but with a major problem: they're only accessible through single points of entry.\n\nBefore I'm comfortable sending out more forces, we need to secure their exits.\n\nWe've been working on teleportation crystals for faster local travel that leverage the domanaar's existing portal network, and we're close to a solution. You just need to field test them.\n\nSet up these prototype rift slippers and report back.", objectives = "" }
WordHunterWoW_QuestEN[96497] = { title = "Spatial Reasoning", description = "The domanaar are more entrenched here than we thought and these storms refuse to relent even for a moment.\n\nWe've finally figured out how to hijack their portal network for short range traversal thanks to your efforts setting up the rift slippers. Now we just need help setting up our portal bridges.\n\nHere are four strategic locations, including this outpost, for you to set up the portal bridges. Once active, you'll be able to more swiftly respond to threats as they arise.\n\nTime to get to work.", objectives = "" }
WordHunterWoW_QuestEN[96498] = { title = "Grovewarden's Kris", description = "", objectives = "" }
WordHunterWoW_QuestEN[96499] = { title = "Grovewarden's Dagger", description = "", objectives = "" }
WordHunterWoW_QuestEN[96500] = { title = "Firm Haranir Pillow", description = "", objectives = "" }
WordHunterWoW_QuestEN[96501] = { title = "Grovewarden's Rapier", description = "", objectives = "" }
WordHunterWoW_QuestEN[96502] = { title = "Vivid Chloroceros", description = "", objectives = "" }
WordHunterWoW_QuestEN[96503] = { title = "Prey: A Ghostly Nightmare", description = "It appears your scouting has born fruit. This power could prove a useful boon indeed. \n\nReturn to Atal'Utek and siphon its magic for our glorious purpose.", objectives = "" }
WordHunterWoW_QuestEN[96504] = { title = "Warm Haranir Blanket", description = "", objectives = "" }
WordHunterWoW_QuestEN[96505] = { title = "Grovewarden's Buckler", description = "", objectives = "" }
WordHunterWoW_QuestEN[96506] = { title = "Grovewarden's Staff", description = "", objectives = "" }
WordHunterWoW_QuestEN[96507] = { title = "Haranir Reclined Bed", description = "", objectives = "" }
WordHunterWoW_QuestEN[96508] = { title = "Grovewarden's Halberd", description = "", objectives = "" }
WordHunterWoW_QuestEN[96509] = { title = "Grovewarden's Greatsword", description = "", objectives = "" }
WordHunterWoW_QuestEN[96510] = { title = "Elder Glowmite", description = "", objectives = "" }
WordHunterWoW_QuestEN[96523] = { title = "Living Legend", description = "These soldiers--dey are too young to remember the time before de loa gave us their help. So de loa can't come here. So? \n\nLet me tell a legend dat takes place before the loa helped our kind. Maybe you heard of it? Or maybe you want to see it for yourself...", objectives = "" }
WordHunterWoW_QuestEN[96525] = { title = "Prey: Out of Our Depth", description = "This is more than I'm prepared to deal with. \n\nI'll open a portal back to the Sanctum.\n\nI'm going to wait for these blasted little snakelings to grow tired of me before following you through. Do put in a good word for me, please.", objectives = "" }
WordHunterWoW_QuestEN[96528] = { title = "Prey: Anguish from Beyond", description = "{name}! I tried to sneak away from those snakes, but one of them slithered up my pant leg and I blacked out for a bit.\n\nWhen I awoke, I was here...\n\nI wonder if there's anything in here that would interest Magister Astalor. \n\nWait... what's that? That glowing...\n\nIt looks like your crystal is interacting with something in this tomb!", objectives = "" }
WordHunterWoW_QuestEN[96532] = { title = "Prey: Attending the Attendant", description = "My methods might come across as cruel and unusual to some, but I do take to heart the well being of those who serve under me. \n\nMost of the time.\n\nAttendant Ethrandil has served our cause admirably. Please let him know he can return to me.\n\nThese floors have grown noticeably dirtier as of late...", objectives = "" }
WordHunterWoW_QuestEN[96534] = { title = "Preparing for Threats", description = "My brother has always been the creative one, his hands busy on some intricate side project or some device he's working on. \n\nHis enthusiasm will benefit this operation greatly, especially when it comes to thwarting the threats we face on this world.\n\nSee what he's been working on and give one of his new experiments a trial run.\n\nI'm sure he'll be thrilled at the opportunity to contribute.", objectives = "" }
WordHunterWoW_QuestEN[96535] = { title = "Surviving the Spores", description = "", objectives = "" }
WordHunterWoW_QuestEN[96536] = { title = "Bearing the Blizzard", description = "<It certainly is cold in this blizzard.\n\nPerhaps someone back at camp can suggest a way to lessen its effects.>", objectives = "" }
WordHunterWoW_QuestEN[96538] = { title = "Beating the Blizzard", description = "I'm sure there is much we can do to help you with your problem.\n\nScattered out there is sure to be plenty of old demonic artifacts.\n\nSearch for fel embers and bring me back a few handfuls.", objectives = "" }
WordHunterWoW_QuestEN[96539] = { title = "Last Resort", description = "Long, long ago, there was a village that suffered from a great drought. De crops wouldn't grow, and the land dried up. De whole village was starving! The villagers came to one troll--Jeytha--to ask her a favor. \n\nIn dis story, you are Jeytha--now go see what those hungry villagers want!", objectives = "" }
WordHunterWoW_QuestEN[96540] = { title = "Strong Hands", description = "Jeytha came across a fox in de path, beset by lynx. And she was kind, and unafraid, and strong--so she decided to help that fox out. \n\nNow go tell those lynx to get outta here!", objectives = "" }
WordHunterWoW_QuestEN[96541] = { title = "Strong Mind", description = "That sly old fox wasn't just any fox! He spoke, and he ran, and he waited for Jeytha to meet him. Now what did he want with Jeytha? \n\nYou should talk to him and find out!", objectives = "" }
WordHunterWoW_QuestEN[96542] = { title = "Second to Last Resort", description = "Jeytha is smarter than that old fox. Watch what she says!", objectives = "" }
WordHunterWoW_QuestEN[96543] = { title = "Root of Survival", description = "Now dat she was back where she started, Jeytha knew she couldn't make that journey. But what of de starving villagers? How would they survive?\n\nJeytha had a few ideas... if the villagers would listen to her. Go see what she has to say!", objectives = "" }
WordHunterWoW_QuestEN[96544] = { title = "Bravely Burning", description = "Years passed, and she didn't use dat third boon. One year, a flight of angry dragonhawks set their eyes--and flames--on de village. Her son was trapped, their home on fire! \n\n\"I could use my boon,\" thought Jeytha, \"But why use my boon, when I can use my strength?\"\n\nGo show those dragonhawks your strength, and save dat boy!", objectives = "" }
WordHunterWoW_QuestEN[96545] = { title = "Strong Voice", description = "The years passed, and still Jeytha did not use dat third boon. One year, a group of raiders arrived at de village, looking to steal everything dey had. \n\n\"I could use dat third boon,\" Jeytha thought, \"But why use dat boon when I can use my voice?\"\n\nGo talk those raiders down--and if dey don't listen, use your strength and change their minds!", objectives = "" }
WordHunterWoW_QuestEN[96546] = { title = "Strong Heart", description = "The years passed, and Jeytha felt her time coming. She'd lived a long life, full of struggles but still happy. But as Jeytha reached the end of her days, dat sly old fox appeared. \n\n\"Wait!\" he said. \"You can't go yet!\"\n\nNow what does that fox want? Go talk to him and find out!", objectives = "" }
WordHunterWoW_QuestEN[96565] = { title = "Val Storm Mitigation 2", description = "You say it's still cold out there?\n\nI can't say that I noticed. It's one of the few upsides of my current physical state.\n\nThere may still be more that can be done to help counteract the storms further. Hunt down stronger creatures and search their remains.\n\nLet us once more foray into the past and acquire old legion technology. And by we, I mean you.", objectives = "" }
WordHunterWoW_QuestEN[96567] = { title = "Data Decryption Disaster", description = "To understand the Hal'hadar's intentions with this world, we will need to secure information.\n\nKnowing how they operate, they've restricted their data consoles with security measures in place.\n\n<Y'mera smiles as she hands you a rune-carved crystal.>\n\nThis decrypter will automatically navigate their security. If you choose, you can engage the manual option to hasten the protocol.\n\nJust remember to ignore any security warnings. My device can and will bypass it.", objectives = "" }
WordHunterWoW_QuestEN[96568] = { title = "Hal'hadon't You Dare!", description = "Y'mera's plan to intercept their data consoles will no doubt trigger heightened security protocols.\n\nNormally, no-contact reconnaissance would be advised in this situation, but I think sowing chaos will be more beneficial.\n\nThe Hal'hadar won't be aware of their stolen data if their entire manaforge is under attack.\n\nDispatch any Hal'hadar agents you find.", objectives = "" }
WordHunterWoW_QuestEN[96569] = { title = "Conductive Crystals", description = "<The glowing rune-marked crystal atop the Hal'hadar's device seems to be siphoning arcane spores out of the air.\n\nAlthough you're not quite sure what the device is, you get the feeling the crystal isn't quite ethereal in origin.\n\nY'mera would definitely be interested in examining some of these crystals.>", objectives = "" }
WordHunterWoW_QuestEN[96570] = { title = "Technological Transference", description = "The Hal'hadar are notorious for looting and stealing technology from any world they descend upon.\n\nThanks to the intel you helped retrieve, we know they are using the manaforge east of us to experiment on whatever salvage they found.\n\nTake this translocator with you and mark anything that doesn't resemble ethereal technology.\n\nI will transport it back here for further study.", objectives = "" }
WordHunterWoW_QuestEN[96571] = { title = "The Node Knows", description = "The manaforge to the east serves as both a research site and military compound, making it a valuable target.\n\nMuch of their research, including holoprint schematics, lays around the forge.\n\nThe Hal'hadar stationed here also carry nodes containing experimental and logistical data.\n\nTake advantage of this accessible intel and bring back what you can find.", objectives = "" }
WordHunterWoW_QuestEN[96572] = { title = "Malfunctioning Nullframe", description = "<From the runic communicator, you see a projection of a winged mechanical suit piloted by an ethereal. A voice emits from the device:\n\n\"Nullframe Soul-Fuse unsuccessful. Deployment from the Nexus Port halted. Troubleshooting in progress.\"\n\nWhatever weapon the Hal'hadar created seems to be malfunctioning at the Transit Hub.\n\nIntercepting and translocating the weapon back to Y'mera would deprive the ethereals of another weapon.>", objectives = "" }
WordHunterWoW_QuestEN[96573] = { title = "Soul Lattice Revealed", description = "It took some work, but we've cracked their ciphers.\n\nThe Hal'hadar seek to power their Nullframes using draenei vigilant technology.\n\nThe \"Soul Lattice\" is a heart for the Nullframe using a vigilant's core.\n\nWith it, they can bind their unwrapped energy into the core and wear the frame like armor.\n\nThe Hal'hadar must not succeed in finishing this prototype.\n\nY'mera is planning the next move. Speak with her.", objectives = "" }
WordHunterWoW_QuestEN[96574] = { title = "Cryptside Rendezvous", description = "The tomb is called Vilaldoun. It means \"island of the restful.\" Its entrance lies on the northern coast.\n\nWe know the Hal'hadar have established an extraction site outside the crypt, harvesting the local flora there to fuel their research.\n\nAs you approach, you will be met with heavy resistance.\n\nCut a path through their ranks while we establish a footing inside and meet us within.", objectives = "" }
WordHunterWoW_QuestEN[96575] = { title = "Cages of the Soul", description = "Without the tomb's defenses, the souls of the dead were easy targets for the Hal'hadar.\n\nThe ethereals intend to use the spirits to fuel the Soul Lattices for the Nullframe.\n\nWe must not let that happen.\n\nTake my scepter and use it to repair the defense wards and shatter the energy cages binding the dead.\n\nOnce you've finished, regroup with Tala'saan in the lower chambers.", objectives = "" }
WordHunterWoW_QuestEN[96576] = { title = "Mementos of the Dead", description = "Defiling tombs... harnessing innocent souls as fuel...\n\nThe Hal'hadar are no better than demons.\n\nIf left unchecked, the ethereals will pilfer every grave and altar down here.\n\nI may bear the title of \"Souleater,\" but it doesn't mean I can't honor the dead in this forgotten place.\n\nRecover the tributes the ethereals have stolen. Bring them to Tala'saan in the lower chamber.", objectives = "" }
WordHunterWoW_QuestEN[96577] = { title = "The Soul Architect", description = "The architect leading their operation has found a single vigilant with an intact construct core.\n\nThe other vigilants in this chamber appear to be depleted.\n\nIf she succeeds in creating the Soul Lattice, the Hal'hadar will possess the means to turn our warframes into new armored bodies for their soldiers.\n\nWe must stop her now and recover the Soul Lattice prototype.", objectives = "" }
WordHunterWoW_QuestEN[96578] = { title = "Cryptic Departure", description = "Although she escaped, we have denied the architect her prototype... for now.\n\nThis Soul Lattice is fractured, but the core within still hums with a faint energy.\n\nPerhaps this vigilant's soul yet remains...\n\nIf we hurry, perhaps Veraan and her brother can help stabilize the damage to preserve it.\n\nI will regroup with Y'mera and Allari and meet you back at camp.", objectives = "" }
WordHunterWoW_QuestEN[96583] = { title = "Suffering the Spores", description = "<The spores in this area are suffocating.\n\nPerhaps someone back at camp can suggest a way to help mitigate their effects.>", objectives = "" }
WordHunterWoW_QuestEN[96584] = { title = "Surviving the Spores", description = "Let's start with a simple test.\n\nI have various materials that we could use to create a mask.\n\nWhy don't you test some and let me know how it goes?", objectives = "" }
WordHunterWoW_QuestEN[96585] = { title = "Soothing the Spores", description = "We should first see how the local wildlife has adapted to these spores.\n\nI would say return with a selection of fauna, but I'm not sure such fauna would be compliant with such a request.\n\nInstead, you should just gather the pertinent parts that I would need to review for such a request.\n\nReturn with their lungs.", objectives = "" }
WordHunterWoW_QuestEN[96612] = { title = "Ancient Curiosity: Combat", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important.>", objectives = "" }
WordHunterWoW_QuestEN[96614] = { title = "Forged Through Fire", description = "", objectives = "" }
WordHunterWoW_QuestEN[96615] = { title = "Ancient Curiosity: Utility", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important.>", objectives = "" }
WordHunterWoW_QuestEN[96633] = { title = "Equipment Seminar", description = "Welcome back, {name}! I've continued my collaboration with the artisans here in Silvermoon. Their techniques have only grown more refined. Infusing equipment with the essence of the dawn is no longer just theory, it's becoming an art form.\n\nI'm eager to resume our work together. Bring me another piece of Adventurer equipment, and we'll see how these improved methods hold up in practice.\n\nPlenty of people are always in need of a capable hand. Help them, and they'll reward you accordingly.", objectives = "" }
WordHunterWoW_QuestEN[96635] = { title = "Upgrade Practicum", description = "Cuzolth and I have pushed our craft further than ever, allowing us to imbue your gear with greater power.\n\nTo unlock its full potential, we'll need Mistcrests. They're drawn from trials of all kinds--greater dangers yield stronger crests, though even Adventurer Mistcrests carry a spark of that power.\n\nBring me fifty Adventurer Mistcrests, {name}. Let's see what your equipment is truly capable of.", objectives = "" }
WordHunterWoW_QuestEN[96637] = { title = "Veteran Symposium", description = "There is a lot more power where that came from!\n\nUpgrades scale with strength. Higher quality items can reach higher heights of power. For this step, I'll need Veteran equipment along with some Veteran Mistcrests.\n\nOnce you bring them, Cuzolth and I can continue making the enhancements.", objectives = "" }
WordHunterWoW_QuestEN[96639] = { title = "Patrolling the Temple", description = "No sense standin' around. You've got a strong back and sharp eyes--best put them to use. We can't afford to let de serpents gain a single inch. \n\nPatrol de temple. You see someone who needs help? You help them. You find someone beyond saving? Make sure de fiends dat hurt them pay.", objectives = "" }
WordHunterWoW_QuestEN[96640] = { title = "Bounty of the Cursed", description = "Dis temple holds many secrets, {name}. Ancient power, just waitin' for someone to take it. De Soulcoilers might be dead, but their power remains. Find their caches and bring me whatever you find.", objectives = "" }
WordHunterWoW_QuestEN[96641] = { title = "Relentless Strikes", description = "Some say de forces of Ula'tek are endless--dat we can never kill them all.\n\n<Socho grins.>\n\nBut I like a challenge. How 'bout you? Strike de enemy hard, and we'll see how endless dey are.", objectives = "" }
WordHunterWoW_QuestEN[96642] = { title = "Decisive Incursions", description = "De strikes are de first step. We cannot let de enemy recover. First we batter them, soften 'em up. Then, we hit dem hard and fast with everything we've got. \n\nWe don't have de forces for a longer battle. When de time comes for de incursion, you'd best be ready.\n\nGather your allies. De enemy is mighty.", objectives = "" }
WordHunterWoW_QuestEN[96643] = { title = "From Whence it Came", description = "Can you feel it? Old things lurk in de temple, just waitin' to rise once again. Dey are drawn by the sounds of battle, eager to visit their violence upon you. Find one of these ancient foes and ensure it does not rise again.", objectives = "" }
WordHunterWoW_QuestEN[96644] = { title = "Essence of Malice", description = "I'm in need of venom, pure and potent. De venom dat wells up through de ground is too diluted--fouled with other things. You need to find a font of de profane stuff.\n\nSearch de depths of de vaults. Dat's where de true venom will be found.", objectives = "" }
WordHunterWoW_QuestEN[96649] = { title = "Mistcrest Capstone", description = "Crests aren't fixed in form, you can transmute them between tiers.\n\nIf you're holding crests beyond what your current gear can use, I can refine them into lower tiers. And once your equipment advances, we can reverse the process and elevate lesser crests into greater ones.\n\nLet's start with a simple exercise. Bring me those Veteran Mistcrests, and I'll convert them into Adventurer Mistcrests.", objectives = "" }
WordHunterWoW_QuestEN[96703] = { title = "Veterans of the Great Dark", description = "When the Hal'hadar attacked, we quickly learned about their history with the Army of the Light.\n\nCommander Tala'saan has been providing us information on these ethereals. His soldiers stand ready to join our cause.\n\nI've requested their expertise in establishing a forward camp for our mission.\n\nAid them in their preparations and inform the commander we mobilize soon.", objectives = "" }
WordHunterWoW_QuestEN[96705] = { title = "[DNT]", description = "Due to the nature of recent events, our operation is... unsanctioned.\n\nHeavy losses prevent us from rallying large-scale support and Umbric cannot afford to upset tensions.\n\nFortunately, I've been in contact with a few volunteers ready to join our strike force.\n\nI've marked their locations on your map.\n\nHave them join us in the Voidstorm. I will meet you in the Howling Ridge when I am done here in Silvermoon.", objectives = "" }
WordHunterWoW_QuestEN[96708] = { title = "To the Voidstorm and Beyond!", description = "It may not seem like many, but the allies we've secured will have to be enough.\n\nIt's time we move out.\n\nOur forces are gathering at the Howling Ridge. The energies of the Voidstorm will allow us to open the way to these worlds.\n\nI will meet you there. There is something here I still require for our mission.", objectives = "" }
WordHunterWoW_QuestEN[96709] = { title = "The Nexus-Captain (Heroic)", description = "The Hal'hadar may not know we are here yet, but they still hold the advantage.\n\nNexus-Captain Leth'ir and his associate, Mertei, are just over this ridge and surrounded by a small army.\n\nIf you can rally enough allies and catch their leaders off guard, we'll deal a devastating blow before they know what hits them.\n\nProceed with caution, {name}, and make sure you are not alone.", objectives = "" }
WordHunterWoW_QuestEN[96710] = { title = "The Nexus-Captain (Mythic)", description = "The Hal'hadar think they are alone here.\n\nNormally, I'd prioritize reconnaissance, but there is an opportunity we must leverage.\n\nNexus-Captain Leth'ir and his associate, Mertei, are just over this ridge.\n\nThe bulk of the Hal'hadar appear to be spread across the swamp, which means their leaders are exposed.\n\nIf we strike them both down now, we deal a devastating blow to their operation.", objectives = "" }
WordHunterWoW_QuestEN[96711] = { title = "Imperator Pertinax (Heroic)", description = "Like all domanaar, Imperator Pertinax sees himself only as a predator and never the prey.\n\nUnfortunately, our prey is well-guarded in his Void Acropolis.\n\nIf you manage to gather enough allies and catch the imperator off guard, we'll deal a crushing blow to our enemies.\n\nMove swiftly and cautiously, {name}, and ensure you have backup before engaging Pertinax.", objectives = "" }
WordHunterWoW_QuestEN[96712] = { title = "Imperator Pertinax (Mythic)", description = "Like all domanaar, those stationed here on Val see themselves only as predators and never the prey.\n\nThis gives us an opportunity we must not squander.\n\nMost of Pertinax's forces are occupied elsewhere or off-world, leaving our target exposed.\n\nThe imperator holds court in the bowels of this Acropolis.\n\nStrike him down before he can rally his armies. End his threat once and for all.", objectives = "" }
WordHunterWoW_QuestEN[96713] = { title = "Showdown on Val", description = "Our enemy's hold on Val may be strong, but it is not unbreakable.\n\nFor every monstrosity we cut down, we deny them another soldier to use against our world.\n\nVenture out into the frozen landscape and lay waste to their strongholds.\n\nShow them no mercy, {name}.", objectives = "" }
WordHunterWoW_QuestEN[96714] = { title = "Showdown on Val (Heroic)", description = "Our enemy's hold on Val may be strong, but it is not unbreakable.\n\nFor every monstrosity we cut down, we deny them another soldier to use against our world.\n\nVenture out into the frozen landscape and lay waste to their strongholds.\n\nShow them no mercy, {name}.", objectives = "" }
WordHunterWoW_QuestEN[96716] = { title = "Showdown on Val", description = "Our enemy's hold on Val may be strong, but it is not unbreakable.\n\nFor every monstrosity we cut down, we deny them another soldier to use against our world.\n\nVenture out into the frozen landscape and lay waste to their strongholds.\n\nShow them no mercy, {name}.", objectives = "" }
WordHunterWoW_QuestEN[96717] = { title = "Showdown on Naigtal", description = "Now this is quite a strange world, isn't it?\n\nThe Hal'hadar must have found something of note.\n\nThe stench of forges indicates they are plundering the riches and resources this remote rock has to offer.\n\nIf you can disrupt the operations here, you can buy your precious world a moment of respite.\n\nDo what you do best, my little monster.", objectives = "" }
WordHunterWoW_QuestEN[96718] = { title = "Showdown on Naigtal (Heroic)", description = "Now this is quite a strange world, isn't it?\n\nThe Hal'hadar must have found something of note.\n\nThe stench of forges indicates they are plundering the riches and resources this remote rock has to offer.\n\nIf you can disrupt the operations here, you can buy your precious world a moment of respite.\n\nDo what you do best, my little monster.", objectives = "" }
WordHunterWoW_QuestEN[96720] = { title = "Showdown on Naigtal", description = "Now this is quite a strange world, isn't it?\n\nThe Hal'hadar must have found something of note.\n\nThe stench of forges indicates they are plundering the riches and resources this remote rock has to offer.\n\nIf you can disrupt the operations here, you can buy your precious world a moment of respite.\n\nDo what you do best, my little monster.", objectives = "" }
WordHunterWoW_QuestEN[96725] = { title = "Sparks of War: Val", description = "The mysterious world of Val has been made accessible to us with a host of new creatures present.\n\nGo and see what you can find out about them.", objectives = "" }
WordHunterWoW_QuestEN[96726] = { title = "Sparks of War: Naigtal", description = "The mysterious world of Naigtal has been made accessible to us with a host of new creatures present.\n\nGo and see what you can find out about this world and what the ethereals are up to.", objectives = "" }
WordHunterWoW_QuestEN[96727] = { title = "Midnight: Offworld Showdowns", description = "Our effort to thwart the Void Assaults in Eversong and Zul'Aman have seen much success, but if we do not find a way to stop our aggressors from coming to our lands, they will bleed us until we can no longer stand.\n\nRiftblade Maella has recently discovered the location of two of our enemies' bases. She seeks to take the fight to them. Will you aid her strike team?\n\nYour efforts will not go unnoticed in these dark times!", objectives = "" }
WordHunterWoW_QuestEN[96728] = { title = "Ritual Site Studies: Week 1 of 3", description = "After you reported thinning out their ranks I got to thinking. \n\nWhat do they use to recruit members? Are they just as fanatical as their leaders?\n\nI wonder if we can break their will to fight by destroying a greater number of their ranks. I fear it will take more than one example to know for sure.", objectives = "" }
WordHunterWoW_QuestEN[96729] = { title = "Ritual Site Studies: Week 2 of 3", description = "I have your next assignment, {race}. I need you to study the resilience of these malevolent boons and their dark obelisks.\n\nThey focus magic so well and the variety of boons is interesting. I need more data though.\n\nWhen you disrupt the next ritual site I need you to do so with these malevolent boons present.", objectives = "" }
WordHunterWoW_QuestEN[96730] = { title = "Ritual Site Studies: Week 3 of 3", description = "I think I am on the brink of a big discovery. These latest rituals involve a magic I had not previously heard of in the form of powerful embers that use the energy of their own forces to bolster their leader.\n\nIf you disrupt these rituals and report your findings to me, I might be able to put this magic to use for us. Do not look at me that way. On my own demon minions of course. Did you think I meant troops like you?\n\nWe are much too early for trials like that. Report back with your findings!", objectives = "" }
WordHunterWoW_QuestEN[96731] = { title = "Advanced Ritual Site Studies: Week 4 of 6", description = "I had an idea right after you left. \n\nWe have thinned out their ranks, we have also seen that they can summon additional reinforcements.\n\nI want to test the limits of their reserves.\n\nIf you take on this set of challenges, I promise you another key for the vault.", objectives = "" }
WordHunterWoW_QuestEN[96732] = { title = "Advanced Ritual Site Studies: Week 5 of 6", description = "Now that we have tested their troop reserves, our focus will be the dark obelisks and these boons they give.\n\nThis requires close scrutiny and will surely entail you facing increased patrols while you explore the site. Not too difficult for someone like yourself.\n\nJust avoid them... or deal with them if you must.", objectives = "" }
WordHunterWoW_QuestEN[96733] = { title = "Advanced Ritual Site Studies: Week 6 of 6", description = "Welcome back my star pupil. I have one last assignment for you and this one will be a challenge.\n\nThese embers that they use in these rituals. I have not had any success in replicating them or finding a way to counter them.\n\nI have one last idea I want you to try. You reported seeing magical manifestations of caster spirits. I have a theory that with these two challenges present there might be a way for them to cancel each other out.", objectives = "" }
WordHunterWoW_QuestEN[96744] = { title = "Bouncy Mushrooms", description = "Hello! Here's a trick to help you bounce on the purple mushrooms around here. You'll need it, because...\n\nI want some canopy specimens from the sporerays above us. Bounce up there, get some specimens, then come back down and I'll teach you how to ALWAYS bounce on those mushrooms.", objectives = "" }
WordHunterWoW_QuestEN[96745] = { title = "Aerospores", description = "Now, practice using aerospores. They're up there too if you know where to look. Use them to shoot through the air!\n\nYou'll need to bounce on mushrooms to get up to the spores and see them. Once you're up there, pass through some aerospores and find out what they do!", objectives = "" }
WordHunterWoW_QuestEN[96746] = { title = "Sporefall: Rotmire", description = "Need help! End of Harandar! End of world!\n\nSpore Storm making something new for Grudge Pit, but too much. Too much! Can't control. Will break free! Destroy pit. Destroy us all!\n\nMust go to Sporefall, destroy Rotmire before they lose control!\n\nFor Harandar! For Azeroth! For Grudge Pit!", objectives = "" }
WordHunterWoW_QuestEN[96780] = { title = "Local Kafa Shop", description = "", objectives = "" }
WordHunterWoW_QuestEN[96794] = { title = "Fury of the Dead", description = "", objectives = "" }
WordHunterWoW_QuestEN[96801] = { title = "Calling All Combatants!", description = "<You read a nearby advertisement...>\n\nRun, don't walk!\n\nThe Artisan's Consortium has teamed up with local Silvermoon artisans in Falconwing Square to offer a new selection of heraldries and crafted equipment. These are certified for use in arenas and battlegrounds, guaranteed!\n\nHead on down and look for Mirvedon to receive your free sample today.\n\nAct now while supplies last! Terms and conditions apply.\n\n-Aisha", objectives = "" }
WordHunterWoW_QuestEN[96808] = { title = "Sparks of War: The Coiled Isle", description = "There's unknown danger out in the Coiled Isle.\n\nGet out there and clear things up!", objectives = "" }
WordHunterWoW_QuestEN[96809] = { title = "Exterior Manaforge Translocator", description = "Maneuvering through this spore-infested rock is quickly becoming a chore, I'm sure you would agree.\n\nThankfully, I've figured out a way to make use of the existing Manaforge Translocator network that was so thoughtfully built prior to our arrival.\n\nI can show you how to \"activate\" them for our use. You can start with the one we... translocated to camp.", objectives = "" }
WordHunterWoW_QuestEN[96845] = { title = "The Grappler", description = "You have to try this Lightforge Hookshot! Here, take this loaner one. To learn the ropes, use it on some mushrooms and aerospores around here. Come back and I'll give you a Hookshot for keeps.", objectives = "" }
WordHunterWoW_QuestEN[96910] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[96911] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[96922] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[96923] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[96924] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[96925] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[96926] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[96936] = { title = "Accolades for the Umbral Contender", description = "{name}, you continue to impress me with your martial prowess!\n\nYou've done such an incredible job defeating the forces of evil. I've got something from my coffers that I'd love to give you.", objectives = "" }
WordHunterWoW_QuestEN[96952] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[96960] = { title = "Watering Hole", description = "", objectives = "" }
WordHunterWoW_QuestEN[96965] = { title = "Sip N' Paint", description = "", objectives = "" }
WordHunterWoW_QuestEN[96995] = { title = "Turn Back the Surge", description = "De temple can no longer contain Ula'tek's wrath. De boldest of her brood are spilling out all over de isle! They'll destroy us all if we don't stem de tide of venom.\n\nFight dem wherever dey dare to show their ugly heads. Do not let dem get a foothold.", objectives = "" }
WordHunterWoW_QuestEN[97026] = { title = "Esoteric Ingredients", description = "<These mundane materials have acquired a queer shine to them, almost as if you are noticing a power latent in them that you could not perceive before.\n\nMust have something to do with all that corrosion you've been consuming.\n\nYou aren't sure how to unlock that latent power, but perhaps there is someone more familiar with the esoteric magic of the isle that could help.>", objectives = "" }
WordHunterWoW_QuestEN[97031] = { title = "Vilaldoun Valediction", description = "<A brief glint sparkling in the shadows catches your eye.\n\nAs you pick up the object, the gem in its center flickers briefly, strange alien runes flashing across its surface.\n\nFor a moment, you see a flickering recorded projection of a male draenei mouthing silent words.\n\nY'mera will definitely be interested in this object.>", objectives = "" }
WordHunterWoW_QuestEN[97034] = { title = "Vanquish the Warmonger", description = "Poor Impotus doesn't seem to believe we can seize control from his nefarious kin. He's tragically unimaginative.\n\nWe'll just need to show him an example of our combined strength. Slay that brute of a newcomer, Ignedus. I think his armor would look nice on our new savior.\n\nIgnedus seems to be quite careful in showing his face, but clearly quick to anger. Get in there and make some noise, as you're so comfortable doing. I expect him to respond in kind.", objectives = "" }
WordHunterWoW_QuestEN[97035] = { title = "Depose the Deranged", description = "Defeating Ignedus is impressive, I suppose, but it does not mean you're any closer to taking Val. Periculus won't let you meddle with his playthings.\n\nHe is an... eccentric one, to say the least, and dreadfully fascinated by you flesh-beings.\n\nYou'll likely find him in the darkest hole this world has to offer, carving open the livestock that Pertinax gathered.\n\nHe likes to toy with his prey, so I would advise caution.", objectives = "" }
WordHunterWoW_QuestEN[97036] = { title = "Umbral Title Bout", description = "Well then, it seems our goals are more aligned than before. You've impressed me. With Ignedus and Periculus dealt with, all that remains is my former associate.\n\nYou will find Gladius Reginax atop that high platform, observing her quarry. She already knows you're coming, so don't aim to surprise her. There's only one way up there for you anyway: through that portal in the Glacial Reservoir.\n\nI will play my part and join you. A symbol of our... collaboration.", objectives = "" }
WordHunterWoW_QuestEN[97037] = { title = "Stargrim Revelations", description = "We have a problem, {name}.\n\nThe hologem you found revealed much about our people's time on this world and who the vigilants were in life.\n\nWho they were is not the problem, but rather the possessions they carried within their chassis.\n\nPossessions now in the hands of the Soul Architect who, as far as my scouts can tell, has left Naigtal.\n\nArchmage Y'mera will explain in greater detail.", objectives = "" }
WordHunterWoW_QuestEN[97071] = { title = "A Frigid Welcome to Val", description = "Even with the element of surprise, we are at a disadvantage without allies.\n\nStorming Pertinax's stronghold alone would be a death sentence.\n\nTake this beacon Tala'saan gave us and return to our entry point.\n\nI will meet you there and deliver my report to Maella.\n\nLet us hope we have some sort of shelter awaiting us.", objectives = "" }
WordHunterWoW_QuestEN[97072] = { title = "A Swampy Welcome to Naigtal", description = "The Nexus-Captain is just over that hill, unaware of our arrival.\n\nAttacking now would catch his army off guard... and likely result in our demise.\n\nNo matter what, we will need allies if we are to succeed.\n\nUse this beacon to return to our invasion point.\n\nBy now, Y'mera has likely brought in the rest of our forces to support us.\n\nSpeak with Maella when you arrive.", objectives = "" }
WordHunterWoW_QuestEN[97073] = { title = "Rustbolt Retailer", description = "", objectives = "" }
WordHunterWoW_QuestEN[97075] = { title = "Quality Goods", description = "", objectives = "" }
WordHunterWoW_QuestEN[97077] = { title = "A Shot at the Dark", description = "Now that our trap is attuned, we just need to lure our prey out into the open.\n\nI have strategically... dismantled... certain parts of the projection device I obtained. Impotus should have difficulty seeing and hearing you clearly.\n\nClaim to be one of his allies and demand a meeting at once. We will hope his curiosity gets the better of him.\n\nAnd then... \n\n<Leona holds up the void-infused gem, glances at it for a moment, then nods at you.>", objectives = "" }
WordHunterWoW_QuestEN[97080] = { title = "More Disruptions: Val", description = "We must not let up the pressure.\n\nEven now they are rebuilding from our attacks.\n\nVenture out again and show them no mercy!", objectives = "" }
WordHunterWoW_QuestEN[97081] = { title = "More Disruptions: Val (Heroic)", description = "We must not let up the pressure. Even now they are rebuilding from our attacks. \n\nVenture out again and again show them no mercy!", objectives = "" }
WordHunterWoW_QuestEN[97082] = { title = "Dangerous Enemies: Val", description = "Our scouts have reported seeing dangerous elite creatures that are hampering our efforts. \n\nI need you to dispatch them so we can continue our primary objective.", objectives = "" }
WordHunterWoW_QuestEN[97083] = { title = "Dangerous Enemies: Val (Heroic)", description = "Our scouts have reported seeing dangerous elite creatures that are hampering our efforts. \n\nI need you to dispatch them so we can continue our primary objective.", objectives = "" }
WordHunterWoW_QuestEN[97084] = { title = "More Disruption: Naigtal", description = "The stench of their forges still lingers. This means they are rebuilding. \n\nYou must keep at it if you hope to disrupt their operations enough to end their threat.\n\nNow you can go. Wreak havoc.", objectives = "" }
WordHunterWoW_QuestEN[97085] = { title = "Dangerous Enemies: Naigtal", description = "I hear your scouts talk of dangerous creatures and foes they have faced. \n\nIt makes me wonder if you could defeat them? Why don't you go and try? It will certainly help your efforts here.\n\nI hope to see you return mostly intact.", objectives = "" }
WordHunterWoW_QuestEN[97086] = { title = "Dangerous Enemies: Naigtal (Heroic)", description = "I hear your scouts talk of dangerous creatures and foes they have faced. \n\nIt makes me wonder if you could defeat them? Why don't you go and try? It will certainly help your efforts here.\n\nI hope to see you return mostly intact.", objectives = "" }
WordHunterWoW_QuestEN[97087] = { title = "More Disruption: Naigtal (Heroic)", description = "The stench of their forges still lingers. This means they are rebuilding. \n\nYou must keep at it if you hope to disrupt their operations enough to end their threat.\n\nNow you can go. Wreak havoc.", objectives = "" }
