WordHunterWoW_QuestEN[97141] = { title = "Spoils of the Vaults", description = "It takes de whole of our strength to keep de forces of Ula'tek from overwhelming de isle. Dat battle is waged inside the Vault of Ula'tek, against the endless tide of her children. Kill one, and two more will slither out of de venom.\n\nVenture in, {name}, and lend your power to our weary fighters. Who knows? You may even find something valuable in dat ancient, cursed place.", objectives = "" }
