WordHunterWoW_QuestEN[97215] = { title = "A Secondary Strike", description = "We have struck a major blow against our enemies. Still, they continue their assaults.\n\nDecimus and my riftwardens have targeted another world from which they launch these attacks.\n\nThe bulk of our forces have temporarily withdrawn to the Voidstorm so that we may begin our assault on this second world.\n\nOur strike team awaits us at the Howling Ridge.", objectives = "" }
WordHunterWoW_QuestEN[97256] = { title = "Knocking Off the Top (Heroic)", description = "Even the most ruthless of creatures falter when they see their greatest champions crumble to ash.\n\nRemind our enemies here just how quickly their leaders fall!\n\nLet them know just how unrelenting and vicious you monsters of Azeroth really are! Bring me the Void Commander's Emblems and I will reward you accordingly.", objectives = "" }
WordHunterWoW_QuestEN[97321] = { title = "Slithering Spoils", description = "I've got good news and bad news.\n\nBad is that all those curios we dug up together? Melted.\n\nGood news? I've found some very interesting new poisons to work with.\n\nBut let me explain what happened...", objectives = "" }
WordHunterWoW_QuestEN[97381] = { title = "A Curated Gift", description = "I have watched the effort and care you take with the other mortals of your neighborhood, here in Founder's Point. This ceaseless labor on their behalf is the sort of behavior that I encourage. There's no profit to be had for you, but that isn't a driving concern for the best of your kind.\n\nIn recognition of your efforts and status, I offer you a gift. This small device contains a piece of decor for you to place in your home. I will have another for you next week.", objectives = "" }
WordHunterWoW_QuestEN[97382] = { title = "Counter-Curse Bounty", description = "Every part of dis isle is cursed, {name}. When de curse of Ula'tek coalesces into a fight, dat is when it is most important to strike back. We need all de help we can get keeping it at bay.\n\nYou look strong... but you'll need better equipment if you want to stay alive.\n\nDefeat the leader of one of dese surges, and then we can discuss a reward.", objectives = "" }
WordHunterWoW_QuestEN[97383] = { title = "Spirit Corrosion", description = "Our scouts found dis relic in one of da crypts. Maybe Er'inye knows what to do with it?", objectives = "" }
WordHunterWoW_QuestEN[97384] = { title = "More Spirit Corrosion", description = "One of those soulcoilers was carrying dis gem. You should show it to Er'inye.", objectives = "" }
WordHunterWoW_QuestEN[97454] = { title = "Seasonal Refresher: Midnight", description = "Since the opening of the Coiling Isles, things have started to get interesting again in delves.\n\nSee if our dear hosts have anything they can spare for those of us actually risking our necks and check the Delver's Guide for any updates.\n\nA quick refresher never hurt anyone.", objectives = "" }
WordHunterWoW_QuestEN[97455] = { title = "Call of the Bell", description = "<Years beneath the waves should have erased its details, yet the bell remains remarkably well-preserved. Whatever purpose it once served, the runes carved into it were clearly meant to endure.\n\nA sense of foreboding comes over you as you consider ringing it. Maybe not.\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97457] = { title = "Fits Like a Glove", description = "<These appear to be a large pair of hand bones, that someone has hollowed out and claimed to be gauntlets.\n\nIt's a good thing you're already wearing gauntlets, or you'd be tempted to try them on.\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97458] = { title = "Tackled and Boxed", description = "<An endless supply of fishing gear would be a dream for most anglers. The fact that this tacklebox screams whenever it is opened likely explains why it ended up at the bottom of the sea.\n\nAfter spending enough time with it, the screams start to echo without needing to open it at all.\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97459] = { title = "Something Smelly", description = "<The inscription promises to not only attract spirits, but to whip them into a violent frenzy if enough is burned. That can't end well.\n\nStill, it does smell nice.\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97460] = { title = "Lightly Salted", description = "<The pouch is unremarkable, but its history may not be. Ritual salts have long been used to call upon ancestors, spirits, and powers beyond the mortal world.\n\nThis salt is extra-salty, having been in the ocean. Perhaps that makes it extra-potent?\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97461] = { title = "Cursed Fishing 101", description = "<Most fishing manuals concern themselves with bait, weather, and patience. This weathered tome boasts lessons on hexing one's fishing rivals and communing with the deep.\n\nYou sense you are wading into dangerous waters.\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97462] = { title = "Rocky Shores", description = "<This faceted ore hums with an unsettling energy. Whether it is valued more for its practical uses or its strange properties, you cannot say.\n\nYou feel compelled to lick it, though you know you shouldn't.\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97463] = { title = "Just a Normal Knife", description = "<This blade shows no signs of battle wear, only careful maintenance. Its purpose was clearly ceremonial, but for what ceremony?\n\nThe red gleam to the metal gives you a clue.\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97464] = { title = "A Dash of Poison", description = "<The glass is thick and reinforced, suggesting the contents were considered dangerous--or valuable. The verdant liquid within glimmers as it shifts in the vial.\n\nYou think you smell something acrid and noxious about it. But it could be that this whole isle smells acrid and noxious.\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97465] = { title = "The Intended Way to Fish", description = "<It's a spear. The fishing rod is a spear.\n\nSluggs probably knows something about this item.>", objectives = "" }
WordHunterWoW_QuestEN[97482] = { title = "Fangs for the Memories", description = "That snake monstrosity was vicious, with venom potent enough to burn through stone.\n\nWe'll want to make sure we get our hands on the best gear we can before we think about taking it on.\n\nI've got some ideas about turning that venom to our own ends, though, so we can hit the ground running.", objectives = "" }
WordHunterWoW_QuestEN[97521] = { title = "A Turtle Bade It to the Water", description = "Greetings, settler!\n\nThere's a cove off the coast that my people have turned into a tavern. It's open year round, but we like to help drum up some business for them whenever we come to town. Would you care to help?", objectives = "" }
WordHunterWoW_QuestEN[97535] = { title = "A Bargain You Won't Refuse", description = "<A voice hisses in your mind.>\n\nAm I to be another victim in your pointless conquest? I wonder... will you skin me alive and boil me in a stew? Or simply leave me to rot on a pile of your forgotten excess?\n\nWhat if I can offer you something... better? Something... delicious. The Children of Ula'tek are a blight on this world. On this we agree. Bring me proof of their demise.", objectives = "" }
WordHunterWoW_QuestEN[97557] = { title = "Tailing the Tlhapi", description = "Toxic Tlhapi. Nasty little fish.\n\nEverything's wrong about them, from their big, buggy eyes to their sweet, succulent meat...\n\n<Gills clears their throat.>\n\nNot to mention the toxicity. The seas would be much better without them fouling things up.", objectives = "" }
WordHunterWoW_QuestEN[97559] = { title = "The Familiar Taste of Poison", description = "Surely by now even you understand the threat Ula'tek poses, yes? Her wretched power oozes forth time and time again.\n\nIf I am to do my part, I will need proof of your devotion to our... agreement, shall we call it? When next her acolytes call forth their twisted mongrels, slay them and collect their remains.", objectives = "" }
WordHunterWoW_QuestEN[97562] = { title = "Culling the Killifish", description = "Spotted Killifish. Grotesque little creatures.\n\nThe little demons swarm like insects, washing up on shores in such horrific numbers that it would take several meals to devour them all.\n\n<Gills' belly burbles audibly.>\n\nYou can do your part by collecting some for me, ridding the waters of their foul presence.", objectives = "" }
WordHunterWoW_QuestEN[97565] = { title = "Tipping the Scaled", description = "<The wretched things you gathered briefly wink out of existence, returning in the same breath as one object.>\n\nGo on, take it. Carry it to the Vaults of Atal'Utek. Affix it to that dismal rod of yours and cast it into the fetid pools to draw out one of Ula'tek's pets. You do have the skill to fish anywhere, don't you?", objectives = "" }
WordHunterWoW_QuestEN[97571] = { title = "Dogging the Darters", description = "Dirty Darters. Ghoulish little buggers.\n\nThe way they flit about the water is so unnerving, so disquieting, one can't help but imagine them darting right down one's gullet...\n\n<Gills coughs rather loudly>\n\nYou can do your part by collecting some for me, ridding the waters of their foul presence.", objectives = "" }
WordHunterWoW_QuestEN[97616] = { title = "Corrosive Gifts: Corrosive Power", description = "<You feel a change in the air as you take this ancient volume into your hands.\n\nThough it prickles and burns your skin, your mind radiates with thoughts of the power it contains and the peril it represents.\n\nYou must know more.\n\nThere is only one place on the isle profane enough for this tome. In your mind's eye, you glimpse the Altar of Corrosion.>", objectives = "" }
